/// Create a structured JSON error response.
pub(crate) fn json_error(
    status: StatusCode,
    message: impl Into<String>,
) -> (StatusCode, Json<ApiError>) {
    (
        status,
        Json(ApiError {
            success: false,
            error: message.into(),
            code: None,
            retryable: None,
        }),
    )
}

pub(crate) fn coded_json_error(
    status: StatusCode,
    code: impl Into<String>,
    message: impl Into<String>,
    retryable: bool,
) -> (StatusCode, Json<ApiError>) {
    (
        status,
        Json(ApiError {
            success: false,
            error: message.into(),
            code: Some(code.into()),
            retryable: Some(retryable),
        }),
    )
}

