    #[test]
    fn session_detail_response_emits_etag_and_honors_if_none_match() {
        let detail = SessionDetail {
            id: "s".into(),
            name: "n".into(),
            working_dir: PathBuf::from("."),
            created_at: 0,
            updated_at: 0,
            message_count: 0,
            revision: 0,
            caps: session_capabilities(),
            cursor: SessionCursor {
                oldest_seq: None,
                total: 0,
            },
            offset: 0,
            pinned_user_index: None,
            turns: Vec::new(),
            input_cursor: 0,
            messages: Vec::new(),
            preferred_model: None,
            approval_mode: None,
            reasoning_effort: None,
            thinking_budget: None,
            token_usage: None,
            origin: jeikcode_capabilities::session::SessionOrigin::Manual,
            todos: Vec::new(),
            todos_revision: 0,
        };
        let first = session_detail_response(&HeaderMap::new(), detail.clone());
        assert_eq!(first.status(), StatusCode::OK);
        let etag = first
            .headers()
            .get(axum::http::header::ETAG)
            .unwrap()
            .to_str()
            .unwrap()
            .to_string();
        let mut request_headers = HeaderMap::new();
        request_headers.insert(
            axum::http::header::IF_NONE_MATCH,
            HeaderValue::from_str(&etag).unwrap(),
        );
        let second = session_detail_response(&request_headers, detail);
        assert_eq!(second.status(), StatusCode::NOT_MODIFIED);
        assert_eq!(
            second
                .headers()
                .get(axum::http::header::ETAG)
                .unwrap()
                .to_str()
                .unwrap(),
            etag
        );
    }

