#[cfg(test)]
mod chat_replay_tests {
    use super::*;

    #[test]
    fn part_rev_is_monotonic_within_a_part_and_resets_on_a_new_part() {
        let mut projector = ChatRuntimeProjector::default();
        projector.current_message_id = Some("m-rev".into());

        let first = projector.next_part_stamp("text");
        assert_eq!(first.2, Some(1));
        assert_eq!(first.3, Some(1));
        let second = projector.next_part_stamp("text");
        assert_eq!(second.2, Some(1), "same part keeps part_seq");
        assert_eq!(second.3, Some(2), "same part bumps part_rev");

        let reasoning = projector.next_part_stamp("reasoning");
        assert_eq!(reasoning.2, Some(2), "kind change opens a new part");
        assert_eq!(reasoning.3, Some(1), "new part starts at revision 1");

        let text_after_reasoning = projector.next_part_stamp("text");
        assert_eq!(text_after_reasoning.2, Some(3));
        assert_eq!(text_after_reasoning.3, Some(1));

        projector.end_streaming_part();
        let after_tool = projector.next_part_stamp("text");
        assert_eq!(after_tool.2, Some(4));
        assert_eq!(after_tool.3, Some(1));
    }

    #[test]
    fn artifact_split_text_events_get_distinct_part_revisions() {
        use jeikcode_kernel::event::AgentEvent;

        let mut projector = ChatRuntimeProjector::default();
        let _ = projector.project_agent(
            AgentEvent::AssistantMessage {
                message_id: "m-artifact-rev".into(),
            },
            "sess-artifact-rev",
        );
        let events = projector.project_agent(
            AgentEvent::TextDelta("before\n\n```rust\ncode\n```\nafter".into()),
            "sess-artifact-rev",
        );
        let revisions: Vec<u64> = events
            .iter()
            .filter_map(|event| match event {
                ChatEvent::TextDelta { part_rev, .. } => *part_rev,
                _ => None,
            })
            .collect();
        assert!(
            revisions.len() > 1,
            "artifact detector must split the delta"
        );
        assert!(
            revisions.windows(2).all(|pair| pair[0] < pair[1]),
            "each emitted TextDelta needs a distinct increasing part_rev: {revisions:?}"
        );
    }

    #[test]
    fn replay_log_seq_advances_for_every_event_and_keeps_the_last_on_coalesce() {
        let delta = |content: &str| ChatEvent::TextDelta {
            content: content.into(),
            message_id: Some("m-seq".into()),
            part_id: Some("m-seq:1:text".into()),
            part_seq: Some(1),
            part_rev: Some(1),
        };
        let mut log = ReplayLog::new(10);
        assert_eq!(push_chat_replay(&mut log, delta("a")), 11);
        assert_eq!(push_chat_replay(&mut log, delta("b")), 12);
        assert_eq!(log.events[0].0, 12, "coalesced entry exposes the last seq");
        assert_eq!(push_chat_replay(&mut log, ChatEvent::Stopped), 13);
        assert_eq!(log.events.len(), 2);
        assert_eq!(log.high_water(), 13);
    }

    #[test]
    fn replay_coalescing_keeps_the_last_part_rev() {
        let delta = |content: &str, rev: u64| ChatEvent::TextDelta {
            content: content.into(),
            message_id: Some("m-rev".into()),
            part_id: Some("m-rev:1:text".into()),
            part_seq: Some(1),
            part_rev: Some(rev),
        };
        let mut log = ReplayLog::new(0);
        assert_eq!(push_chat_replay(&mut log, delta("a", 1)), 1);
        assert_eq!(push_chat_replay(&mut log, delta("b", 2)), 2);
        assert_eq!(log.events.len(), 1);
        assert_eq!(log.events[0].0, 2, "coalesced entry keeps the LAST seq");
        match &log.events[0].1 {
            ChatEvent::TextDelta {
                content, part_rev, ..
            } => {
                assert_eq!(content, "ab");
                assert_eq!(
                    *part_rev,
                    Some(2),
                    "replay snapshot carries the last revision"
                );
            }
            other => panic!("expected text delta, got {other:?}"),
        }
    }

    #[test]
    fn chat_replay_coalesces_only_within_the_same_identity() {
        let delta = |content: &str, message_id: &str, part_id: &str| ChatEvent::TextDelta {
            content: content.into(),
            message_id: Some(message_id.into()),
            part_id: Some(part_id.into()),
            part_seq: Some(1),
            part_rev: None,
        };
        let mut log = ReplayLog::new(0);
        push_chat_replay(&mut log, delta("a", "m-1", "m-1:1:text"));
        push_chat_replay(&mut log, delta("b", "m-1", "m-1:1:text"));
        assert_eq!(log.events.len(), 1, "same identity coalesces");
        // 身份不同绝不合并：合并后回放会把后一回合的正文画到前一回合名下。
        push_chat_replay(&mut log, delta("c", "m-2", "m-2:1:text"));
        assert_eq!(
            log.events.len(),
            2,
            "a different round keeps its own replay entry"
        );
        match (&log.events[0].1, &log.events[1].1) {
            (
                ChatEvent::TextDelta {
                    content: first,
                    message_id: Some(first_id),
                    ..
                },
                ChatEvent::TextDelta {
                    content: second,
                    message_id: Some(second_id),
                    ..
                },
            ) => {
                assert_eq!(first, "ab");
                assert_eq!(first_id, "m-1");
                assert_eq!(second, "c");
                assert_eq!(second_id, "m-2");
            }
            other => panic!("unexpected replay buffer: {other:?}"),
        }
    }
}

#[cfg(test)]
mod transcript_display_tests {
    use super::*;
    use jeikcode_capabilities::session::{ToolRecord, TurnRecord};

    fn turn(id: u64, ts: i64, user: &str, assistant: &str) -> TurnRecord {
        TurnRecord {
            v: 1,
            ts,
            iso: String::new(),
            session_id: "s1".into(),
            turn_id: id,
            user: user.into(),
            assistant: assistant.into(),
            reasoning: String::new(),
            tools: Vec::new(),
            usage: Default::default(),
        }
    }

    fn info(role: &str, text: &str, synthetic: bool) -> MessageInfo {
        message_info! {
            turn_id: None,
            seq: None,
            role: role.into(),
            id: None,
            content: text.into(),
            reasoning: None,
            synthetic,
            internal_origin: None,
            tool_calls: None,
            tool_result: None,
            artifacts: None,
            images: None,
            created_at: None,
            elapsed_ms: None,
        }
    }

    #[test]
    fn missing_display_clock_inherits_the_previous_row() {
        // 行序就是时间序：缺时间的工具行必须继承上一条，绝不能用会话 updated_at。
        let mut rows = vec![
            info("user", "Q", false),
            info("tool", "out", false),
            info("assistant", "A", false),
        ];
        rows[0].created_at = Some(1_000);
        rows[1].created_at = None;
        rows[2].created_at = Some(1_200);
        fill_missing_display_clock(&mut rows, 500);
        assert_eq!(rows[0].created_at, Some(1_000));
        assert_eq!(rows[1].created_at, Some(1_000));
        assert_eq!(rows[2].created_at, Some(1_200));
    }

    #[test]
    fn repair_display_clock_pulls_fabricated_stamps_back_into_order() {
        // 旧日志里工具行与注入提示行被写成会话 updated_at(=9_000)，比它后面的回复还晚。
        let mut rows = vec![
            info("user", "Q", false),
            info("user", "<available_skills>", true),
            info("assistant", "A1", false),
            info("tool", "out", false),
            info("assistant", "A2", false),
        ];
        rows[0].created_at = Some(1_000);
        rows[1].created_at = Some(9_000);
        rows[2].created_at = Some(1_100);
        rows[3].created_at = Some(9_000);
        rows[4].created_at = Some(1_200);
        repair_display_clock(&mut rows);
        assert_eq!(
            rows[0].created_at,
            Some(1_000),
            "已按行序的提问时间保持原样"
        );
        assert_eq!(rows[1].created_at, Some(1_100), "伪造的注入提示时间被拉回");
        assert_eq!(rows[3].created_at, Some(1_200));
        let stamps: Vec<u64> = rows.iter().filter_map(|row| row.created_at).collect();
        assert!(stamps.windows(2).all(|pair| pair[0] <= pair[1]));
    }

    #[test]
    fn transcript_prefix_rebuilds_user_assistant_and_paired_tools() {
        let mut first = turn(1, 100, "Q1", "A1");
        first.tools.push(ToolRecord {
            name: "read".into(),
            args: "{\"path\":\"a\"}".into(),
            result: "R1".into(),
            is_error: false,
        });
        let second = turn(2, 200, "Q2", "A2");

        let rows = display_prefix_from_transcript(&[first, second], Some(150), None);
        assert_eq!(rows.len(), 4);
        assert_eq!(rows[0].role, "user");
        assert_eq!(rows[0].content, "Q1");
        assert_eq!(rows[0].created_at, None);
        assert_eq!(rows[1].role, "assistant");
        assert_eq!(rows[1].id.as_deref(), Some("transcript-1-assistant-tools"));
        let call = rows[1].tool_calls.as_ref().unwrap()[0].clone();
        assert_eq!(call.id, "transcript-1-tool-0");
        assert_eq!(rows[2].role, "tool");
        assert_eq!(rows[2].content, "R1");
        assert_eq!(rows[2].tool_result.as_ref().unwrap().call_id, call.id);
        assert!(rows[2].tool_result.as_ref().unwrap().success);
        assert_eq!(rows[3].role, "assistant");
        assert_eq!(rows[3].content, "A1");
        assert_eq!(rows[3].created_at, Some(100));
    }

    #[test]
    fn transcript_prefix_can_split_by_user_text_when_timestamp_is_missing() {
        let first = turn(1, 100, "Q1", "A1");
        let second = turn(2, 200, "Q2", "A2");
        let rows = display_prefix_from_transcript(&[first, second], None, Some("Q2"));
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0].content, "Q1");
        assert_eq!(rows[1].content, "A1");
    }

    fn display_record(role: &str, content: &str) -> jeikcode_capabilities::session::DisplayRecord {
        jeikcode_capabilities::session::DisplayRecord {
            v: jeikcode_capabilities::session::DISPLAY_VERSION,
            session_id: "s1".into(),
            turn_id: 1,
            index: 0,
            seq: 0,
            role: role.into(),
            id: Some("m-1".into()),
            content: content.into(),
            reasoning: None,
            synthetic: false,
            internal_origin: None,
            tool_calls: Vec::new(),
            tool_call_id: None,
            is_error: false,
            images: Vec::new(),
            created_at: Some(1),
            elapsed_ms: None,
        }
    }

    #[test]
    fn display_record_round_trips_images_and_tool_results() {
        let mut user = display_record("user", "看这张图");
        user.images
            .push(jeikcode_capabilities::session::DisplayImage {
                media_type: "image/png".into(),
                data: "AAAA".into(),
                missing: false,
            });
        let info = display_record_to_message_info(&user);
        assert_eq!(info.images.as_ref().unwrap()[0].data, "AAAA");
        let back = display_record_from_message_info("s1", 0, &info);
        assert_eq!(back.images[0].data, "AAAA");

        let mut call = display_record("assistant", "");
        call.tool_calls
            .push(jeikcode_capabilities::session::DisplayToolCall {
                id: "call-1".into(),
                name: "read".into(),
                arguments: "{\"path\":\"a\"}".into(),
            });
        let call_info = display_record_to_message_info(&call);
        assert_eq!(call_info.tool_calls.as_ref().unwrap()[0].id, "call-1");

        let mut result = display_record("tool", "tool output");
        result.tool_call_id = Some("call-1".into());
        let result_info = display_record_to_message_info(&result);
        assert_eq!(result_info.tool_result.as_ref().unwrap().call_id, "call-1");
        assert!(result_info.tool_result.as_ref().unwrap().success);
        assert_eq!(result_info.content, "tool output");
    }

    #[test]
    fn display_prefix_stops_before_the_first_real_user() {
        let snapshot = jeikcode_kernel::message::SessionSnapshot::new(vec![
            jeikcode_kernel::message::Message::system("sys"),
            jeikcode_kernel::message::Message::synthetic_user("ctx"),
            jeikcode_kernel::message::Message::user("Q1"),
        ]);
        let meta = jeikcode_capabilities::session::SessionMeta::new("s1", "/p", 1);
        let view = crate::legacy_convert::CatalogSessionView {
            snapshot,
            meta,
            presentation: jeikcode_capabilities::session::PresentationFile::default(),
        };
        let prefix = display_prefix_messages(&view);
        assert_eq!(prefix.len(), 2);
        assert_eq!(prefix[0].role, "system");
        assert_eq!(prefix[1].role, "user");
        assert!(prefix[1].synthetic);
        assert!(prefix.iter().all(|message| message.content != "Q1"));
    }

    #[test]
    fn display_record_strips_the_vision_marker_and_adds_a_placeholder() {
        let record = display_record("user", "请描述[图片内容（由模型识别）]：一只猫");
        let info = display_record_to_message_info(&record);
        assert_eq!(info.content, "请描述");
        assert!(info
            .images
            .as_ref()
            .is_some_and(|images| images.iter().any(|image| image.missing)));
    }

    #[test]
    fn splice_compacted_display_keeps_prefix_then_retained_tail_without_duplication() {
        let messages = vec![
            info("system", "sys", false),
            info("user", "你好啊\n\n<strong-reminder>x", false),
            info("user", "<!-- jeikcode:anchor v1 -->\nsummary", true),
            info("user", "Q2", false),
            info("assistant", "A2", false),
        ];
        let prefix = vec![
            info("user", "你好啊", false),
            info("assistant", "A1", false),
        ];
        let out = splice_compacted_display(messages, prefix);
        let texts: Vec<_> = out.iter().map(|m| m.content.as_str()).collect();
        assert_eq!(texts, vec!["你好啊", "A1", "sys", "Q2", "A2"]);
        assert_eq!(
            out.iter().filter(|m| m.content == "你好啊").count(),
            1,
            "the pre-anchor user must be covered by the transcript prefix, not duplicated"
        );
    }
}

#[cfg(test)]
mod env_write_guard_tests {
    /// 运行期禁止改写“会影响路径解析”的进程级环境变量。
    ///
    /// 契约：`Config::config_dir()` 在进程内只解析一次（`OnceLock`），因此任何
    /// 运行期 `set_var` 这 4 个键的代码都会让“写”与“读”落到不同根目录 —— 这正是
    /// 并行测试偶发的根因（scoped-home 测试改 env，另一个测试正好横跨读写窗口）。
    ///
    /// 正确做法：测试用 `jeikcode_config::test_util::isolated_home()`（线程级注入，
    /// 不碰 env）；bins 的 `main` 用 `special_dirs::sanitize_process_temp_env()`
    /// （仅启动期一次）。
    ///
    /// 白名单**只减不增**，且只允许“每测试进程/每进程恰好一次”的启动期写入。
    const GUARDED_KEYS: [&str; 4] = ["JEIKCODE_HOME", "TMPDIR", "TMP", "TEMP"];

    const ALLOWED: [(&str, &str); 3] = [
        (
            "crates/jeikcode-kernel/src/test_support.rs",
            "每测试进程一次的 isolate_home()（在任何测试解析路径之前）",
        ),
        (
            "crates/jeikcode-capabilities/src/special_dirs.rs",
            "bins main 启动期归一化 TMP/TMPDIR/TEMP",
        ),
        (
            "crates/jeikcode-capabilities/tests/temp_env_sanitize.rs",
            "该用例的测试对象就是 TMPDIR/TMP/TEMP 的归一化本身（集成测试独立进程）",
        ),
    ];

    /// 已登记的历史站点（**只减不增**）。迁移完成后本表应为空。
    const PENDING_MIGRATION: [&str; 0] = [];

    #[test]
    fn runtime_code_must_not_write_path_env_vars() {
        let repo_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(|crates| crates.parent())
            .expect("repo root")
            .to_path_buf();
        let mut files = Vec::new();
        collect_rs_files(&repo_root.join("crates"), &mut files);
        assert!(!files.is_empty(), "源码扫描必须能枚举到 crates/**/*.rs");

        let mut hits: std::collections::BTreeMap<String, Vec<String>> =
            std::collections::BTreeMap::new();
        for file in files {
            let relative = file
                .strip_prefix(&repo_root)
                .unwrap_or(&file)
                .to_string_lossy()
                .replace('\\', "/");
            if ALLOWED.iter().any(|(path, _)| *path == relative) {
                continue;
            }
            let Ok(source) = std::fs::read_to_string(&file) else {
                continue;
            };
            for (index, line) in source.lines().enumerate() {
                let trimmed = line.trim_start();
                // 注释里的示例不算违规。
                if trimmed.starts_with("//")
                    || !(line.contains("set_var") || line.contains("remove_var"))
                {
                    continue;
                }
                if GUARDED_KEYS
                    .iter()
                    .any(|key| line.contains(&format!("\"{key}\"")))
                {
                    hits.entry(relative.clone())
                        .or_default()
                        .push(format!("{}: {trimmed}", index + 1));
                }
            }
        }

        // ① 表外新违规 → 失败（阻止债务增长）。
        let unexpected: Vec<String> = hits
            .iter()
            .filter(|(file, _)| !PENDING_MIGRATION.contains(&file.as_str()))
            .map(|(file, lines)| format!("{file}\n  {}", lines.join("\n  ")))
            .collect();
        assert!(
            unexpected.is_empty(),
            "新增的运行期路径 env 写入（应改用线程级注入或启动期一次）；\n{}…",
            unexpected.join("\n")
        );

        // ② 已登记但不再违规 → 失败（提醒收缩清单）。
        let stale: Vec<&str> = PENDING_MIGRATION
            .iter()
            .copied()
            .filter(|file| !hits.contains_key(*file))
            .collect();
        assert!(
            stale.is_empty(),
            "这些文件已不再违规，请从 PENDING_MIGRATION 里删除：{stale:?}"
        );
    }

    fn collect_rs_files(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
        let Ok(entries) = std::fs::read_dir(dir) else {
            return;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                if path
                    .file_name()
                    .is_some_and(|name| name == "target" || name == ".git")
                {
                    continue;
                }
                collect_rs_files(&path, out);
            } else if path.extension().is_some_and(|ext| ext == "rs") {
                out.push(path);
            }
        }
    }
}

#[cfg(test)]
mod global_events_tests {
    use super::*;

    #[test]
    fn runtime_activity_serializes_revision_phase_and_owner() {
        let json = serde_json::to_value(GlobalWireEvent::RuntimeActivity {
            session_id: "s1".into(),
            revision: 7,
            running: true,
            phase: Some("compacting".into()),
            phase_started_at: Some(1_700_000_000_000),
            owner: Some("manual:op-1".into()),
        })
        .unwrap();
        assert_eq!(json["type"], "runtime_activity");
        assert_eq!(json["session_id"], "s1");
        assert_eq!(json["revision"], 7);
        assert_eq!(json["phase"], "compacting");
        assert_eq!(json["phase_started_at"], 1_700_000_000_000u64);
        assert_eq!(json["owner"], "manual:op-1");
    }

    #[test]
    fn global_bus_fans_out_to_every_subscriber() {
        // 跨实例语义：每个实例一条订阅，投递必须广播到所有订阅者（而不是竞争消费）。
        let mut first = global_events().subscribe();
        let mut second = global_events().subscribe();
        publish_global(GlobalWireEvent::Activity {
            session_id: "s-1".into(),
            running: true,
            terminal: None,
            status: None,
        });
        publish_global(GlobalWireEvent::ReviewAsked {
            session_id: "s-1".into(),
        });
        for rx in [&mut first, &mut second] {
            let a = rx.try_recv().expect("first event reaches every subscriber");
            let b = rx
                .try_recv()
                .expect("second event reaches every subscriber");
            assert!(matches!(a, GlobalWireEvent::Activity { .. }));
            assert!(matches!(b, GlobalWireEvent::ReviewAsked { .. }));
        }
    }

    /// `/loop` / `/goal` 控制器也是「会话正在干活」的一部分：wakeup 等待期间
    /// 没有执行中的回合，但控制器还挂着，不能被 `/chat/active` 当成空闲。
    #[test]
    fn controller_state_counts_as_running_until_it_is_released() {
        let session_id = "controller-test-loop";
        crate::note_loop_state(session_id, true, 2, "watch CI");
        let state = crate::controller_state_for(session_id).expect("loop state must be recorded");
        assert!(state.loop_active);
        assert_eq!(state.loop_round, 2);
        assert_eq!(state.loop_label, "watch CI");
        assert!(crate::controller_running_session_ids()
            .iter()
            .any(|id| id == session_id));

        // 控制器结束：记录仍在（保留最后一轮信息），但不再计入运行态。
        crate::note_loop_state(session_id, false, 2, "watch CI");
        assert!(crate::controller_state_for(session_id).is_some());
        assert!(!crate::controller_running_session_ids()
            .iter()
            .any(|id| id == session_id));
    }

    #[test]
    fn goal_state_alone_keeps_the_session_running() {
        let session_id = "controller-test-goal";
        crate::note_goal_state(session_id, true);
        assert!(crate::controller_state_for(session_id).is_some_and(|state| state.goal_active));
        assert!(crate::controller_running_session_ids()
            .iter()
            .any(|id| id == session_id));

        crate::note_goal_state(session_id, false);
        assert!(!crate::controller_running_session_ids()
            .iter()
            .any(|id| id == session_id));
    }

    /// 路由级 smoke：`/events` 必须先发 `sync` 对齐帧，随后把总线上的增量事件
    /// 真正推到 SSE 客户端（走 axum 路由 + ServiceExt::oneshot，与生产挂载同一 helper）。
    #[tokio::test]
    async fn global_events_route_streams_sync_then_incremental_events() {
        use axum::body::Body;
        use axum::http::{header, Request, StatusCode};
        use futures::StreamExt as _;
        use tower::ServiceExt as _;

        let app = with_global_events_route(Router::new());
        let response = app
            .oneshot(
                Request::builder()
                    .uri("/events")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .expect("/events must be mounted on the router");
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("text/event-stream")
        );
        let mut body = response.into_body().into_data_stream();

        // 首帧：sync。累积读取，不依赖分片边界。
        let mut seen = String::new();
        while !seen.contains("\"type\":\"sync\"") {
            let chunk = tokio::time::timeout(std::time::Duration::from_secs(2), body.next())
                .await
                .expect("sync frame must arrive")
                .expect("stream stays open")
                .expect("frame is valid");
            seen.push_str(&String::from_utf8_lossy(&chunk));
        }

        // 真推送：订阅建立后发布增量事件，SSE 必须送达。
        publish_global(GlobalWireEvent::ReviewAsked {
            session_id: "s-route".into(),
        });
        while !seen.contains("review_asked") {
            let chunk = tokio::time::timeout(std::time::Duration::from_secs(2), body.next())
                .await
                .expect("incremental event must arrive")
                .expect("stream stays open")
                .expect("frame is valid");
            seen.push_str(&String::from_utf8_lossy(&chunk));
        }
        assert!(seen.contains("\"session_id\":\"s-route\""), "{seen}");
    }

    #[test]
    fn global_wire_events_carry_incremental_payloads() {
        let upsert = serde_json::to_value(GlobalWireEvent::SessionUpsert {
            session: SessionRowWire {
                id: "s1".into(),
                name: "n".into(),
                working_dir: "E:/p".into(),
                project_hash: "0123456789abcdef".into(),
                created_at: 1,
                updated_at: 2,
                message_count: 3,
                origin: "manual".into(),
                approval_mode: None,
                preferred_model: None,
                reasoning_effort: None,
                thinking_budget: None,
            },
        })
        .unwrap();
        assert_eq!(upsert["type"], "session_upsert");
        assert_eq!(upsert["session"]["id"], "s1");
        assert_eq!(upsert["session"]["project_hash"], "0123456789abcdef");

        let deleted = serde_json::to_value(GlobalWireEvent::SessionDeleted {
            session_id: "s1".into(),
            project_hash: "0123456789abcdef".into(),
        })
        .unwrap();
        assert_eq!(deleted["type"], "session_deleted");
        assert_eq!(deleted["session_id"], "s1");

        // 查看信号：其它实例据此熄灭「刚完成」徽标。
        let seen = serde_json::to_value(GlobalWireEvent::SessionSeen {
            session_id: "s1".into(),
        })
        .unwrap();
        assert_eq!(seen["type"], "session_seen");
        assert_eq!(seen["session_id"], "s1");

        // 编辑/删除/回溯的跨实例失效信号：只带 revision，客户端据此作废缓存。
        let mutated = serde_json::to_value(GlobalWireEvent::SessionMutated {
            session_id: "s1".into(),
            revision: 7,
        })
        .unwrap();
        assert_eq!(mutated["type"], "session_mutated");
        assert_eq!(mutated["session_id"], "s1");
        assert_eq!(mutated["revision"], 7);

        // 终态带 kind（客户端据此出右下角通知）；运行中事件不带 terminal。
        let terminal = serde_json::to_value(GlobalWireEvent::Activity {
            session_id: "s1".into(),
            running: false,
            terminal: Some("completed"),
            status: None,
        })
        .unwrap();
        assert_eq!(terminal["type"], "activity");
        assert_eq!(terminal["terminal"], "completed");
        let running = serde_json::to_value(GlobalWireEvent::Activity {
            session_id: "s1".into(),
            running: true,
            terminal: None,
            status: None,
        })
        .unwrap();
        assert!(running.get("terminal").is_none());

        let asked = serde_json::to_value(GlobalWireEvent::ReviewAsked {
            session_id: "s1".into(),
        })
        .unwrap();
        assert_eq!(asked["type"], "review_asked");
        let resolved = serde_json::to_value(GlobalWireEvent::ReviewResolved {
            session_id: "s1".into(),
            approval_id: Some("a1".into()),
            request_id: None,
        })
        .unwrap();
        assert_eq!(resolved["type"], "review_resolved");
        assert_eq!(resolved["approval_id"], "a1");
        assert!(resolved.get("request_id").is_none());

        let mode_event = serde_json::to_value(GlobalWireEvent::SessionMode {
            session_id: Some("s1".into()),
            mode: "bypass".into(),
        })
        .unwrap();
        assert_eq!(mode_event["type"], "session_mode");
        assert_eq!(mode_event["session_id"], "s1");
        assert_eq!(mode_event["mode"], "bypass");
    }

    #[tokio::test]
    async fn fanout_chat_events_backfills_session_id_from_done_and_emits_terminal_activity() {
        let mut global_rx = global_events().subscribe();
        let (primary_tx, mut primary_rx) = mpsc::unbounded_channel();
        let (bus_tx, _bus_rx) = tokio::sync::broadcast::channel::<(u64, ChatEvent)>(16);
        let tx = fanout_chat_events_for_session(primary_tx, bus_tx, None, None, None);

        tx.send(ChatEvent::Done {
            tokens: 10,
            tool_calls: 0,
            session_id: "sid-fanout".into(),
            stop_reason: None,
            message: None,
            message_id: None,
        })
        .expect("send Done");
        tx.send(ChatEvent::Stopped).expect("send Stopped");
        drop(tx);

        assert!(matches!(
            primary_rx.recv().await,
            Some(ChatEvent::Done { .. })
        ));
        assert!(matches!(primary_rx.recv().await, Some(ChatEvent::Stopped)));

        let mut seen = Vec::new();
        while seen.len() < 2 {
            let evt = tokio::time::timeout(std::time::Duration::from_secs(2), global_rx.recv())
                .await
                .expect("activity frame must arrive")
                .expect("global bus stays open");
            if let GlobalWireEvent::Activity {
                session_id,
                running,
                terminal,
                ..
            } = evt
            {
                if session_id == "sid-fanout" {
                    seen.push((running, terminal));
                }
            }
        }
        assert_eq!(
            seen,
            vec![(false, Some("completed")), (false, Some("stopped"))]
        );
    }
}

/// Compact user-question row for the session outline (right-rail). Not the
/// model context — just labels.
#[derive(Debug, Clone, Serialize, Default)]
pub struct SessionTurnOutline {
    /// Stable ordinal among real user questions. Unlike `index`, this is not
    /// affected by assistant/tool/diagnostic rows inserted by failed turns.
    pub ordinal: usize,
    /// Stable persisted message id when available. The primary dedupe identity;
    /// older rows without an id fall back to `index`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
    pub index: usize,
    /// Short rail label. The full question lives in `messages`; keeping the
    /// outline compact avoids duplicating the whole transcript in every page.
    pub label: String,
    /// Input admitted but not yet folded/persisted. Rendered with a pending
    /// badge; its index is a display-space anchor like any other row.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub pending: bool,
    /// Admission order from the durable input log (absent for persisted rows).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub seq: Option<u64>,
}

const OUTLINE_LABEL_CAP: usize = 120;

fn outline_label(text: &str) -> String {
    let un_steered = if let Some(start) = text.find("<user-query>") {
        if let Some(end) = text.find("</user-query>") {
            &text[start + "<user-query>".len()..end]
        } else {
            text
        }
    } else if let Some(idx) = text.find("[jeikcode-steer]") {
        let before = text[..idx].trim();
        if !before.is_empty() {
            before
        } else {
            text
        }
    } else {
        text
    };
    let compact = un_steered.split_whitespace().collect::<Vec<_>>().join(" ");
    if compact.chars().count() <= OUTLINE_LABEL_CAP {
        return compact;
    }
    format!(
        "{}…",
        compact
            .chars()
            .take(OUTLINE_LABEL_CAP.saturating_sub(1))
            .collect::<String>()
    )
}

fn session_user_outline(messages: &[MessageInfo]) -> Vec<SessionTurnOutline> {
    messages
        .iter()
        .enumerate()
        .filter_map(|(index, msg)| {
            if !msg.role.eq_ignore_ascii_case("user") || msg.synthetic {
                return None;
            }
            let label = outline_label(&msg.content);
            if label.is_empty() {
                return None;
            }
            // 旧快照行可能没有 id：用确定性 id 兑底，大纲条目始终可按 id 命中。
            Some((
                index,
                msg.id.clone().or_else(|| Some(format!("m-legacy-{index}"))),
                label,
                msg.seq,
            ))
        })
        .enumerate()
        .map(|(ordinal, (index, id, label, seq))| SessionTurnOutline {
            ordinal,
            id,
            index,
            label,
            pending: false,
            seq,
        })
        .collect()
}

/// Collect the session-unique message identities present in a display log.
fn display_record_ids(
    records: &[jeikcode_capabilities::session::DisplayRecord],
) -> std::collections::HashSet<String> {
    records
        .iter()
        .filter_map(|record| record.id.clone())
        .collect()
}

/// v4 completeness: every completed turn's boundary messages must be present in
/// the durable display log.
///
/// Turn ids alone are NOT a sufficient identity: a rewind can restore the
/// kernel turn counter, so a later turn may REUSE an id whose archived
/// `turn_stats` entry is still present. `completed_turns.contains(id)` then
/// reports coverage for a turn that never reached the log — exactly how the
/// final turn of a session can vanish from the canvas after a refresh. Message
/// ids are session-unique, so they survive id reuse.
///
/// Both boundaries are checked:
/// - the prompting user row, and
/// - the turn's last assistant row (the tool-call finalization or the
///   error diagnostic).
///
/// The second check matters because a mid-turn refresh/backfill can legitimately
/// write the prompt row early; prompt presence alone would then trust a log
/// whose `turn_complete` slice was dropped.
///
/// A `backfilled` log is no longer exempt: its rows carry the canonical message
/// ids, so the same check applies and a later dropped append is still caught.
fn v4_display_covers_completed_user_turns(
    meta: &jeikcode_capabilities::session::DisplayMeta,
    display_ids: &std::collections::HashSet<String>,
    snapshot: &[jeikcode_kernel::message::Message],
    turn_stats: &[jeikcode_capabilities::session::TurnStat],
    snapshot_last_turn: u64,
) -> bool {
    use jeikcode_kernel::message::Role;

    if meta.last_turn_id < snapshot_last_turn {
        return false;
    }
    let completed: std::collections::HashSet<u64> = meta.completed_turns.iter().copied().collect();
    let mut previous = 0usize;
    for stat in turn_stats
        .iter()
        .filter(|stat| stat.position_valid && stat.turn_id != 0)
    {
        let end = stat.after_message.min(snapshot.len());
        let start = previous.min(end);
        let turn = &snapshot[start..end];
        if let Some(prompt) = turn
            .iter()
            .find(|message| message.role == Role::User && !message.synthetic)
        {
            let covered = match prompt.id.as_deref() {
                Some(id) => display_ids.contains(id),
                // A pre-id snapshot cannot be reconciled by identity. A
                // backfilled log is the only trustworthy projection for those
                // raw rows; otherwise keep the legacy turn-id contract.
                None => meta.backfilled || completed.contains(&stat.turn_id),
            };
            if !covered {
                return false;
            }
        }
        // The terminal assistant row proves the whole turn slice landed, not
        // just a prompt row written by a mid-turn backfill.
        if let Some(last_assistant) = turn.iter().rev().find(|m| m.role == Role::Assistant) {
            if let Some(id) = last_assistant.id.as_deref() {
                if !display_ids.contains(id) {
                    return false;
                }
            }
        }
        previous = end;
    }
    true
}

/// v3 migration guard only. v4 sessions use the exact turn-id check in
/// [`v4_display_covers_completed_user_turns`]; a normal v4 read never calls this.
///
/// 展示日志只覆盖「已落盘的完整回合」。当某个已完成回合的用户行缺失，
/// 且它后面还有可见提问时，这是日志中间的洞（晚到/中断的 flush），
/// 不是运行中的尾巴——此时必须回退到快照投影，而不是继续信任 display。
fn display_covers_completed_user_rows(
    records: &[jeikcode_capabilities::session::DisplayRecord],
    snapshot: &[jeikcode_kernel::message::Message],
    turn_stats: &[jeikcode_capabilities::session::TurnStat],
    snapshot_last_turn: u64,
) -> bool {
    use jeikcode_kernel::message::Role;

    let display_ids: std::collections::HashSet<String> = records
        .iter()
        .filter(|record| record.role.eq_ignore_ascii_case("user") && !record.synthetic)
        .map(display_record_identity)
        .collect();
    // 旧日志没有 id 时无法核对；下一次空闲读取会用确定性 id 回填。
    if display_ids.is_empty() {
        return true;
    }
    for (index, message) in snapshot.iter().enumerate() {
        if message.role != Role::User || message.synthetic {
            continue;
        }
        let Some(id) = message.id.as_deref() else {
            continue;
        };
        if display_ids.contains(id) {
            continue;
        }
        // `after_message` 是快照消息数边界：第一个覆盖该下标的回合就是它所属的 turn。
        let turn_id = turn_stats
            .iter()
            .filter(|stat| stat.position_valid && stat.after_message > index)
            .min_by_key(|stat| stat.after_message)
            .map(|stat| stat.turn_id)
            .unwrap_or(u64::MAX);
        if turn_id > snapshot_last_turn {
            // 运行中的尾巴还没有 turn_stat：这是未落盘尾巴，不是洞。
            continue;
        }
        let later_visible = snapshot[index + 1..].iter().any(|later| {
            later.role == Role::User
                && !later.synthetic
                && later
                    .id
                    .as_deref()
                    .is_some_and(|id| display_ids.contains(id))
        });
        if later_visible {
            return false;
        }
    }
    true
}

/// 把快照里「display 最后一条共享行之后」的未落盘内容投影到画布与大纲。
///
/// 这是运行中/刚停止但尚未 flush 的唯一尾巴来源：display 日志要等
/// `turn_complete`，而 inflight 快照已经有序、带 id。只追加共享锚点之后的
/// 行，绝不猜测锚点之前的位置；没有共享锚点的旧日志交给 snapshot 回退路径。
fn append_snapshot_tail(
    messages: &mut Vec<MessageInfo>,
    turns: &mut Vec<SessionTurnOutline>,
    snapshot: &[jeikcode_kernel::message::Message],
    working_dir: &std::path::Path,
) -> usize {
    use jeikcode_kernel::message::Role;

    if snapshot.is_empty() || messages.is_empty() {
        return 0;
    }
    let display_ids: std::collections::HashSet<String> = messages
        .iter()
        .filter_map(|message| message.id.clone())
        .collect();
    let Some(anchor) = snapshot.iter().rposition(|message| {
        message
            .id
            .as_deref()
            .is_some_and(|id| display_ids.contains(id))
    }) else {
        // 没有共享身份：旧日志/旧 daemon。不能靠文本猜位置。
        return 0;
    };
    let known_turn_ids: std::collections::HashSet<String> =
        turns.iter().filter_map(|turn| turn.id.clone()).collect();
    let mut next_seq = messages
        .iter()
        .filter_map(|message| message.seq)
        .max()
        .unwrap_or(0);
    let mut appended = 0usize;
    for message in snapshot.iter().skip(anchor + 1) {
        let Some(id) = message.id.as_deref() else {
            continue;
        };
        if display_ids.contains(id) {
            continue;
        }
        let index = messages.len();
        let mut msg_info = MessageInfo::from_kernel_in(message, Some(working_dir));
        next_seq = next_seq.saturating_add(1);
        msg_info.seq = Some(next_seq);
        messages.push(msg_info);
        appended += 1;
        if message.role == Role::User && !message.synthetic && !known_turn_ids.contains(id) {
            let label = outline_label(&jeikcode_capabilities::session::user_text_for_display(
                working_dir,
                &message.text,
            ));
            if !label.is_empty() {
                turns.push(SessionTurnOutline {
                    ordinal: turns.len(),
                    id: Some(id.to_string()),
                    index,
                    label,
                    pending: false,
                    seq: Some(next_seq),
                });
            }
        }
    }
    appended
}

/// Show an interrupted per-token checkpoint on a cold read. The next `/chat`
/// overlays the same content into the model context and clears the sidecar; this
/// projection only makes the recovered text visible before the retry.
fn append_interrupted_partial(messages: &mut Vec<MessageInfo>, session_id: &str, running: bool) {
    if running {
        return;
    }
    let Some(partial) = jeikcode_capabilities::session::partial::load_global(session_id) else {
        return;
    };
    if partial.text.trim().is_empty() && partial.reasoning.trim().is_empty() {
        return;
    }
    if partial.message_id.as_deref().is_some_and(|id| {
        messages
            .iter()
            .any(|message| message.id.as_deref() == Some(id))
    }) || (!partial.text.trim().is_empty()
        && messages.iter().any(|message| {
            message.role == "assistant" && message.content.contains(partial.text.trim())
        }))
    {
        return;
    }
    let next_seq = messages
        .iter()
        .filter_map(|message| message.seq)
        .max()
        .unwrap_or(0)
        .saturating_add(1);
    messages.push(message_info! {
        turn_id: None,
        seq: Some(next_seq),
        role: "assistant".into(),
        id: partial.message_id,
        content: partial.text,
        reasoning: (!partial.reasoning.trim().is_empty()).then_some(partial.reasoning),
        synthetic: false,
        internal_origin: Some("interrupted_partial".into()),
        tool_calls: None,
        tool_result: None,
        artifacts: None,
        images: None,
        created_at: Some(partial.updated_at),
        elapsed_ms: None,
    });
}

/// Overlay a per-token crash checkpoint onto the canonical conversation.
/// Idempotent: a persisted assistant message with the same id (or already
/// containing the checkpoint text) wins. Returns true when a row was appended.
pub(crate) fn overlay_partial_stream(
    conversation: &mut Vec<jeikcode_kernel::message::Message>,
    partial: &jeikcode_capabilities::session::PartialStream,
) -> bool {
    if partial.text.trim().is_empty()
        && partial.reasoning.trim().is_empty()
        && partial.tool_calls.is_empty()
    {
        return false;
    }
    let already = conversation.iter().any(|message| {
        message.role == jeikcode_kernel::message::Role::Assistant
            && (partial
                .message_id
                .as_deref()
                .is_some_and(|id| message.id.as_deref() == Some(id))
                || (!partial.text.trim().is_empty() && message.text.contains(partial.text.trim())))
    });
    if already {
        return false;
    }
    let calls: Vec<jeikcode_kernel::tool::ToolCall> = partial
        .tool_calls
        .iter()
        .filter_map(|tool| {
            Some(jeikcode_kernel::tool::ToolCall {
                id: tool.id.clone()?,
                name: tool.name.clone()?,
                arguments: tool.arguments.clone(),
            })
        })
        .collect();
    let mut recovered =
        jeikcode_kernel::message::Message::assistant(partial.text.clone(), calls.clone());
    recovered.id = partial.message_id.clone();
    recovered.reasoning =
        (!partial.reasoning.trim().is_empty()).then_some(partial.reasoning.clone());
    recovered.internal_origin = Some("interrupted_partial".into());
    conversation.push(recovered);
    // A tool call without a result makes the provider context invalid. Pair every
    // interrupted call with an explicit failed result; the next turn can retry.
    for call in calls {
        if conversation
            .iter()
            .any(|message| message.tool_call_id.as_deref() == Some(call.id.as_str()))
        {
            continue;
        }
        let mut result = jeikcode_kernel::message::Message::tool_result(
            call.id,
            "interrupted: tool call did not complete before the process stopped",
            true,
        );
        result.internal_origin = Some("interrupted_partial_tool".into());
        conversation.push(result);
    }
    true
}

/// Project admitted-but-not-yet-folded inputs (prompt/steer) onto the canvas
/// and rail. This is the durable gap between POST acceptance and the kernel's
/// persisted message; it is scoped to the current operation so stale rows from
/// an older turn can never reappear.
fn append_pending_inputs(
    messages: &mut Vec<MessageInfo>,
    turns: &mut Vec<SessionTurnOutline>,
    session_id: &str,
    operation_id: Option<&str>,
    working_dir: &std::path::Path,
    absolute_index_base: usize,
) {
    let existing: std::collections::HashSet<String> = messages
        .iter()
        .filter_map(|message| message.id.clone())
        .collect();
    let mut next_seq = messages
        .iter()
        .filter_map(|message| message.seq)
        .max()
        .unwrap_or(0);
    let all_inputs = jeikcode_capabilities::session::inputs::list_global(session_id);
    if let Some(operation_id) = operation_id {
        for input in all_inputs.iter().filter(|input| {
            input.status == "admitted"
                && input.operation_id.as_deref() == Some(operation_id)
                && (!input.text.trim().is_empty() || !input.images.is_empty())
        }) {
            // Queued steers live in `/chat/queue` as cancellable cards until the
            // kernel actually folds them at a round boundary (`Steered`). Projecting
            // an un-folded steer into `messages` prematurely paints a user bubble
            // below the in-flight assistant round while that round continues
            // streaming above it.
            if input.delivery == "steer" {
                continue;
            }
            if existing.contains(&input.id) {
                continue;
            }
            let content =
                jeikcode_capabilities::session::user_text_for_display(working_dir, &input.text);
            let images: Vec<ImageData> = input
                .images
                .iter()
                .map(|image| ImageData {
                    media_type: image.media_type.clone(),
                    data: image.data.clone(),
                    missing: false,
                })
                .collect();
            if content.trim().is_empty() && images.is_empty() {
                continue;
            }
            let label_text = if content.trim().is_empty() {
                "[图片]".to_string()
            } else {
                content.clone()
            };
            let label = outline_label(&label_text);
            if label.is_empty() {
                continue;
            }
            let index = absolute_index_base + messages.len();
            next_seq = next_seq.saturating_add(1);
            let user_info = message_info! {
                turn_id: None,
                seq: Some(next_seq),
                role: "user".into(),
                id: Some(input.id.clone()),
                content,
                reasoning: None,
                synthetic: false,
                internal_origin: Some("pending_input".into()),
                tool_calls: None,
                tool_result: None,
                artifacts: None,
                images: (!images.is_empty()).then_some(images),
                created_at: Some(input.created_at),
                elapsed_ms: None,
            };
            messages.push(user_info);
            turns.push(SessionTurnOutline {
                ordinal: turns.len(),
                id: Some(input.id.clone()),
                index,
                label,
                pending: true,
                seq: Some(next_seq),
            });
        }
    }
    append_folded_steer_outline(
        messages,
        turns,
        &all_inputs,
        operation_id,
        working_dir,
        absolute_index_base,
    );
}

/// Keep queued/folded steers in the right-rail outline before display flush.
///
/// `display.jsonl` only gets the steer at `turn_complete` (in the correct
/// assistant/user order). The durable input log already records the admitted
/// steer (and marks it promoted when folded); projecting it here prevents a
/// refresh from rebuilding the outline without it. The pending row is replaced
/// by the persisted display row once the turn settles (merge is by `id`).
fn append_folded_steer_outline(
    messages: &[MessageInfo],
    turns: &mut Vec<SessionTurnOutline>,
    inputs: &[jeikcode_capabilities::session::SessionInput],
    operation_id: Option<&str>,
    working_dir: &std::path::Path,
    absolute_index_base: usize,
) {
    let existing: std::collections::HashSet<String> =
        turns.iter().filter_map(|turn| turn.id.clone()).collect();
    let mut added = 0usize;
    for input in inputs {
        if input.delivery != "steer" || (input.status != "admitted" && input.status != "promoted") {
            continue;
        }
        // `/chat` steers carry the owning operation's client id. A live-runtime
        // steer has no ActiveChatRegistry operation; it is still included as
        // long as it is promoted and not already in the persisted outline.
        if let (Some(current), Some(input_op)) = (operation_id, input.operation_id.as_deref()) {
            if current != input_op {
                continue;
            }
        }
        if existing.contains(&input.id) {
            continue;
        }
        let content =
            jeikcode_capabilities::session::user_text_for_display(working_dir, &input.text);
        let label_text = if content.trim().is_empty() {
            if input.images.is_empty() {
                continue;
            }
            "[图片]".to_string()
        } else {
            content
        };
        let label = outline_label(&label_text);
        if label.is_empty() {
            continue;
        }
        turns.push(SessionTurnOutline {
            ordinal: turns.len(),
            id: Some(input.id.clone()),
            // Provisional canvas coordinate: the pending row is jumped by id and
            // replaced by the display row once the turn settles.
            index: absolute_index_base + messages.len() + added,
            label,
            pending: true,
            seq: Some(input.seq),
        });
        added = added.saturating_add(1);
    }
}

/// Explicit edit/rewind: prune the in-memory turn stats that describe the
/// removed tail. Derived files are pruned separately AFTER the canonical
/// snapshot commit, so a failed snapshot write can never leave them ahead.
fn prune_rewound_turn_stats(
    meta: &mut jeikcode_capabilities::session::SessionMeta,
    keep_count: usize,
) -> Option<std::collections::BTreeSet<u64>> {
    let had_native = meta
        .turn_stats
        .iter()
        .any(|stat| stat.position_valid && stat.turn_id != 0);
    meta.turn_stats
        .retain(|stat| stat.after_message <= keep_count);
    meta.turn_count = u32::try_from(meta.turn_stats.len()).unwrap_or(0);
    if !had_native {
        return None;
    }
    Some(
        meta.turn_stats
            .iter()
            .filter(|stat| stat.position_valid && stat.turn_id != 0)
            .map(|stat| stat.turn_id)
            .collect(),
    )
}

fn resync_todo_board_after_rewind(id: &str, messages: &[jeikcode_kernel::message::Message]) {
    // 删除/回溯只回退被删掉的那些 todo 动作，保留更早轮次建立/修改过的项。
    // 按**剩余转录**重新推导；板身份（id + 单调 seq）原地重绑，撤销不会被
    // 看成“另起一板/版本回退”。
    let derived = jeikcode_capabilities::tools::derive_current_todos(messages);
    if jeikcode_capabilities::tools::rebind_todo_board(id, &derived).is_none() {
        if derived.is_empty() {
            jeikcode_capabilities::tools::clear_todo_board(id);
        } else {
            jeikcode_capabilities::tools::commit_todo_board(id, &derived);
        }
    }
}

fn prune_deleted_turn_stats(
    meta: &mut jeikcode_capabilities::session::SessionMeta,
    deleted_range_start: usize,
    removed_count: usize,
) -> Option<std::collections::BTreeSet<u64>> {
    // A single-turn delete keeps every LATER turn. Remove only the stat that
    // covered the deleted range and shift later positions by the removed rows.
    let had_native = meta
        .turn_stats
        .iter()
        .any(|stat| stat.position_valid && stat.turn_id != 0);
    let affected_after = meta
        .turn_stats
        .iter()
        .filter(|stat| {
            stat.position_valid && stat.turn_id != 0 && stat.after_message > deleted_range_start
        })
        .min_by_key(|stat| stat.after_message)
        .map(|stat| stat.after_message);
    if let Some(affected_after) = affected_after {
        meta.turn_stats
            .retain(|stat| stat.after_message != affected_after);
        for stat in &mut meta.turn_stats {
            if stat.after_message > affected_after {
                stat.after_message = stat.after_message.saturating_sub(removed_count);
            }
        }
    }
    meta.turn_count = u32::try_from(meta.turn_stats.len()).unwrap_or(0);
    if !had_native {
        return None;
    }
    Some(
        meta.turn_stats
            .iter()
            .filter(|stat| stat.position_valid && stat.turn_id != 0)
            .map(|stat| stat.turn_id)
            .collect(),
    )
}

/// Apply derived-file pruning only AFTER the canonical snapshot + meta commit.
fn prune_derived_turns(
    manager: &NativeSessionManager,
    id: &str,
    surviving: &std::collections::BTreeSet<u64>,
) {
    let _ = manager.prune_presentation(id, surviving);
    let _ = manager.retain_transcript_turns(id, surviving);
}

fn session_records_user_outline(
    records: &[jeikcode_capabilities::session::DisplayRecord],
    index_offset: usize,
) -> Vec<SessionTurnOutline> {
    records
        .iter()
        .enumerate()
        .filter_map(|(idx, record)| {
            if !record.role.eq_ignore_ascii_case("user") || record.synthetic {
                return None;
            }
            let label = outline_label(&record.content);
            if label.is_empty() {
                return None;
            }
            Some((
                index_offset + idx,
                Some(display_record_identity(record)),
                label,
                (record.seq > 0).then_some(record.seq),
            ))
        })
        .enumerate()
        .map(|(ordinal, (index, id, label, seq))| SessionTurnOutline {
            ordinal,
            id,
            index,
            label,
            pending: false,
            seq,
        })
        .collect()
}

/// 该 daemon 支持的跨端身份 / 版本能力。客户端据此决定是否启用 legacy 文本兜底：
/// 声明了 `id` 就意味着 wire / 磁盘 / 大纲三处共享同一个消息 id，无需再猜文本。
/// 新增能力只能追加，不能改名（旧客户端靠字符串匹配）。
pub(crate) fn session_capabilities() -> Vec<String> {
    vec![
        "id".into(),
        "revision".into(),
        "seq".into(),
        "session_mutated".into(),
        // Terminal frames carry the client correlation id; interrupted turns
        // commit their partial context instead of rolling it back.
        "terminal_operation_id".into(),
        "preserve_interrupted".into(),
        // Live frames carry an explicit replay boolean; clients must not infer
        // replay from seq presence on this daemon.
        "explicit_replay".into(),
    ]
}

/// Session-global display cursor for identity-first pagination.
#[derive(Debug, Clone, Serialize, Default)]
pub struct SessionCursor {
    /// Oldest display `seq` in the returned window (None for legacy rows).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub oldest_seq: Option<u64>,
    pub total: usize,
}

/// Session detail response
#[derive(Debug, Clone, Serialize)]
pub struct SessionDetail {
    /// Session-global display cursor.
    #[serde(default)]
    pub cursor: SessionCursor,
    pub id: String,
    pub name: String,
    pub working_dir: PathBuf,
    /// Epoch milliseconds (统一为毫秒,与 MessageInfo.created_at 一致; kernel 内部 Session.created_at 为秒,此处 API 响应边界转毫秒)。
    pub created_at: u64,
    /// Epoch milliseconds (同上)。
    pub updated_at: u64,
    /// Total messages in the transcript (not the returned window size).
    pub message_count: usize,
    /// 会话权威版本号（内核 `cache_epoch`）。每次显式变更（编辑 / 删除 / 回溯）
    /// 自增；客户端用它给缓存写入设闸门，旧快照永远不能覆盖新快照。
    #[serde(default)]
    pub revision: u64,
    /// 本 daemon 的能力集（见 [`session_capabilities`]）。客户端据此关闭旧文本兜底。
    #[serde(default)]
    pub caps: Vec<String>,
    /// Index of `messages[0]` in the full transcript.
    /// When `pinned_user_index` is set, `messages[0]` is that question and this
    /// is the index of `messages[1]`.
    #[serde(default)]
    pub offset: usize,
    /// Absolute index of the user question pinned ahead of a mid-turn tail page.
    /// Rows between it and `offset` are not included.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pinned_user_index: Option<usize>,
    /// All user questions (short text) in transcript order. Independent of the
    /// `messages` window so the WebUI turn rail can list the full session.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub turns: Vec<SessionTurnOutline>,
    /// Highest durable input-log sequence. Clients pass it back as `after_seq`
    /// to fetch only newly admitted prompt/steer rows.
    #[serde(default)]
    pub input_cursor: u64,
    pub messages: Vec<MessageInfo>,
    /// Per-session model selection. Absent on older sessions.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub preferred_model: Option<String>,
    /// Per-session approval mode ("build" | "accept_edits" | "bypass" | "plan"). Absent on older sessions.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub approval_mode: Option<String>,
    /// Per-session reasoning effort. Absent means "inherit the provider default".
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reasoning_effort: Option<String>,
    /// Per-session custom thinking budget.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub thinking_budget: Option<u32>,
    /// Footer occupancy from the last completed turn (`used_tokens` / last request).
    /// Must not be turn-cumulative `model_usage` billing, or restart paints over-budget.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub token_usage: Option<SessionTokenUsage>,
    /// `manual` / `scheduled` / `protocol`. Protocol sessions are observed in Auto.
    #[serde(default, skip_serializing_if = "is_manual_session_origin")]
    pub origin: jeikcode_capabilities::session::SessionOrigin,
    /// The session's single live checklist. Empty after a completed board is closed on stop.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub todos: Vec<jeikcode_capabilities::tools::TodoItem>,
    /// Monotonic version of `todos` (server-assigned). Clients must arbitrate
    /// snapshots by revision; a lower revision may never overwrite a higher one.
    #[serde(default)]
    pub todos_revision: u64,
}

fn is_manual_session_origin(origin: &jeikcode_capabilities::session::SessionOrigin) -> bool {
    matches!(
        origin,
        jeikcode_capabilities::session::SessionOrigin::Manual
    )
}

/// Token footer snapshot derived from [`SessionMeta::turn_stats`].
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct SessionTokenUsage {
    pub prompt: usize,
    pub completion: usize,
    pub total: usize,
    pub cached: usize,
    #[serde(default)]
    pub cached_estimated: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ctx_window: Option<usize>,
}

fn estimate_prefix_cached_tokens(current_prompt: usize, previous_prompt: usize) -> usize {
    if current_prompt == 0 || previous_prompt == 0 {
        return 0;
    }
    if current_prompt < previous_prompt * 9 / 10 {
        return 0;
    }
    current_prompt.min(previous_prompt)
}

fn turn_stat_billing_prompt_tokens(stat: &jeikcode_capabilities::session::TurnStat) -> usize {
    let mut uncached_input = 0u64;
    let mut cached_input = 0u64;
    for usage in &stat.model_usage {
        uncached_input = uncached_input.saturating_add(usage.tokens.input);
        cached_input = cached_input.saturating_add(usage.tokens.cached_input);
    }
    usize::try_from(uncached_input.saturating_add(cached_input)).unwrap_or(usize::MAX)
}

fn turn_stat_billing_output_tokens(stat: &jeikcode_capabilities::session::TurnStat) -> usize {
    let output = stat
        .model_usage
        .iter()
        .fold(0u64, |acc, usage| acc.saturating_add(usage.tokens.output));
    usize::try_from(output).unwrap_or(0)
}

fn turn_stat_billing_cached_tokens(stat: &jeikcode_capabilities::session::TurnStat) -> usize {
    let cached = stat.model_usage.iter().fold(0u64, |acc, usage| {
        acc.saturating_add(usage.tokens.cached_input)
    });
    usize::try_from(cached).unwrap_or(0)
}

/// Last-request prompt occupancy for the context-window gauge.
///
/// `TurnStat.model_usage` is **turn-cumulative billing** (every LLM round in
/// the user turn is added). Using that sum as `prompt` made a restart paint
/// 1.7M/1.0M until the next live `Usage` event replaced it with occupancy.
fn turn_stat_occupancy_tokens(stat: &jeikcode_capabilities::session::TurnStat) -> usize {
    if stat.used_tokens > 0 {
        stat.used_tokens as usize
    } else if stat.total_tokens > 0 {
        stat.total_tokens as usize
    } else if stat.round_count <= 1 {
        // Legacy rows without occupancy: a single-round billing total is the
        // last request. Multi-round sums are not occupancy — refuse them.
        turn_stat_billing_prompt_tokens(stat)
    } else {
        0
    }
}

fn turn_stat_last_completion_tokens(stat: &jeikcode_capabilities::session::TurnStat) -> usize {
    if stat.used_tokens > 0 && stat.total_tokens > stat.used_tokens {
        stat.total_tokens.saturating_sub(stat.used_tokens) as usize
    } else if stat.round_count <= 1 {
        turn_stat_billing_output_tokens(stat)
    } else {
        0
    }
}

/// Live WebUI last-frame formula (also the restart restore formula):
///
/// ```text
/// prompt     = last LLM request prompt   (occupancy; includes tools in that request)
/// completion = last LLM request completion
/// total      = prompt + completion       // footer 总上下文
/// cached     = last LLM request cached
/// ```
///
/// Each `Usage` event **replaces** the footer. Never sum rounds.
/// `TurnStat.model_usage` is turn-cumulative billing for `/cost` and must not
/// feed this gauge — that is how a 200k last frame became 1.7M after restart.
fn footer_from_last_request(
    prompt: usize,
    completion: usize,
    cached: usize,
    ctx_window: Option<usize>,
    cached_estimated: bool,
) -> SessionTokenUsage {
    let cached = if prompt == 0 { 0 } else { cached.min(prompt) };
    SessionTokenUsage {
        prompt,
        completion,
        total: prompt.saturating_add(completion),
        cached,
        cached_estimated,
        ctx_window,
    }
}

fn last_assistant_request_usage(
    messages: &[jeikcode_kernel::message::Message],
) -> Option<(usize, usize, usize, usize)> {
    use jeikcode_kernel::message::Role;
    let meta = messages
        .iter()
        .rev()
        .find(|message| message.role == Role::Assistant)?
        .meta
        .as_ref()?;
    let prompt = if meta.tokens.prompt > 0 {
        meta.tokens.prompt as usize
    } else {
        meta.used_tokens as usize
    };
    let completion = meta.tokens.completion as usize;
    let cached = meta.tokens.cached as usize;
    let ctx_window = meta.ctx_window as usize;
    if prompt == 0 && completion == 0 {
        return None;
    }
    Some((prompt, completion, cached, ctx_window))
}

fn estimate_cache_from_previous_turn(
    meta: &jeikcode_capabilities::session::SessionMeta,
    prompt: usize,
) -> Option<usize> {
    if prompt == 0 {
        return None;
    }
    let previous = meta
        .turn_stats
        .iter()
        .rev()
        .filter(|stat| stat.position_valid)
        .skip(1)
        .map(turn_stat_occupancy_tokens)
        .find(|value| *value > 0)?;
    let estimated = estimate_prefix_cached_tokens(prompt, previous);
    (estimated > 0).then_some(estimated)
}

/// Restore the footer from the last assistant `MessageMeta` (same payload the
/// live `Usage` event painted) and only fall back to turn-stat occupancy.
pub(crate) fn session_token_usage_from_session(
    meta: &jeikcode_capabilities::session::SessionMeta,
    snapshot: &jeikcode_kernel::message::SessionSnapshot,
) -> Option<SessionTokenUsage> {
    // 刚提交的压缩是比「最后一条助手消息的 usage」更新的上下文事实：后者仍是
    // 压缩前的 prompt 大小。新回合 / undo / 显式变更会清空该字段。
    if let Some(compacted) = meta.compacted_context_tokens.filter(|tokens| *tokens > 0) {
        return Some(footer_from_last_request(
            compacted as usize,
            0,
            0,
            None,
            false,
        ));
    }
    if let Some((prompt, completion, cached, ctx_window)) =
        last_assistant_request_usage(&snapshot.messages)
    {
        let mut cached_estimated = false;
        let cached = if cached > 0 && cached <= prompt {
            cached
        } else if let Some(estimated) = estimate_cache_from_previous_turn(meta, prompt) {
            cached_estimated = true;
            estimated
        } else {
            0
        };
        return Some(footer_from_last_request(
            prompt,
            completion,
            cached,
            (ctx_window > 0).then_some(ctx_window),
            cached_estimated,
        ));
    }
    session_token_usage_from_meta(meta)
}

/// Occupancy fallback when the snapshot has no last-request `MessageMeta`.
/// Uses `used_tokens` / `total_tokens` (last request), never `model_usage` sums.
pub(crate) fn session_token_usage_from_meta(
    meta: &jeikcode_capabilities::session::SessionMeta,
) -> Option<SessionTokenUsage> {
    let stat = meta.turn_stats.iter().rev().find(|s| s.position_valid)?;
    if stat.used_tokens == 0 && stat.total_tokens == 0 && stat.model_usage.is_empty() {
        return None;
    }

    let prompt = turn_stat_occupancy_tokens(stat);
    let completion = turn_stat_last_completion_tokens(stat);
    if prompt == 0 && completion == 0 {
        return None;
    }

    let billing_cached = turn_stat_billing_cached_tokens(stat);
    let mut cached = 0usize;
    let mut cached_estimated = false;
    if billing_cached > 0 && billing_cached <= prompt {
        cached = billing_cached;
    } else if let Some(estimated) = estimate_cache_from_previous_turn(meta, prompt) {
        cached = estimated;
        cached_estimated = true;
    }

    let ctx_window = (stat.ctx_window > 0).then_some(stat.ctx_window as usize);
    Some(footer_from_last_request(
        prompt,
        completion,
        cached,
        ctx_window,
        cached_estimated,
    ))
}

/// Global project state store (current working directory)
/// Process-global lock serialising `$JEIKCODE_HOME` mutations across ALL daemon
/// tests. `commands.rs` and `live_api.rs` compile into the same test binary and
/// both point `JEIKCODE_HOME` at a tempdir; without a shared lock their separate
/// per-module locks don't mutually exclude, so they race and read each other's
/// sessions root. One lock here fixes that.
#[cfg(test)]
pub(crate) fn jeikcode_home_test_lock() -> &'static std::sync::Mutex<()> {
    static LOCK: std::sync::OnceLock<std::sync::Mutex<()>> = std::sync::OnceLock::new();
    LOCK.get_or_init(|| std::sync::Mutex::new(()))
}

type ProjectStateStore = Arc<RwLock<ProjectState>>;

pub(crate) static DAEMON_PROJECT: std::sync::Mutex<Option<ProjectStateStore>> =
    std::sync::Mutex::new(None);

#[derive(Clone)]
struct AdmittedUser {
    content: String,
    /// Server-rendered user-facing text (user-wrap unwrapped, reminders/VL
    /// markers stripped). Live frames carry this so clients never parse protocol
    /// strings on the authoritative path.
    display_text: String,
    created_at: Option<u64>,
    /// 客户端关联键（`/chat` 的 `request_id`）。回传到 `ChatEvent::User`，让发送端
    /// 按身份认领自己的乐观气泡，而不是退化到文本比对。
    client_input_id: Option<String>,
    images: Vec<ImageData>,
}

/// One admitted `/chat` operation. Aliases include both the persisted session id
/// and the browser-generated request id so either client protocol can stop it.
struct ActiveChatOperation {
    started_at: u64,
    status: Option<String>,
    session_id: Option<String>,
    /// 客户端为本轮提供的关联键（`/chat` 的 `request_id`；`/chat/steer` 走
    /// `client_input_id` + `steered` 通道）。回传到 user 回声，供前端按 id 认领。
    request_id: Option<String>,
    aliases: Vec<String>,
    cancellation: CancellationToken,
    /// Linearizes user stop against approval consumption. A stop must mark this
    /// gate before signalling the cancellation token; approval delivery holds
    /// the same gate until the runtime has consumed (or rejected) its response.
    stop_gate: Arc<Mutex<bool>>,
    /// Signalled in `complete` so a preempting request can wait until the
    /// cancelled turn has persisted its snapshot and left the registry.
    finished: Arc<Notify>,
    stopped: bool,
    /// When terminal (Done/Error/Stopped) is sent, the turn is logically completed
    /// even if cleanup/shutdown is awaiting in background.
    terminal_reached: bool,
    /// Fan-out bus so WebUI (or other observers) can `GET /chat/watch` and
    /// reattach to a turn started by OpenAI/API clients without owning the
    /// primary SSE response.
    event_bus: tokio::sync::broadcast::Sender<(u64, ChatEvent)>,
    /// The user message admitted for this turn, recorded right when it is
    /// pushed to the conversation. `tokio::broadcast` does not replay history,
    /// so a `/chat/watch` observer that attaches *after* the turn started would
    /// otherwise never see the user's own message until the turn-boundary disk
    /// snapshot lands. Late subscribers replay this instead.
    admitted_user: Option<AdmittedUser>,
    /// Full turn event log for late joiners (page refresh mid-stream). Broadcast
    /// has no history; without this buffer a reattached WebUI only paints deltas
    /// *after* subscribe and loses thinking/text/tools already streamed.
    /// Consecutive text/reasoning deltas are coalesced to bound memory.
    replay: Arc<std::sync::Mutex<ReplayLog>>,
    /// 本回合帧的起始游标：第 i 条缓冲帧的 seq = `seq_base + i + 1`。
    /// 回合结束时把 `seq_base + 缓冲长度` 回写到会话计数器，下一回合接着往上走。
    seq_base: u64,
    /// Mid-turn steer inbox. Present only while `run_chat_turn_v2` is reading it.
    /// A submit on this channel is folded at the next round boundary; it does not
    /// cancel the in-flight model call or tool batch.
    steer_tx: Option<mpsc::UnboundedSender<live_api::ChatSteerSignal>>,
    /// FIFO of client correlation ids for `/chat/steer` submits awaiting fold.
    /// Drained by the projection when a `Steered` event lands, so the wire can
    /// echo the id and let the WebUI reconcile an in-flight steer after refresh.
    steer_client_ids: std::collections::VecDeque<Option<String>>,
    /// FIFO of arrival timestamps for `/chat/steer` submits awaiting fold.
    steer_timestamps: std::collections::VecDeque<Option<u64>>,
}

#[derive(Default)]
struct ActiveChatIndex {
    operations: HashMap<String, ActiveChatOperation>,
    aliases: HashMap<String, String>,
    /// `/chat/watch` observers that arrived while the session had NO active
    /// turn. Keyed by session id -> client id -> sender.
    standby_watchers: HashMap<String, HashMap<String, mpsc::UnboundedSender<(u64, ChatEvent)>>>,
    /// Session-scoped event state. Survives the operation: the turn's frames live
    /// in the operation, but "how far did this session get" and "what was its
    /// terminal frame" must outlive the turn.
    ///
    /// The resume cursor (`after_seq`) is session-scoped while the frames were
    /// turn-scoped — that mismatch is exactly why a subscriber attaching after the
    /// turn ended could never learn the turn was over, and the WebUI stayed stuck
    /// in "running" (red stop button, clock still ticking, checklist frozen).
    session_seq: HashMap<String, u64>,
    /// 会话级终态帧记录。
    ///
    /// 断点续传游标是会话级的，帧却只活在回合里 —— 回合一结束，断链重连 / 刷新 /
    /// 切回的订阅者就再也拿不到终态帧，前端会一直停在「运行中」（红色停止按钮 + 计时器
    /// 一直叠加 + 清单定格），只能靠切一次会话顺带修好。终态帧是整个回合最重要的一帧，
    /// 它必须活得比 operation 久，所以记在会话上而不是记在 operation 里。
    ///
    /// 键是会话的 alias；值是（序号, 帧本身）。
    session_terminal: HashMap<String, (u64, ChatEvent)>,
}

/// Atomic admission and identity-aware cleanup for background `/chat` turns.
///
/// The old `HashMap<alias, CancellationToken>` overwrote an existing entry when
/// two requests targeted the same session, then let the older task remove the
/// replacement entry during cleanup. Keeping operations and aliases in one lock
/// makes single-flight admission and compare-by-operation cleanup indivisible.
#[derive(Clone, Default)]
struct ActiveChatRegistry {
    inner: Arc<RwLock<ActiveChatIndex>>,
}

struct ActiveChatAdmission {
    operation_id: String,
    cancellation: CancellationToken,
}

/// Outcome of `subscribe_or_standby`: either attach to a running turn now
/// (`Live`) or park until a turn is admitted for this session (`Standby`).
enum WatchOutcome {
    Live(tokio::sync::broadcast::Receiver<(u64, ChatEvent)>),
    Standby,
}

#[derive(Debug)]
enum ActiveChatAdmissionError {
    SessionBusy,
    RequestBusy,
}

impl ActiveChatRegistry {
    async fn admit(
        &self,
        session_id: Option<&str>,
        request_id: Option<&str>,
    ) -> Result<ActiveChatAdmission, ActiveChatAdmissionError> {
        self.admit_occupied(
            session_id.map(str::to_string),
            request_id.map(str::to_string),
            None,
        )
        .await
    }

    /// Same as [`Self::admit`], plus an occupancy alias (compat `user` key) so a
    /// first turn that has not yet bound a UUID still serializes the same client.
    async fn admit_occupied(
        &self,
        session_id: Option<String>,
        request_id: Option<String>,
        occupancy: Option<String>,
    ) -> Result<ActiveChatAdmission, ActiveChatAdmissionError> {
        let mut index = self.inner.write().await;
        if session_id
            .as_deref()
            .is_some_and(|alias| index.aliases.contains_key(alias))
            || occupancy
                .as_deref()
                .is_some_and(|alias| index.aliases.contains_key(alias))
        {
            return Err(ActiveChatAdmissionError::SessionBusy);
        }
        if request_id
            .as_deref()
            .is_some_and(|alias| index.aliases.contains_key(alias))
        {
            return Err(ActiveChatAdmissionError::RequestBusy);
        }

        let operation_id = uuid::Uuid::new_v4().to_string();
        let cancellation = CancellationToken::new();
        let stop_gate = Arc::new(Mutex::new(false));
        // 会话级游标起点：接着上一回合的序号继续走（严格单调递增）。
        let seq_base = session_id
            .as_deref()
            .and_then(|sid| index.session_seq.get(sid).copied())
            .unwrap_or(0);
        // Capacity: expanded to 4096 to prevent Lagged event drops during heavy tool outputs / streaming.
        let (event_bus, _) = tokio::sync::broadcast::channel(4096);
        // Clone for waking standby watchers (the original moves into the operation).
        let bus_for_drain = event_bus.clone();
        let mut aliases = Vec::with_capacity(3);
        for alias in [
            session_id.as_deref(),
            request_id.as_deref(),
            occupancy.as_deref(),
        ]
        .into_iter()
        .flatten()
        {
            if !aliases.iter().any(|existing| existing == alias) {
                aliases.push(alias.to_string());
            }
        }
        for alias in &aliases {
            index.aliases.insert(alias.clone(), operation_id.clone());
        }
        let started_at = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis() as u64)
            .unwrap_or(0);
        index.operations.insert(
            operation_id.clone(),
            ActiveChatOperation {
                started_at,
                status: None,
                session_id: session_id.clone(),
                request_id,
                aliases,
                cancellation: cancellation.clone(),
                stop_gate,
                finished: Arc::new(Notify::new()),
                stopped: false,
                terminal_reached: false,
                event_bus,
                admitted_user: None,
                replay: Arc::new(std::sync::Mutex::new(ReplayLog::new(seq_base))),
                seq_base,
                steer_tx: None,
                steer_client_ids: std::collections::VecDeque::new(),
                steer_timestamps: std::collections::VecDeque::new(),
            },
        );

        // Wake any `/chat/watch` observers parked waiting for this session to
        // start a turn (event-driven push instead of client polling).
        if let Some(sid) = session_id.as_deref() {
            let drained = Self::drain_standby_locked(&mut index, sid, &bus_for_drain);
            if drained > 0 {
                tracing::debug!(
                    session_id = %sid,
                    drained,
                    "chat: drained standby watchers to live fan-out"
                );
            }
        }

        // 跨实例增量：新轮次开始 → 所有实例即时点亮该会话的活动状态。
        if let Some(sid) = session_id.clone() {
            publish_global(GlobalWireEvent::Activity {
                session_id: sid,
                running: true,
                terminal: None,
                status: None,
            });
        }

        Ok(ActiveChatAdmission {
            operation_id,
            cancellation,
        })
    }

    /// Clone the turn's event bus (for fan-out from the producer task).
    async fn event_bus(
        &self,
        operation_id: &str,
    ) -> Option<tokio::sync::broadcast::Sender<(u64, ChatEvent)>> {
        self.inner
            .read()
            .await
            .operations
            .get(operation_id)
            .map(|op| op.event_bus.clone())
    }

    /// Set the human/client-visible operation status (e.g. "compacting").
    pub async fn set_operation_status(&self, operation_id: &str, status: Option<String>) {
        let mut index = self.inner.write().await;
        if let Some(op) = index.operations.get_mut(operation_id) {
            op.status = status;
        }
    }

    /// Event bus + shared replay log for a turn (fan-out records into `replay`).
    async fn event_bus_with_replay(
        &self,
        operation_id: &str,
    ) -> Option<(
        tokio::sync::broadcast::Sender<(u64, ChatEvent)>,
        Arc<std::sync::Mutex<ReplayLog>>,
    )> {
        self.inner
            .read()
            .await
            .operations
            .get(operation_id)
            .map(|op| (op.event_bus.clone(), op.replay.clone()))
    }

    /// Broadcast an event to any live subscriber or parked standby watcher of `session_id`.
    /// Used for out-of-turn differential mutations (rewrite, delete, truncate) so all
    /// open tabs stay synchronized without polling or full-transcript reloads.
    pub async fn broadcast_to_session(&self, session_id: &str, event: ChatEvent) {
        let index = self.inner.read().await;
        let mut seq = 0u64;
        if let Some(operation_id) = index.aliases.get(session_id) {
            if let Some(operation) = index.operations.get(operation_id) {
                // 会话变更（删/改/截断）改写了权威转录：本回合的旧帧立即作废，
                // 否则带旧游标或全量重连会把变更前发出的帧补回来（已删内容复活）。
                let mut log = operation
                    .replay
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                if matches!(event, ChatEvent::SessionMutation { .. }) {
                    log.events.clear();
                }
                seq = log.push(event.clone());
                let _ = operation.event_bus.send((seq, event.clone()));
            }
        }
        if let Some(watchers) = index.standby_watchers.get(session_id) {
            for tx in watchers.values() {
                let _ = tx.send((seq, event.clone()));
            }
        }
    }

    /// Snapshot of events so far for a late `/chat/watch` joiner.
    /// Holds the replay lock while creating the broadcast subscription so no
    /// event can land only on the bus (missed by both snapshot and subscriber).
    async fn subscribe_live_with_replay(
        &self,
        session_id: &str,
    ) -> Option<(
        Vec<(u64, ChatEvent)>,
        tokio::sync::broadcast::Receiver<(u64, ChatEvent)>,
    )> {
        let index = self.inner.read().await;
        let operation_id = index.aliases.get(session_id)?.clone();
        let operation = index.operations.get(&operation_id)?;
        // A terminal turn is NOT a reason to bail out: the terminal frame may still
        // be queued for the fan-out. Handing back the snapshot plus the bus lets a
        // watcher that attaches now either read the terminal from the snapshot or
        // receive it live — instead of parking, which means keepalives only and a
        // client that waits forever.
        let guard = operation
            .replay
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        // 游标就是缓冲序号（从 1 开始）：缓冲是追加式的（连续同身份合并只改最后一条的内容，
        // 不改它的位置），所以同一个事件的 seq 永远稳定 —— 断点续传靠的就是这一点。
        let mut snapshot: Vec<(u64, ChatEvent)> = guard.events.clone();
        let rx = operation.event_bus.subscribe();
        drop(guard);
        if let Some(ref admitted) = operation.admitted_user {
            if !snapshot
                .iter()
                .any(|(_, e)| matches!(e, ChatEvent::User { .. }))
            {
                // 本轮提问的回声：不占游标（seq 0），因为它是幂等的用户气泡。
                snapshot.insert(
                    0,
                    (
                        operation.seq_base,
                        ChatEvent::User {
                            content: admitted.content.clone(),
                            display_text: Some(admitted.display_text.clone()),
                            internal: Some(false),
                            editable: Some(true),
                            session_id: Some(session_id.to_string()),
                            created_at: admitted
                                .created_at
                                .or((operation.started_at > 0).then_some(operation.started_at)),
                            message_id: admitted.client_input_id.clone(),
                            order: None,
                            turn_ordinal: None,
                            client_input_id: admitted.client_input_id.clone(),
                            images: (!admitted.images.is_empty()).then(|| admitted.images.clone()),
                        },
                    ),
                );
            }
        }
        Some((snapshot, rx))
    }

    /// Unanswered permission / user-input prompts for an active session, derived
    /// from the turn replay log. Empty when the session is idle or the turn has
    /// already terminated.
    async fn pending_interactive(
        &self,
        session_id: &str,
    ) -> (Option<ChatEvent>, Option<ChatEvent>) {
        let index = self.inner.read().await;
        let Some(operation_id) = index.aliases.get(session_id) else {
            return (None, None);
        };
        let Some(operation) = index.operations.get(operation_id) else {
            return (None, None);
        };
        if operation.terminal_reached || operation.stopped {
            return (None, None);
        }
        let guard = operation
            .replay
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        pending_interactive_from_replay(&guard.events)
    }

    /// True when the turn replay already closed `call_id` (result/output/terminal).
    /// Stale `pending_permission.json` must not restore a card in that case.
    async fn replay_resolves_call(&self, session_id: &str, call_id: &str) -> bool {
        let index = self.inner.read().await;
        let Some(operation_id) = index.aliases.get(session_id) else {
            return false;
        };
        let Some(operation) = index.operations.get(operation_id) else {
            return false;
        };
        let guard = operation
            .replay
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        replay_resolves_call(&guard.events, call_id)
    }

    /// Subscribe to a session's turn **if one is already running**, otherwise
    /// park the caller as a standby watcher so `admit` can wake it the instant an
    /// API/native turn starts for this session. This is the event-driven path
    /// that lets the WebUI observe an API turn without polling: the watch
    /// connection stays open (SSE keepalive) while idle and is converted to a
    /// live broadcast subscriber the moment a turn is admitted.
    async fn subscribe_or_standby(
        &self,
        session_id: &str,
        client_id: Option<&str>,
        standby_tx: &mpsc::UnboundedSender<(u64, ChatEvent)>,
        replay_terminal: bool,
    ) -> WatchOutcome {
        let mut index = self.inner.write().await;
        if let Some(operation_id) = index.aliases.get(session_id).cloned() {
            if let Some(operation) = index.operations.get(&operation_id) {
                if !operation.terminal_reached && !operation.stopped {
                    return WatchOutcome::Live(operation.event_bus.subscribe());
                }
            }
            index.aliases.remove(session_id);
        }
        // The session's turn is over (or never started). Hand the watcher the
        // terminal frame recorded on the session — parking here would mean
        // keepalives only and a client that waits forever for a finished turn.
        //
        // The lookup is by session id and deliberately independent of the alias:
        // the alias is gone once the operation is cleaned up, and a watcher
        // attaching after the turn ended is exactly the case that must not hang.
        //
        // Only the reattach path asks for it: the idle standby watcher must stay
        // silent, or it would re-deliver the same terminal on every re-arm and
        // spin.
        if replay_terminal {
            if let Some((seq, terminal)) = index.session_terminal.get(session_id) {
                let _ = standby_tx.send((*seq, terminal.clone()));
            }
        }
        // Multi-client standby pool: prune dead senders, and update or register this client_id.
        // A single tab refreshing reuses its client_id and replaces its own dead sender without piling up;
        // multiple independent remote clients with distinct client_ids stay concurrently subscribed.
        let entry = index
            .standby_watchers
            .entry(session_id.to_string())
            .or_default();
        entry.retain(|_, tx| !tx.is_closed());
        let cid = client_id.unwrap_or("").trim();
        let key = if cid.is_empty() {
            uuid::Uuid::new_v4().to_string()
        } else {
            cid.to_string()
        };
        // Hard capacity cap per session (max 16 concurrent standby tabs/devices) to prevent unbounded memory growth.
        if entry.len() >= 16 && !entry.contains_key(&key) {
            if let Some(oldest_key) = entry.keys().next().cloned() {
                entry.remove(&oldest_key);
            }
        }
        entry.insert(key, standby_tx.clone());
        WatchOutcome::Standby
    }

    /// Record the user message admitted for this turn so a *late* `/chat/watch`
    /// subscriber (one that attaches after the broadcast, and therefore missed
    /// the live `ChatEvent::User`) can replay it. The bus itself never replays.
    async fn record_user_message(
        &self,
        operation_id: &str,
        content: String,
        display_text: String,
        created_at: Option<u64>,
        images: Vec<ImageData>,
    ) {
        if let Some(op) = self.inner.write().await.operations.get_mut(operation_id) {
            let created = created_at.or((op.started_at > 0).then_some(op.started_at));
            let client_input_id = op.request_id.clone();
            op.admitted_user = Some(AdmittedUser {
                content,
                display_text,
                created_at: created,
                client_input_id,
                images,
            });
        }
    }

    /// Resolve a session alias to its currently-admitted operation id.
    async fn operation_for_session(&self, session_id: &str) -> Option<String> {
        self.inner.read().await.aliases.get(session_id).cloned()
    }

    /// The user message admitted for `operation_id`, if the turn has already
    /// recorded one (i.e. the turn started before this watcher subscribed).
    async fn admitted_user_message(&self, operation_id: &str) -> Option<AdmittedUser> {
        self.inner
            .read()
            .await
            .operations
            .get(operation_id)
            .and_then(|op| op.admitted_user.clone())
    }

    /// Resolve an admitted user message directly by session id.
    async fn admitted_user_for_session(&self, session_id: &str) -> Option<AdmittedUser> {
        let op_id = self.operation_for_session(session_id).await?;
        self.admitted_user_message(&op_id).await
    }

    async fn replay_admitted_user(
        &self,
        session_id: &str,
        tx: &mpsc::UnboundedSender<(u64, ChatEvent)>,
    ) {
        let Some(operation_id) = self.operation_for_session(session_id).await else {
            return;
        };
        let (admitted, started_at) = {
            let index = self.inner.read().await;
            let op = index.operations.get(&operation_id);
            (
                op.and_then(|o| o.admitted_user.clone()),
                op.map(|o| o.started_at).unwrap_or(0),
            )
        };
        let Some(admitted) = admitted else {
            return;
        };
        let created_at = admitted
            .created_at
            .or((started_at > 0).then_some(started_at));
        let _ = tx.send((
            0,
            ChatEvent::User {
                content: admitted.content,
                display_text: Some(admitted.display_text),
                internal: Some(false),
                editable: Some(true),
                session_id: Some(session_id.to_string()),
                created_at,
                message_id: admitted.client_input_id.clone(),
                order: None,
                turn_ordinal: None,
                client_input_id: admitted.client_input_id,
                images: (!admitted.images.is_empty()).then(|| admitted.images),
            },
        ));
    }

    /// Drain (wake) all standby watchers parked for `session_id`, converting
    /// each to a live broadcast subscriber on `bus`. Called from `admit` while
    /// still holding the write lock so no watcher can be added between the
    /// alias insert and the drain.
    fn drain_standby_locked(
        index: &mut ActiveChatIndex,
        session_id: &str,
        bus: &tokio::sync::broadcast::Sender<(u64, ChatEvent)>,
    ) -> usize {
        if let Some(mut watchers) = index.standby_watchers.remove(session_id) {
            watchers.retain(|_, tx| !tx.is_closed());
            let n = watchers.len();
            for (_cid, tx) in watchers {
                let mut rx = bus.subscribe();
                tokio::spawn(async move {
                    loop {
                        match rx.recv().await {
                            Ok((seq, event)) => {
                                let terminal = matches!(
                                    event,
                                    ChatEvent::Done { .. }
                                        | ChatEvent::Error { .. }
                                        | ChatEvent::Stopped
                                );
                                if tx.send((seq, event)).is_err() {
                                    break;
                                }
                                if terminal {
                                    break;
                                }
                            }
                            Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => continue,
                            Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
                        }
                    }
                });
            }
            n
        } else {
            0
        }
    }

    /// Bind the runtime's canonical session id after a first-turn session has
    /// been allocated (or a requested id has been resolved to its canonical id).
    async fn bind_session(&self, operation_id: &str, session_id: &str) -> anyhow::Result<()> {
        let mut index = self.inner.write().await;
        if let Some(owner) = index.aliases.get(session_id) {
            if owner != operation_id {
                anyhow::bail!("chat session {session_id} became active while this turn started");
            }
        }
        let operation = index
            .operations
            .get_mut(operation_id)
            .ok_or_else(|| anyhow::anyhow!("chat operation is no longer active"))?;
        operation.session_id = Some(session_id.to_string());
        if !operation.aliases.iter().any(|alias| alias == session_id) {
            operation.aliases.push(session_id.to_string());
        }
        index
            .aliases
            .insert(session_id.to_string(), operation_id.to_string());
        Ok(())
    }

    /// Mark and cooperatively cancel an operation addressed by either alias.
    async fn stop_alias(&self, alias: &str) -> bool {
        let operation_id = {
            let index = self.inner.read().await;
            let Some(operation_id) = index.aliases.get(alias).cloned() else {
                return false;
            };
            operation_id
        };
        self.stop_operation(&operation_id).await
    }

    /// Stop the occupant of `alias` (same path as WebUI `/chat/stop`) and wait
    /// until it leaves the registry. `true` means the alias is idle (already
    /// gone, or the cancelled turn finished). `false` means the timeout fired
    /// while the previous turn was still persisting.
    ///
    /// `timeout = None` waits for the release to be real instead of timing out.
    /// Send-now callers need that verdict: a hard cap there misreported
    /// "still busy" for turns that were already releasing, which pushed the
    /// user's message back into the queue. `Some(limit)` keeps the bounded
    /// behaviour of the session-deletion paths.
    async fn stop_and_wait(&self, alias: String, timeout: Option<Duration>) -> bool {
        let operation_id = {
            let index = self.inner.read().await;
            let Some(operation_id) = index.aliases.get(&alias).cloned() else {
                return true;
            };
            if !index.operations.contains_key(operation_id.as_str()) {
                return true;
            }
            operation_id
        };
        self.stop_alias_owned(alias).await;
        let await_release = async {
            loop {
                let finished = {
                    let index = self.inner.read().await;
                    match index.operations.get(&operation_id) {
                        None => return,
                        Some(operation) => operation.finished.clone(),
                    }
                };
                let notified = finished.notified();
                {
                    let index = self.inner.read().await;
                    if !index.operations.contains_key(&operation_id) {
                        return;
                    }
                }
                notified.await;
            }
        };
        match timeout {
            Some(limit) => tokio::time::timeout(limit, await_release).await.is_ok(),
            // Unterminated wait: the operation always leaves the registry (the
            // chat task completes even on panic), so this resolves, not hangs.
            None => {
                await_release.await;
                true
            }
        }
    }

    async fn stop_alias_owned(&self, alias: String) -> bool {
        let operation_id = {
            let index = self.inner.read().await;
            let Some(operation_id) = index.aliases.get(&alias).cloned() else {
                return false;
            };
            operation_id
        };
        self.stop_operation(&operation_id).await
    }

    async fn stop_operation(&self, operation_id: &str) -> bool {
        let (cancellation, stop_gate, op_session_id) = {
            let index = self.inner.read().await;
            let Some(operation) = index.operations.get(operation_id) else {
                return false;
            };
            (
                operation.cancellation.clone(),
                operation.stop_gate.clone(),
                operation.session_id.clone(),
            )
        };

        // This is the stop/approval linearization point. If an approval already
        // holds the gate, its runtime consumption wins and this stop follows it.
        // Otherwise mark stopped before the cancellation token becomes visible,
        // so a later approval cannot cross the runtime boundary.
        {
            let mut stopped = stop_gate.lock().await;
            *stopped = true;
        }
        {
            let mut index = self.inner.write().await;
            if let Some(operation) = index.operations.get_mut(operation_id) {
                operation.stopped = true;
            }
        }
        cancellation.cancel();
        if let Some(ref sid) = op_session_id {
            jeikcode_capabilities::tools::bash_runtime::cancel_foreground_live_bash_for_session(
                sid,
            );
        } else {
            jeikcode_capabilities::tools::legacy_bash_runtime_state().cancel_foreground_live_bash();
        }
        true
    }

    async fn stop_gate(&self, operation_id: &str) -> Option<Arc<Mutex<bool>>> {
        self.inner
            .read()
            .await
            .operations
            .get(operation_id)
            .map(|operation| operation.stop_gate.clone())
    }

    /// Compat latest-wins: if the session is busy, cancel the running turn
    /// (bash/tools included), wait for snapshot persist + `complete`, then admit.
    /// Retries until this caller occupies the aliases or `timeout` elapses.
    ///
    /// Takes `self` by value (cheap Arc clone) so axum handlers stay `Send`.
    async fn admit_or_preempt(
        self,
        session_id: Option<String>,
        occupancy: Option<String>,
        timeout: Duration,
    ) -> Result<ActiveChatAdmission, ActiveChatAdmissionError> {
        let deadline = tokio::time::Instant::now() + timeout;
        loop {
            match self
                .admit_occupied(session_id.clone(), None, occupancy.clone())
                .await
            {
                Ok(admission) => return Ok(admission),
                Err(ActiveChatAdmissionError::RequestBusy) => {
                    return Err(ActiveChatAdmissionError::RequestBusy);
                }
                Err(ActiveChatAdmissionError::SessionBusy) => {
                    let remaining = deadline.saturating_duration_since(tokio::time::Instant::now());
                    if remaining.is_zero() {
                        return Err(ActiveChatAdmissionError::SessionBusy);
                    }
                    // The occupant may be keyed by UUID, by the compat `user`
                    // alias, or both. A first turn often occupies only the user
                    // key until `bind_session` lands — stopping only the UUID
                    // would spin until timeout.
                    let mut keys = Vec::new();
                    if let Some(sid) = session_id.clone() {
                        keys.push(sid);
                    }
                    if let Some(occ) = occupancy.clone() {
                        keys.push(occ);
                    }
                    if !self.stop_and_wait_any(keys, remaining).await {
                        return Err(ActiveChatAdmissionError::SessionBusy);
                    }
                }
            }
        }
    }

    async fn stop_and_wait_any(&self, aliases: Vec<String>, timeout: Duration) -> bool {
        let deadline = tokio::time::Instant::now() + timeout;
        let mut saw_alias = false;
        for alias in aliases {
            saw_alias = true;
            let remaining = deadline.saturating_duration_since(tokio::time::Instant::now());
            if remaining.is_zero() {
                return false;
            }
            if !self.stop_and_wait(alias, Some(remaining)).await {
                return false;
            }
        }
        saw_alias
    }

    async fn was_stopped(&self, operation_id: &str) -> bool {
        self.inner
            .read()
            .await
            .operations
            .get(operation_id)
            .is_some_and(|operation| operation.stopped)
    }

    async fn session_id(&self, operation_id: &str) -> Option<String> {
        self.inner
            .read()
            .await
            .operations
            .get(operation_id)
            .and_then(|operation| operation.session_id.clone())
    }

    /// Attach the turn's steer inbox. Lookup is by any alias (session id or request id).
    async fn install_steer(
        &self,
        operation_id: &str,
        tx: mpsc::UnboundedSender<live_api::ChatSteerSignal>,
    ) {
        let mut index = self.inner.write().await;
        if let Some(operation) = index.operations.get_mut(operation_id) {
            operation.steer_tx = Some(tx);
        }
    }

    async fn steer_sender(
        &self,
        alias: &str,
    ) -> Option<mpsc::UnboundedSender<live_api::ChatSteerSignal>> {
        let index = self.inner.read().await;
        let operation_id = index.aliases.get(alias)?;
        index.operations.get(operation_id)?.steer_tx.clone()
    }

    /// Record a `/chat/steer` submit's client correlation id and timestamp (FIFO)
    /// so the turn projection can echo them on `steered`.
    async fn record_steer_metadata(
        &self,
        alias: &str,
        client_input_id: Option<String>,
        created_at: Option<u64>,
    ) {
        let mut index = self.inner.write().await;
        if let Some(operation_id) = index.aliases.get(alias).cloned() {
            if let Some(operation) = index.operations.get_mut(&operation_id) {
                operation.steer_client_ids.push_back(client_input_id);
                operation.steer_timestamps.push_back(created_at);
            }
        }
    }

    /// Remove a cancelled steer's correlation id and timestamp so a later steer
    /// fold never pops the cancelled steer's stale metadata.
    async fn cancel_steer_metadata(&self, alias: &str, client_input_id: Option<&str>) {
        let mut index = self.inner.write().await;
        let Some(operation_id) = index.aliases.get(alias).cloned() else {
            return;
        };
        let Some(operation) = index.operations.get_mut(&operation_id) else {
            return;
        };
        if let Some(cid) = client_input_id.map(str::trim).filter(|s| !s.is_empty()) {
            if let Some(pos) = operation
                .steer_client_ids
                .iter()
                .position(|entry| entry.as_deref() == Some(cid))
            {
                operation.steer_client_ids.remove(pos);
                operation.steer_timestamps.remove(pos);
            }
        } else {
            operation.steer_client_ids.clear();
            operation.steer_timestamps.clear();
        }
    }

    /// Drain up to `count` recorded steer client ids and timestamps for the operation,
    /// matching by the kernel's preserved `SteeredInput.message_id` when present so an
    /// out-of-band or cancelled steer cannot shift the FIFO alignment.
    async fn take_steer_metadata_for_inputs(
        &self,
        operation_id: &str,
        count: usize,
        inputs: &[jeikcode_kernel::event::SteeredInput],
    ) -> (Vec<Option<String>>, Vec<Option<u64>>) {
        let mut index = self.inner.write().await;
        let Some(operation) = index.operations.get_mut(operation_id) else {
            return (Vec::new(), Vec::new());
        };
        let mut ids = Vec::with_capacity(count);
        let mut timestamps = Vec::with_capacity(count);
        for i in 0..count {
            let kernel_id = inputs
                .get(i)
                .and_then(|inp| inp.message_id.as_deref())
                .filter(|s| !s.is_empty());
            if let Some(kid) = kernel_id {
                if let Some(pos) = operation
                    .steer_client_ids
                    .iter()
                    .position(|entry| entry.as_deref() == Some(kid))
                {
                    let id = operation.steer_client_ids.remove(pos).unwrap_or(None);
                    let ts = operation.steer_timestamps.remove(pos).unwrap_or(None);
                    ids.push(id.or_else(|| Some(kid.to_string())));
                    timestamps.push(ts);
                    continue;
                }
                ids.push(Some(kid.to_string()));
                let ts = if operation
                    .steer_client_ids
                    .front()
                    .is_some_and(|entry| entry.is_none())
                {
                    let _ = operation.steer_client_ids.pop_front();
                    operation.steer_timestamps.pop_front().unwrap_or(None)
                } else {
                    None
                };
                timestamps.push(ts);
            } else {
                ids.push(operation.steer_client_ids.pop_front().unwrap_or(None));
                timestamps.push(operation.steer_timestamps.pop_front().unwrap_or(None));
            }
        }
        (ids, timestamps)
    }

    /// Remove only the exact operation that finished. A late cleanup from an
    /// older generation can never erase a replacement operation's aliases.
    async fn complete(&self, operation_id: &str) -> bool {
        let mut index = self.inner.write().await;
        let Some(operation) = index.operations.remove(operation_id) else {
            return false;
        };
        // 会话级游标推进：把本回合已发出的帧数累加进去，下一回合从更高的序号开始。
        // 严格单调递增，且与上下文/压缩无关。
        let next_base = operation
            .replay
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .high_water();
        for alias in &operation.aliases {
            index.session_seq.insert(alias.clone(), next_base);
        }
        for alias in operation.aliases {
            if index
                .aliases
                .get(&alias)
                .is_some_and(|owner| owner == operation_id)
            {
                index.aliases.remove(&alias);
            }
        }
        operation.finished.notify_waiters();
        // 跨实例增量：操作结束 → 活动状态回落（不触发任何整表重拉）。
        if let Some(sid) = operation.session_id.clone() {
            // 只结束属于本次 operation 的阶段：手动压缩归 `manual:<op>`，
            // `/chat` 自动压缩归 `turn` 前缀。绝不能无条件清掉 live 或别的 owner
            // 正在执行的压缩（旧实现正是这样让刷新误杀另一条链路）。
            let manual_owner = manual_compaction_owner(operation_id);
            finish_compaction_phase(&sid, &manual_owner, false);
            finish_compaction_phase_prefix(&sid, COMPACTION_OWNER_TURN, false);
            publish_global(GlobalWireEvent::Activity {
                session_id: sid,
                running: false,
                terminal: None,
                status: None,
            });
        }
        true
    }

    /// Mark that a terminal event (Done, Stopped, or Error) has been emitted, and
    /// record that terminal frame **on the session** in the same critical section
    /// that raises the flag.
    ///
    /// The flag used to become visible before the terminal frame existed anywhere:
    /// the frame was still queued for the fan-out task, so a watcher attaching in
    /// that window saw "already terminal" with nothing to replay — and it parked,
    /// and parking means keepalives only, never a terminal. The WebUI then stayed
    /// in "running" forever (red stop button, clock still ticking, checklist
    /// frozen) until the user happened to switch sessions.
    ///
    /// Recording the frame here makes "this turn is over" and "here is its
    /// terminal frame" a single fact, so a late watcher can always be told.
    async fn mark_terminal(&self, operation_id: &str, terminal: &ChatEvent) {
        let mut index = self.inner.write().await;
        let Some(op) = index.operations.get_mut(operation_id) else {
            return;
        };
        // The terminal frame takes the next slot in the turn's replay log, so its
        // cursor is the same number the replay snapshot hands out.
        let seq = op
            .replay
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .high_water()
            .saturating_add(1);
        op.terminal_reached = true;
        let aliases = op.aliases.clone();
        for alias in aliases {
            index
                .session_terminal
                .insert(alias, (seq, terminal.clone()));
        }
    }

    /// Evict all in-memory tracking state (sequences, cached terminal frames, standby watchers, aliases)
    /// when a session is deleted, preventing resource leakage across session lifecycles.
    pub(crate) async fn clear_session(&self, session_id: &str) {
        let mut index = self.inner.write().await;
        index.session_seq.remove(session_id);
        index.session_terminal.remove(session_id);
        index.standby_watchers.remove(session_id);
        index.aliases.remove(session_id);
    }

    async fn active_session_ids(&self) -> Vec<String> {
        let mut sessions: Vec<String> = self
            .inner
            .read()
            .await
            .operations
            .values()
            .filter(|operation| !operation.terminal_reached)
            .filter_map(|operation| operation.session_id.clone())
            .collect();
        sessions.sort();
        sessions.dedup();
        sessions
    }

    async fn has_active_operations(&self) -> bool {
        !self.inner.read().await.operations.is_empty()
    }

    #[cfg(test)]
    async fn cancel_all(&self) {
        let cancellations: Vec<(CancellationToken, Arc<Mutex<bool>>)> = self
            .inner
            .read()
            .await
            .operations
            .values()
            .map(|operation| (operation.cancellation.clone(), operation.stop_gate.clone()))
            .collect();
        for (cancellation, stop_gate) in cancellations {
            *stop_gate.lock().await = true;
            cancellation.cancel();
        }
    }
}

const DANGEROUS_TOOLS_ENV: &str = "JEIKCODE_DAEMON_ENABLE_DANGEROUS_TOOLS";

/// RAII guard that decrements `active_connections` on drop, ensuring the counter
/// is always decremented even if the SSE client disconnects abruptly (TCP RST).
struct SseConnectionGuard(Arc<std::sync::atomic::AtomicUsize>);

/// Truncate a value for diagnostic logging, cutting at a char boundary so a
/// multi-byte (CJK etc.) argument never panics `&s[..n]`.
fn log_truncate(value: &str, max: usize) -> String {
    if value.chars().count() <= max {
        return value.to_string();
    }
    let mut out = String::with_capacity(max + 3);
    for ch in value.chars().take(max) {
        out.push(ch);
    }
    out.push('…');
    out
}

/// Scan a turn's replay log for interactive prompts that are still unanswered.
/// Used by `GET /chat/pending` so a refreshed WebUI can restore approval /
/// user-input cards even if it misses the SSE edge that first emitted them.
///
/// A `PermissionRequest` is still pending when no later `ToolCallResult` (or
/// terminal) has closed that `call_id`. A `UserInputRequest` is pending until
/// a later `request_user_input` tool result or the turn ends — TUI/live can
/// answer or decline without a dedicated chat-bus resolve event.
fn pending_interactive_from_replay(
    events: &[(u64, ChatEvent)],
) -> (Option<ChatEvent>, Option<ChatEvent>) {
    // A PermissionRequest is only "answered" by a resolution event that occurs
    // AFTER it (by index). A tool that started / produced output / returned a
    // result BEFORE the request cannot be what answered it, so a genuinely
    // unanswered card (the request being the newest event) is still restored.
    // This preserves the in-flight-tool-switch guard (a resolved tool is never
    // re-toasted) while no longer dropping an unanswered request that happens to
    // share a call id with an earlier ToolCallStarted.
    let mut last_permission: Option<(usize, ChatEvent)> = None;
    let mut last_user_input: Option<ChatEvent> = None;
    let mut last_resolution: std::collections::HashMap<String, usize> =
        std::collections::HashMap::new();
    let mut turn_terminal = false;
    for (index, (_, event)) in events.iter().enumerate() {
        match event {
            ChatEvent::ToolCallStarted { id, .. } => {
                // Tool already started running — approval was granted / not needed.
                last_resolution.insert(id.clone(), index);
            }
            // Execution returned ⇒ the call necessarily got past its gate, even when
            // the authoritative result frame has not been applied yet (batch order).
            ChatEvent::ToolFinished { id, .. } => {
                last_resolution.insert(id.clone(), index);
            }
            ChatEvent::ToolCallResult { id, name, .. } => {
                last_resolution.insert(id.clone(), index);
                if name == "request_user_input" {
                    last_user_input = None;
                }
            }
            ChatEvent::ToolOutputChunk { id, .. } => {
                // Output means the tool already started — approval was granted.
                last_resolution.insert(id.clone(), index);
            }
            ChatEvent::Done { .. } | ChatEvent::Stopped | ChatEvent::Error { .. } => {
                turn_terminal = true;
            }
            ChatEvent::PermissionRequest { .. } => {
                last_permission = Some((index, event.clone()));
            }
            ChatEvent::UserInputRequest { .. } => {
                last_user_input = Some(event.clone());
            }
            _ => {}
        }
    }
    if turn_terminal {
        return (None, None);
    }
    let permission = last_permission.and_then(|(req_index, ev)| match &ev {
        ChatEvent::PermissionRequest { call_id, .. } => {
            let answered = last_resolution
                .get(call_id)
                .is_some_and(|&res_index| res_index > req_index);
            (!answered).then_some(ev)
        }
        _ => None,
    });
    let user_input = last_user_input;
    (permission, user_input)
}

fn replay_resolves_call(events: &[(u64, ChatEvent)], call_id: &str) -> bool {
    events.iter().any(|(_, event)| match event {
        ChatEvent::ToolCallStarted { id, .. }
        | ChatEvent::ToolCallResult { id, .. }
        | ChatEvent::ToolFinished { id, .. }
        | ChatEvent::ToolOutputChunk { id, .. } => id == call_id,
        ChatEvent::Done { .. } | ChatEvent::Stopped | ChatEvent::Error { .. } => true,
        _ => false,
    })
}

/// 全局失效总线（跨实例推送）。
///
/// 现有推送通道都是「按会话」的：`SessionRuntimeRegistry` 每个会话一条
/// broadcast（订阅必须带 session_id），`LiveViewHub` 只绑定一个执行会话，
/// `/chat/watch` 同样需要指定会话。于是「实例 B」无从得知「实例 A 新建/删除了
/// 会话、某会话弹出了审批/提问卡」——只能靠窗口聚焦重拉（历史上的 15s 轮询
/// 兜底已被拔除）。这里补上唯一缺失的一环：一条进程级全局广播 + `/events`。
///
/// 只发「失效信号」（不发 payload 副本）：客户端收到后单次重拉既有接口，
/// 保证实时性的同时让数据形状与一致性仍由单一数据源决定。
#[derive(Clone, Debug, serde::Serialize)]
#[serde(tag = "type")]
pub(crate) enum GlobalWireEvent {
    /// 会话行新增/更新（新建、改名、回合完成后的 updated_at/message_count）。
    /// 客户端按 id 就地 upsert，不重拉列表。
    #[serde(rename = "session_upsert")]
    SessionUpsert { session: SessionRowWire },
    /// 会话删除（含批量）：客户端就地删行并丢弃该 id 的本地缓存。
    #[serde(rename = "session_deleted")]
    SessionDeleted {
        session_id: String,
        project_hash: String,
    },
    /// 某会话已被用户打开/查看：其它实例据此熄灭该会话的「刚完成」徽标。
    ///
    /// 徽标由全局 `activity` 广播点亮，熄灭也必须走同一条全局总线，
    /// 否则只清当前实例会在其它标签页/浏览器上留下幽灵勾。
    #[serde(rename = "session_seen")]
    SessionSeen { session_id: String },
    /// 会话转录被显式变更（编辑 / 删除 / 回溯 / 压缩）。
    ///
    /// 与 `session_mutation` 的区别：那条走**会话总线**，只送达“正在看这个会话”
    /// 的订阅者；本事件走**全局总线**，让没打开该会话的标签页/浏览器也能立刻作废
    /// 本地缓存。只带 revision，不背 payload —— 客户端按版本决定是否重取。
    #[serde(rename = "session_mutated")]
    SessionMutated {
        session_id: String,
        /// 变更后的权威版本；客户端只接受 `incoming >= stored`。
        revision: u64,
    },
    /// 一条已落盘的展示记录（压缩边界、警告等）刚刚追加。
    ///
    /// display 追加不一定改变 snapshot 的 `cache_epoch`；单靠
    /// `session_mutated` 的 revision 闸门会让“恰好已知同版本”的客户端跳过重取。
    /// 本事件只带 session id，客户端做一次定向磁盘尾部对账即可。
    #[serde(rename = "display_appended")]
    DisplayAppended { session_id: String },
    /// 活动/转圈变化；`terminal` 非空时同时携带终态供右下角通知去重；`status` 可携带 "compacting" 等阶段状态。
    ///
    /// 兼容旧客户端保留；新客户端应优先消费 `runtime_activity`（带 revision/owner）。
    #[serde(rename = "activity")]
    Activity {
        session_id: String,
        running: bool,
        #[serde(skip_serializing_if = "Option::is_none")]
        terminal: Option<&'static str>,
        #[serde(skip_serializing_if = "Option::is_none")]
        status: Option<String>,
    },
    /// 会话执行态的权威快照（阶段 + revision + owner）。
    ///
    /// 这是压缩/运行态的唯一阶段信号：客户端只接受 `revision` 更高的快照，
    /// 不再根据单个 `status` 字段或事件到达顺序猜测阶段。
    #[serde(rename = "runtime_activity")]
    RuntimeActivity {
        session_id: String,
        revision: u64,
        running: bool,
        #[serde(skip_serializing_if = "Option::is_none")]
        phase: Option<String>,
        #[serde(skip_serializing_if = "Option::is_none")]
        phase_started_at: Option<u64>,
        #[serde(skip_serializing_if = "Option::is_none")]
        owner: Option<String>,
    },
    /// 某会话弹出待交互卡片（审批/提问）。只带会话 id，客户端对该会话做一次
    /// 定向 pending 拉取（单会话、小请求），避免重拉整表。
    #[serde(rename = "review_asked")]
    ReviewAsked { session_id: String },
    /// 会话待发卡片队列（排队 / 转向中 / 转向已排队）变化：创建、点转向、取消、
    /// 被内核消费都算。只带会话 id，客户端对该会话做一次定向 `/chat/queue` 拉取，
    /// 既不背大 payload，也不重拉整表。
    #[serde(rename = "queue_updated")]
    QueueUpdated { session_id: String },
    /// 中途转向已被内核 fold：携带权威输入。活跃视图由 `/chat/watch` 的 `steered`
    /// 帧落笔（带光标与归位锚点）；本事件让**其它会话/其它客户端**把这条提问提前
    /// 写进该会话的本地画布缓存，切过去或冷启动时用户气泡已经在里面。
    ///
    /// 只传文本/身份，**不传图片本体**（可能是一整张 base64）：各端自己队列卡片里
    /// 就有原图，随后的 `queue_updated` 也会把已被消费的卡片收走。
    #[serde(rename = "steer_folded")]
    SteerFolded {
        session_id: String,
        inputs: Vec<SteerFoldedInputWire>,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        client_input_ids: Vec<Option<String>>,
    },
    /// 模型配置变更（会话聊天模型 / 思考强度 / 思考预算）。
    ///
    /// 只带**本会话实际生效的值**：`provider` 为模型选择 id，`effort` 存在时
    /// 两个字段都按快照下发（`null` = 显式清空/继承模型默认）。其它客户端据此更新
    /// 下拉框与会话缓存；本轮仍在跑时参数已落盘，停止后下一轮自然生效。
    #[serde(rename = "model_config")]
    ModelConfig {
        /// `Some` = 会话级；`None` = 新会话默认模型变了。
        #[serde(skip_serializing_if = "Option::is_none")]
        session_id: Option<String>,
        #[serde(skip_serializing_if = "Option::is_none")]
        provider: Option<String>,
        #[serde(skip_serializing_if = "Option::is_none")]
        effort: Option<ModelEffortWire>,
        /// 本轮仍在跑，参数已落盘、下一轮生效（仅作 UI 提示，不参与合并）。
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        deferred: bool,
    },
    /// 待交互卡片已解决：客户端直接就地移除卡片。
    #[serde(rename = "review_resolved")]
    ReviewResolved {
        session_id: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        approval_id: Option<String>,
        #[serde(skip_serializing_if = "Option::is_none")]
        request_id: Option<u64>,
    },
    /// 全局配置热重载（如 CLI 执行 jeikcode ghimg 或后台变更）。
    #[serde(rename = "config_reloaded")]
    ConfigReloaded,
    /// Git 仓库状态变更（discard / stage / commit / pull / fetch / checkout 等），跨设备全量广播。
    /// `fetch: true` 表示「分支/远端引用可能已变」：客户端除本地刷新外，还应（按自身节流）
    /// 补一次 `git fetch`（只更新 remote-tracking refs，绝不动工作区）。
    #[serde(rename = "git_updated")]
    GitUpdated {
        cwd: String,
        #[serde(default)]
        fetch: bool,
    },
    /// 终端会话状态变更（创建 / 关闭 / 清空），项目级跨设备全局广播
    #[serde(rename = "terminal_updated")]
    TerminalUpdated { cwd: String },
    /// 会话审批模式变更（跨实例全局广播）
    #[serde(rename = "session_mode")]
    SessionMode {
        #[serde(skip_serializing_if = "Option::is_none")]
        session_id: Option<String>,
        mode: String,
    },
    /// 全局模式开关变更（跨实例全局广播）。`enabled` 为 true 时所有会话统一
    /// 跟随 `mode`；为 false 时各会话恢复自己的模式。
    #[serde(rename = "mode_global")]
    ModeGlobal { enabled: bool, mode: String },
}

/// 一次模型参数变更里携带的思考强度/预算快照（两字段都序列化，`null` 即清空）。
#[derive(Clone, Debug, serde::Serialize)]
pub(crate) struct ModelEffortWire {
    pub reasoning_effort: Option<String>,
    pub thinking_budget: Option<u32>,
}

/// 全局 `steer_folded` 里的单条转向：只带跨端匹配所需的轻量字段。
#[derive(Clone, Debug, serde::Serialize)]
pub(crate) struct SteerFoldedInputWire {
    pub text: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub message_id: Option<String>,
    /// 是否带图（图片本体不进全局通道）。
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub has_images: bool,
}

impl SteerFoldedInputWire {
    pub(crate) fn from_kernel(input: &jeikcode_kernel::event::SteeredInput) -> Self {
        Self {
            text: input.text.clone(),
            message_id: input.message_id.clone(),
            has_images: !input.images.is_empty(),
        }
    }
}

/// 增量会话行（与 `/sessions` 返回的 `SessionMetaWithProject` 同形），
/// 客户端按 `id` 就地 upsert。
#[derive(Clone, Debug, serde::Serialize)]
pub(crate) struct SessionRowWire {
    pub id: String,
    pub name: String,
    pub working_dir: String,
    pub project_hash: String,
    pub created_at: u64,
    pub updated_at: u64,
    pub message_count: u32,
    pub origin: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub approval_mode: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub preferred_model: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reasoning_effort: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub thinking_budget: Option<u32>,
}

/// Build the incremental session row for one stored session. `None` when the
/// aggregate is not (yet) durable.
pub(crate) fn session_row_wire(
    working_dir: &std::path::Path,
    session_id: &str,
) -> Option<SessionRowWire> {
    let manager = NativeSessionManager::for_project(working_dir);
    let meta = manager.read_meta(session_id).ok()?;
    let origin = match meta.origin {
        jeikcode_capabilities::session::SessionOrigin::Manual => "manual",
        jeikcode_capabilities::session::SessionOrigin::Scheduled => "scheduled",
        jeikcode_capabilities::session::SessionOrigin::Protocol => "protocol",
    };
    Some(SessionRowWire {
        id: session_id.to_string(),
        name: meta.name.clone(),
        working_dir: meta.working_dir.clone(),
        project_hash: response_project_hash(std::path::Path::new(&meta.working_dir)),
        created_at: u64::try_from(meta.created_at.max(0)).unwrap_or(0),
        updated_at: u64::try_from(meta.updated_at.max(0)).unwrap_or(0),
        message_count: meta.message_count,
        origin: origin.to_string(),
        approval_mode: Some(live_api::live_display_approval_mode_wire(
            session_id,
            meta.approval_mode.as_deref(),
        )),
        preferred_model: meta.preferred_model.clone(),
        reasoning_effort: meta.reasoning_effort.clone(),
        thinking_budget: meta.thinking_budget,
    })
}

/// Same row, addressed by project bucket instead of a working dir (catalog
/// mutation helpers already hold the bucket).
pub(crate) fn session_row_wire_in_bucket(
    project_bucket: &str,
    session_id: &str,
) -> Option<SessionRowWire> {
    let manager =
        NativeSessionManager::with_root(NativeSessionManager::sessions_root().join(project_bucket));
    let meta = manager.read_meta(session_id).ok()?;
    let origin = match meta.origin {
        jeikcode_capabilities::session::SessionOrigin::Manual => "manual",
        jeikcode_capabilities::session::SessionOrigin::Scheduled => "scheduled",
        jeikcode_capabilities::session::SessionOrigin::Protocol => "protocol",
    };
    Some(SessionRowWire {
        id: session_id.to_string(),
        name: meta.name.clone(),
        working_dir: meta.working_dir.clone(),
        project_hash: project_bucket.to_string(),
        created_at: u64::try_from(meta.created_at.max(0)).unwrap_or(0),
        updated_at: u64::try_from(meta.updated_at.max(0)).unwrap_or(0),
        message_count: meta.message_count,
        origin: origin.to_string(),
        approval_mode: Some(live_api::live_display_approval_mode_wire(
            session_id,
            meta.approval_mode.as_deref(),
        )),
        preferred_model: meta.preferred_model.clone(),
        reasoning_effort: meta.reasoning_effort.clone(),
        thinking_budget: meta.thinking_budget,
    })
}

/// 推送一条会话行的增量快照（读 meta 失败即静默跳过：下次事件/冷启动收敛）。
pub(crate) fn publish_session_upsert(working_dir: &std::path::Path, session_id: &str) {
    if let Some(session) = session_row_wire(working_dir, session_id) {
        publish_global(GlobalWireEvent::SessionUpsert { session });
    }
}

const GLOBAL_EVENTS_CAP: usize = 256;

/// Process-wide invalidation bus shared by every connected client instance.
pub(crate) fn global_events() -> &'static tokio::sync::broadcast::Sender<GlobalWireEvent> {
    static BUS: std::sync::OnceLock<tokio::sync::broadcast::Sender<GlobalWireEvent>> =
        std::sync::OnceLock::new();
    BUS.get_or_init(|| {
        let (tx, _) = tokio::sync::broadcast::channel(GLOBAL_EVENTS_CAP);
        tx
    })
}

/// Broadcast a model-config change to every instance. `session_id = None` means the
/// new-session default model changed; `effort = None` means the event only carries a
/// provider switch. `deferred` tells the UI the turn in flight keeps its assembled
/// provider and the values apply from the next turn.
pub(crate) fn publish_model_config(
    session_id: Option<&str>,
    provider: Option<&str>,
    effort: Option<ModelEffortWire>,
    deferred: bool,
) {
    publish_global(GlobalWireEvent::ModelConfig {
        session_id: session_id.map(str::to_string),
        provider: provider.map(str::to_string),
        effort,
        deferred,
    });
}

/// Broadcast an invalidation signal. No subscribers / lagged receivers are fine:
/// the next invalidation (or a client's cold start) reconciles the state.
pub(crate) fn publish_global(event: GlobalWireEvent) {
    let _ = global_events().send(event);
}

/// 压缩 owner 命名空间。
///
/// 压缩阶段必须按 owner 隔离：`/chat` 的自动压缩归当前 turn，native live 归
/// live runtime，手动 `/compact` 归该次 operation。任何一个 owner 的收尾都
/// 不得清除另一个 owner 正在执行的压缩。
pub(crate) const COMPACTION_OWNER_TURN: &str = "turn";
pub(crate) const COMPACTION_OWNER_LIVE: &str = "live";

pub(crate) fn manual_compaction_owner(operation_id: &str) -> String {
    format!("manual:{operation_id}")
}

#[derive(Clone, Debug)]
struct CompactionPhase {
    started_at: u64,
    owner: String,
}

/// 会话级执行阶段。`revision` 在每次阶段变化时单调递增；即使阶段结束也保留
/// 最后一次 revision，客户端据此拒绝迟到的旧事件。
#[derive(Clone, Debug, Default)]
struct ExecutionPhaseState {
    revision: u64,
    phase: Option<CompactionPhase>,
}

fn execution_phases() -> &'static std::sync::Mutex<HashMap<String, ExecutionPhaseState>> {
    static PHASES: std::sync::OnceLock<std::sync::Mutex<HashMap<String, ExecutionPhaseState>>> =
        std::sync::OnceLock::new();
    PHASES.get_or_init(|| std::sync::Mutex::new(HashMap::new()))
}

/// 登记一次压缩开始；同一 owner 的重复开始保留最早的起点。
///
/// 返回该 pass 的权威起点。不同 owner 同时到达时拒绝抢占，保留先到者——
/// 正常情况下 `ActiveChatRegistry` 的准入已经保证同一会话只有一个执行 owner。
pub(crate) fn note_compaction_started(session_id: &str, owner: &str) -> u64 {
    let started_at = u64::try_from(jeikcode_capabilities::session::now_ms()).unwrap_or(0);
    let result = {
        let mut phases = execution_phases()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let state = phases.entry(session_id.to_string()).or_default();
        state.revision = state.revision.saturating_add(1);
        match state.phase.as_ref() {
            Some(existing) => {
                if existing.owner != owner {
                    tracing::warn!(
                        session_id = %session_id,
                        running_owner = %existing.owner,
                        incoming_owner = %owner,
                        "compaction start ignored: another owner already holds the phase"
                    );
                }
                existing.started_at
            }
            None => {
                state.phase = Some(CompactionPhase {
                    started_at,
                    owner: owner.to_string(),
                });
                started_at
            }
        }
    };
    publish_runtime_activity(session_id, true);
    result
}

/// 只结束指定 owner 的压缩阶段；owner 不匹配时保持现状。
pub(crate) fn note_compaction_finished(session_id: &str, owner: &str) -> bool {
    let mut phases = execution_phases()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let Some(state) = phases.get_mut(session_id) else {
        return false;
    };
    if state
        .phase
        .as_ref()
        .map_or(true, |phase| phase.owner != owner)
    {
        return false;
    }
    state.phase = None;
    state.revision = state.revision.saturating_add(1);
    true
}

/// 结束某个 owner 前缀的压缩阶段（用于 turn/live 这类没有精确 run id 的投影器）。
pub(crate) fn note_compaction_finished_for_prefix(session_id: &str, prefix: &str) -> bool {
    let mut phases = execution_phases()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let Some(state) = phases.get_mut(session_id) else {
        return false;
    };
    if !state
        .phase
        .as_ref()
        .is_some_and(|phase| phase.owner.starts_with(prefix))
    {
        return false;
    }
    state.phase = None;
    state.revision = state.revision.saturating_add(1);
    true
}

/// 结束阶段并广播权威运行态。`running_after` 描述该 owner 结束后会话是否仍在执行。
pub(crate) fn finish_compaction_phase(session_id: &str, owner: &str, running_after: bool) -> bool {
    if note_compaction_finished(session_id, owner) {
        publish_runtime_activity(session_id, running_after);
        true
    } else {
        false
    }
}

pub(crate) fn finish_compaction_phase_prefix(
    session_id: &str,
    prefix: &str,
    running_after: bool,
) -> bool {
    if note_compaction_finished_for_prefix(session_id, prefix) {
        publish_runtime_activity(session_id, running_after);
        true
    } else {
        false
    }
}

pub(crate) fn compaction_started_at(session_id: &str) -> Option<u64> {
    execution_phases()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .get(session_id)
        .and_then(|state| state.phase.as_ref().map(|phase| phase.started_at))
}

pub(crate) fn compaction_owner(session_id: &str) -> Option<String> {
    execution_phases()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .get(session_id)
        .and_then(|state| state.phase.as_ref().map(|phase| phase.owner.clone()))
}

pub(crate) fn execution_phase_revision(session_id: &str) -> u64 {
    execution_phases()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .get(session_id)
        .map(|state| state.revision)
        .unwrap_or(0)
}

pub(crate) fn compaction_running_session_ids() -> Vec<String> {
    execution_phases()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .iter()
        .filter(|(_, state)| state.phase.is_some())
        .map(|(session_id, _)| session_id.clone())
        .collect()
}

/// 广播一条带 revision/owner 的权威运行态。
///
/// `RuntimeActivity` 是新客户端的唯一阶段信号；`Activity` 继续保留给旧客户端
/// 与侧栏的活动列表，两者由同一个状态快照派生，不能再由各处自行拼装。
pub(crate) fn publish_runtime_activity(session_id: &str, running: bool) {
    let (started_at, owner, revision) = {
        let phases = execution_phases()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        match phases.get(session_id) {
            Some(state) => (
                state.phase.as_ref().map(|phase| phase.started_at),
                state.phase.as_ref().map(|phase| phase.owner.clone()),
                state.revision,
            ),
            None => (None, None, 0),
        }
    };
    let compacting = started_at.is_some();
    publish_global(GlobalWireEvent::RuntimeActivity {
        session_id: session_id.to_string(),
        revision,
        running,
        phase: compacting.then(|| "compacting".to_string()),
        phase_started_at: started_at,
        owner: owner.clone(),
    });
    // 旧客户端只理解 Activity；状态字段必须与新快照保持一致。
    publish_global(GlobalWireEvent::Activity {
        session_id: session_id.to_string(),
        running,
        terminal: None,
        status: Some(if compacting { "compacting" } else { "running" }.to_string()),
    });
}

#[cfg(test)]
mod folded_steer_outline_tests {
    use super::*;

    #[test]
    fn folded_steer_is_projected_into_the_outline_without_a_display_row() {
        let inputs = vec![jeikcode_capabilities::session::SessionInput {
            id: "steer-1".into(),
            seq: 7,
            session_id: "session-1".into(),
            delivery: "steer".into(),
            status: "promoted".into(),
            text: "<user-query>\n看这个\n</user-query>".into(),
            images: Vec::new(),
            created_at: 1_700_000_000_000,
            message_id: Some("m-steer-1".into()),
            operation_id: Some("op-1".into()),
        }];
        let mut turns = Vec::new();
        append_folded_steer_outline(
            &[],
            &mut turns,
            &inputs,
            Some("op-1"),
            std::path::Path::new("/project"),
            0,
        );
        assert_eq!(turns.len(), 1);
        assert_eq!(turns[0].id.as_deref(), Some("steer-1"));
        assert_eq!(turns[0].label, "看这个");
        assert!(turns[0].pending);

        // The same durable steer must not be added twice on every read.
        append_folded_steer_outline(
            &[],
            &mut turns,
            &inputs,
            Some("op-1"),
            std::path::Path::new("/project"),
            0,
        );
        assert_eq!(turns.len(), 1);
    }

    #[test]
    fn queued_and_live_steers_are_projected_without_an_operation_alias() {
        let inputs = vec![
            jeikcode_capabilities::session::SessionInput {
                id: "steer-queued".into(),
                seq: 8,
                session_id: "session-1".into(),
                delivery: "steer".into(),
                status: "admitted".into(),
                text: "<user-query>\n排队中\n</user-query>".into(),
                images: Vec::new(),
                created_at: 1_700_000_000_100,
                message_id: None,
                operation_id: Some("op-1".into()),
            },
            jeikcode_capabilities::session::SessionInput {
                id: "steer-live".into(),
                seq: 9,
                session_id: "session-1".into(),
                delivery: "steer".into(),
                status: "admitted".into(),
                text: "<user-query>\nlive 转向\n</user-query>".into(),
                images: Vec::new(),
                created_at: 1_700_000_000_200,
                message_id: None,
                operation_id: None,
            },
        ];
        let mut turns = Vec::new();
        append_folded_steer_outline(
            &[],
            &mut turns,
            &inputs,
            None,
            std::path::Path::new("/project"),
            0,
        );
        assert_eq!(turns.len(), 2);
        assert!(turns.iter().all(|turn| turn.pending));
        assert_eq!(turns[0].label, "排队中");
        assert_eq!(turns[1].label, "live 转向");
    }
}

#[cfg(test)]
mod compaction_phase_tests {
    use super::*;

    #[test]
    fn compaction_phase_keeps_earliest_start_and_only_owner_can_finish() {
        let session_id = "compaction-phase-test-session";
        note_compaction_finished(session_id, "turn");
        let first = note_compaction_started(session_id, "turn");
        // 同一个 pass 的重复 CompactionStarted 不得把计时起点往后拽。
        assert_eq!(note_compaction_started(session_id, "turn"), first);
        assert_eq!(compaction_started_at(session_id), Some(first));

        // 另一个 owner 不得清除当前阶段。
        assert!(!note_compaction_finished(session_id, "live"));
        assert_eq!(compaction_started_at(session_id), Some(first));
        assert_eq!(compaction_owner(session_id).as_deref(), Some("turn"));

        let revision_while_compacting = execution_phase_revision(session_id);
        assert!(revision_while_compacting > 0);

        assert!(note_compaction_finished(session_id, "turn"));
        assert_eq!(compaction_started_at(session_id), None);
        // revision 在阶段结束后继续单调保留，客户端可拒绝迟到的旧事件。
        assert!(execution_phase_revision(session_id) > revision_while_compacting);
    }
}

/// 运行时控制器（`/loop` / `/goal`）的服务端权威状态。
///
/// `/loop` 在两次唤醒之间会进入 wakeup 等待：那一刻没有回合在执行，
/// `ActiveChatRegistry` 与会话运行态注册表都如实报告「空闲」，但控制器还挂着，
/// 下一轮随时开始。客户端若只据此熄灭 busy，就会出现「循环仍在输出、按钮/呼吸点
/// 却是停止态，刷新才恢复」。这里把 `LoopChanged` / `GoalChanged` 收成一份进程级
/// 状态，让 `/chat/active` 与 `/chat/runtime` 能如实回答「这个会话还有没有人在干活」。
///
/// 每轮至少刷新一次 `updated_at`；超过 [`CONTROLLER_STALE_AFTER`] 未刷新即视为
/// 控制器已消失，避免 runtime 崩溃/重启后永久占住运行态。
#[derive(Clone, Debug, Default)]
struct ControllerState {
    loop_active: bool,
    goal_active: bool,
    loop_round: u32,
    loop_label: String,
    updated_at: Option<std::time::Instant>,
}

/// 控制器状态的保鲜窗口。`schedule_wakeup` 允许最长 3600s 的唤醒延迟，期间不会
/// 再发 `LoopChanged`，所以窗口必须覆盖一整轮睡眠再留余量；超过即视为控制器
/// 已消失（runtime 崩溃/重启不会永久占住运行态）。
const CONTROLLER_STALE_AFTER: std::time::Duration = std::time::Duration::from_secs(7200);

fn controller_states(
) -> &'static std::sync::Mutex<std::collections::HashMap<String, ControllerState>> {
    static STATES: std::sync::OnceLock<
        std::sync::Mutex<std::collections::HashMap<String, ControllerState>>,
    > = std::sync::OnceLock::new();
    STATES.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

fn fresh_controller_state(state: &ControllerState) -> bool {
    state
        .updated_at
        .is_some_and(|at| at.elapsed() < CONTROLLER_STALE_AFTER)
}

/// Record the `/loop` controller state for a session (called from the runtime
/// event projector; the daemon used to drop these events on the floor).
fn note_loop_state(session_id: &str, active: bool, round: u32, label: &str) {
    let session_id = session_id.trim();
    if session_id.is_empty() {
        return;
    }
    let mut guard = controller_states()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    // 写路径顺便清掉过期条目：长期运行的 daemon 不会因为历史会话无限增长。
    guard.retain(|_, state| fresh_controller_state(state));
    let state = guard.entry(session_id.to_string()).or_default();
    state.loop_active = active;
    state.loop_round = round;
    state.loop_label = label.to_string();
    state.updated_at = Some(std::time::Instant::now());
}

/// Record the `/goal` controller state for a session.
fn note_goal_state(session_id: &str, active: bool) {
    let session_id = session_id.trim();
    if session_id.is_empty() {
        return;
    }
    let mut guard = controller_states()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    guard.retain(|_, state| fresh_controller_state(state));
    let state = guard.entry(session_id.to_string()).or_default();
    state.goal_active = active;
    state.updated_at = Some(std::time::Instant::now());
}

fn controller_state_for(session_id: &str) -> Option<ControllerState> {
    let guard = controller_states()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    guard
        .get(session_id)
        .filter(|state| fresh_controller_state(state))
        .cloned()
}

/// 这个会话是否仍有已武装的运行时控制器（`/loop` 或 `/goal`）。
fn session_controller_running(session_id: &str) -> bool {
    controller_state_for(session_id).is_some_and(|state| state.loop_active || state.goal_active)
}

/// Sessions whose runtime still owns an armed controller. These must count as
/// "running" for `/chat/active` even while no turn is executing.
fn controller_running_session_ids() -> Vec<String> {
    let guard = controller_states()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    guard
        .iter()
        .filter(|(_, state)| {
            fresh_controller_state(state) && (state.loop_active || state.goal_active)
        })
        .map(|(session_id, _)| session_id.clone())
        .collect()
}

/// 「git 变更命令自动同步」开关：默认开启；读配置失败时按开启兜底。
/// 仅在确实命中 git 写命令的关键节点调用，开销可忽略（不做任何轮询）。
fn auto_git_sync_enabled() -> bool {
    jeikcode_config::store::ConfigStore::default_store()
        .read()
        .map(|snapshot| snapshot.config.auto_git_sync)
        .unwrap_or(true)
}

/// `/events` 的挂载点。单独抽成 helper，生产路由与测试共用同一份定义：
/// 路由一旦被从生产路由上拿掉，`global_events_route_tests` 会立即失败。
pub(crate) fn with_global_events_route<S>(router: Router<S>) -> Router<S>
where
    S: Clone + Send + Sync + 'static,
{
    router.route("/events", get(global_events_stream))
}

/// GET /events — cross-instance invalidation stream (SSE).
///
/// The first frame is `{"type":"sync"}` so a connecting client performs one
/// cold-start alignment; afterwards only real changes are pushed.
async fn global_events_stream() -> axum::response::Response {
    use axum::response::sse::{Event, KeepAlive, Sse};
    use futures::StreamExt as _;
    use std::convert::Infallible;

    let mut rx = global_events().subscribe();
    let (tx, out_rx) = mpsc::unbounded_channel::<String>();
    let _ = tx.send(serde_json::json!({ "type": "sync" }).to_string());
    tokio::spawn(async move {
        loop {
            match rx.recv().await {
                Ok(event) => match serde_json::to_string(&event) {
                    Ok(json) => {
                        if tx.send(json).is_err() {
                            break;
                        }
                    }
                    Err(_) => continue,
                },
                Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => continue,
                Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
            }
        }
    });

    let stream = tokio_stream::wrappers::UnboundedReceiverStream::new(out_rx)
        .map(|json| Ok::<Event, Infallible>(Event::default().data(json)));
    let mut resp = Sse::new(stream)
        .keep_alive(KeepAlive::new().interval(std::time::Duration::from_secs(15)))
        .into_response();
    resp.headers_mut().insert(
        axum::http::header::CACHE_CONTROL,
        axum::http::HeaderValue::from_static("no-cache, no-transform"),
    );
    resp
}

/// Append `event` to the turn replay log, coalescing consecutive text/reasoning
/// deltas so a long stream does not allocate one Vec entry per token.
///
/// Coalescing is IDENTITY-SCOPED: two deltas may merge only when they carry the
/// same `message_id`/`part_id`. Merging across identities used to fuse a later
/// round's tail into an earlier round's entry, so a watch/live replay repainted
/// that text under the WRONG stored message (ghost rounds + misplaced text).
/// The turn's replay buffer AND the single monotonic event cursor. Every
/// emitted event (live or replayed) consumes one seq; coalesced text/reasoning
/// deltas keep the LAST seq, so a replay snapshot is always a prefix of the
/// same ordered log.
struct ReplayLog {
    next_seq: u64,
    events: Vec<(u64, ChatEvent)>,
}

impl ReplayLog {
    fn new(seq_base: u64) -> Self {
        Self {
            next_seq: seq_base,
            events: Vec::new(),
        }
    }

    fn high_water(&self) -> u64 {
        self.next_seq
    }

    fn push(&mut self, event: ChatEvent) -> u64 {
        self.next_seq = self.next_seq.saturating_add(1);
        let seq = self.next_seq;
        let coalesced = match (&event, self.events.last_mut()) {
            (
                ChatEvent::TextDelta {
                    content,
                    message_id,
                    part_id,
                    part_rev,
                    ..
                },
                Some((
                    prev_seq,
                    ChatEvent::TextDelta {
                        content: prev,
                        message_id: prev_message_id,
                        part_id: prev_part_id,
                        part_rev: prev_part_rev,
                        ..
                    },
                )),
            ) if message_id == prev_message_id && part_id == prev_part_id => {
                prev.push_str(content);
                if part_rev.is_some() {
                    *prev_part_rev = *part_rev;
                }
                *prev_seq = seq;
                true
            }
            (
                ChatEvent::ReasoningDelta {
                    content,
                    message_id,
                    part_id,
                    part_rev,
                    ..
                },
                Some((
                    prev_seq,
                    ChatEvent::ReasoningDelta {
                        content: prev,
                        message_id: prev_message_id,
                        part_id: prev_part_id,
                        part_rev: prev_part_rev,
                        ..
                    },
                )),
            ) if message_id == prev_message_id && part_id == prev_part_id => {
                prev.push_str(content);
                if part_rev.is_some() {
                    *prev_part_rev = *part_rev;
                }
                *prev_seq = seq;
                true
            }
            (
                ChatEvent::ToolOutputChunk { id, chunk },
                Some((
                    prev_seq,
                    ChatEvent::ToolOutputChunk {
                        id: prev_id,
                        chunk: prev,
                    },
                )),
            ) if id == prev_id => {
                prev.push_str(chunk);
                *prev_seq = seq;
                true
            }
            _ => false,
        };
        if !coalesced {
            self.events.push((seq, event));
        }
        seq
    }
}

fn push_chat_replay(log: &mut ReplayLog, event: ChatEvent) -> u64 {
    log.push(event)
}

fn push_chat_replay_legacy(buf: &mut Vec<ChatEvent>, event: ChatEvent) {
    match (&event, buf.last_mut()) {
        (
            ChatEvent::TextDelta {
                content,
                message_id,
                part_id,
                part_rev,
                ..
            },
            Some(ChatEvent::TextDelta {
                content: prev,
                message_id: prev_message_id,
                part_id: prev_part_id,
                part_rev: prev_part_rev,
                ..
            }),
        ) if message_id == prev_message_id && part_id == prev_part_id => {
            prev.push_str(content);
            if part_rev.is_some() {
                *prev_part_rev = *part_rev;
            }
        }
        (
            ChatEvent::ReasoningDelta {
                content,
                message_id,
                part_id,
                part_rev,
                ..
            },
            Some(ChatEvent::ReasoningDelta {
                content: prev,
                message_id: prev_message_id,
                part_id: prev_part_id,
                part_rev: prev_part_rev,
                ..
            }),
        ) if message_id == prev_message_id && part_id == prev_part_id => {
            prev.push_str(content);
            if part_rev.is_some() {
                *prev_part_rev = *part_rev;
            }
        }
        (
            ChatEvent::ToolOutputChunk { id, chunk },
            Some(ChatEvent::ToolOutputChunk {
                id: prev_id,
                chunk: prev,
            }),
        ) if id == prev_id => {
            prev.push_str(chunk);
        }
        _ => buf.push(event),
    }
}

/// Bridge a producer channel so every `ChatEvent` reaches both the primary SSE
/// client **and** any `/chat/watch` subscribers on the turn's broadcast bus.
///
/// When `replay` is set, each event is also recorded (coalesced) so late watchers
/// can rehydrate the full turn after a browser refresh.
pub(crate) fn fanout_chat_events(
    primary: mpsc::UnboundedSender<ChatEvent>,
    bus: tokio::sync::broadcast::Sender<(u64, ChatEvent)>,
    replay: Option<Arc<std::sync::Mutex<ReplayLog>>>,
) -> mpsc::UnboundedSender<ChatEvent> {
    fanout_chat_events_for_session(primary, bus, replay, None, None)
}

/// Like [`fanout_chat_events`], but also mirrors stream events into the L2
/// `SessionRuntimeRegistry` so `/live?session_id=` viewers see `/chat` / OpenAI
/// compat turns on the same session.
pub(crate) fn fanout_chat_events_for_session(
    primary: mpsc::UnboundedSender<ChatEvent>,
    bus: tokio::sync::broadcast::Sender<(u64, ChatEvent)>,
    replay: Option<Arc<std::sync::Mutex<ReplayLog>>>,
    session_id: Option<String>,
    working_dir: Option<std::path::PathBuf>,
) -> mpsc::UnboundedSender<ChatEvent> {
    let (tx, mut rx) = mpsc::unbounded_channel::<ChatEvent>();
    tokio::spawn(async move {
        let mut current_sid = session_id;
        let mut no_replay_seq: u64 = 0;
        let current_wd = working_dir;
        // Git 变更命令登记表：call_id → 意图（见 git_intent）。仅在 shell 工具里命中
        // 「改动分支/引用/远端」的 git 命令时登记，待其 ToolResult 落地才触发一次广播。
        // 这是关键节点启发触发，不引入任何轮询。
        let mut pending_git: HashMap<String, crate::git_intent::GitIntent> = HashMap::new();
        while let Some(event) = rx.recv().await {
            let mut deferred_activity: Option<GlobalWireEvent> = None;
            let mut deferred_upsert_sid: Option<String> = None;
            match &event {
                ChatEvent::ToolCallStarted {
                    id,
                    name,
                    arguments,
                    ..
                } => {
                    tracing::info!(
                        tool = %name,
                        args = %log_truncate(arguments, 300),
                        "chat: tool call started"
                    );
                    // 关键节点启发：仅解析 shell 工具的命令，命中 git 写操作才登记，
                    // 等 ToolResult 落地后再广播（绝不新增轮询）。
                    if jeikcode_capabilities::tools::is_shell_tool_name(name) {
                        if let Some(intent) =
                            jeikcode_capabilities::tools::extract_shell_command(arguments)
                                .and_then(|cmd| crate::git_intent::classify(&cmd))
                        {
                            pending_git.insert(id.clone(), intent);
                        }
                    }
                }
                ChatEvent::PermissionRequest {
                    session_id,
                    tool_name,
                    call_id,
                    ..
                } => {
                    tracing::warn!(
                        tool = %tool_name,
                        call_id = %call_id,
                        "chat: PERMISSION REQUEST emitted (approval round-trip)"
                    );
                    publish_global(GlobalWireEvent::ReviewAsked {
                        session_id: session_id.clone(),
                    });
                }
                ChatEvent::UserInputRequest { session_id, .. } => {
                    tracing::warn!(
                        "chat: user_input_request emitted (model asked a structured question)"
                    );
                    publish_global(GlobalWireEvent::ReviewAsked {
                        session_id: session_id.clone(),
                    });
                }
                ChatEvent::User {
                    session_id,
                    client_input_id,
                    message_id,
                    ..
                } => {
                    let sid = session_id.clone().or_else(|| current_sid.clone());
                    if let Some(sid) = sid {
                        // The admitted prompt is now a real message: retire its
                        // pending input row by the same id.
                        let _ = jeikcode_capabilities::session::inputs::mark_promoted_global(
                            &sid,
                            &[(client_input_id.clone(), message_id.clone())],
                        );
                        publish_global(GlobalWireEvent::Activity {
                            session_id: sid,
                            running: true,
                            terminal: None,
                            status: None,
                        });
                    }
                }
                ChatEvent::Steered {
                    inputs,
                    client_input_ids,
                    ..
                } => {
                    // 中途转向已并入本轮：异地客户端即使没在看这个会话，也要把这条
                    // 提问写进它自己的本地画布缓存（切过去 / 冷启动时气泡已在）。
                    if let Some(sid) = current_sid.clone() {
                        // The kernel folded these steers into persisted user
                        // messages: retire their pending input rows by client id
                        // and bind the kernel message id for later reconciliation.
                        let pairs: Vec<(Option<String>, Option<String>)> = client_input_ids
                            .iter()
                            .cloned()
                            .zip(inputs.iter().map(|input| input.message_id.clone()))
                            .collect();
                        let _ = jeikcode_capabilities::session::inputs::mark_promoted_global(
                            &sid, &pairs,
                        );
                        retire_folded_steers_from_queue(&sid, &pairs).await;
                        publish_global(GlobalWireEvent::SteerFolded {
                            session_id: sid,
                            inputs: inputs
                                .iter()
                                .map(SteerFoldedInputWire::from_kernel)
                                .collect(),
                            client_input_ids: client_input_ids.clone(),
                        });
                    }
                }
                ChatEvent::Done {
                    session_id,
                    stop_reason,
                    ..
                } => {
                    tracing::info!(
                        session_id = %session_id,
                        stop_reason = ?stop_reason,
                        "chat: turn done"
                    );
                    if current_sid.is_none() {
                        current_sid = Some(session_id.clone());
                    }
                    deferred_activity = Some(GlobalWireEvent::Activity {
                        session_id: session_id.clone(),
                        running: false,
                        terminal: Some(chat_done_terminal_label(stop_reason.as_deref())),
                        status: None,
                    });
                    deferred_upsert_sid = Some(session_id.clone());
                }
                ChatEvent::Stopped | ChatEvent::Error { .. } => {
                    if matches!(event, ChatEvent::Stopped) {
                        tracing::info!("chat: turn stopped");
                    }
                    if let Some(sid) = current_sid.clone() {
                        deferred_activity = Some(GlobalWireEvent::Activity {
                            session_id: sid,
                            running: false,
                            terminal: Some("stopped"),
                            status: None,
                        });
                    }
                }
                ChatEvent::ToolCallResult {
                    id, name, success, ..
                } => {
                    tracing::info!(tool = %name, success, "chat: tool result");
                    // shell 的 git 变更命令已执行完毕（关键节点）：向本项目全部会话广播一次
                    // Git 刷新；远端/引用类命令让客户端再按节流补一次 `git fetch`。
                    if let Some(intent) = pending_git.remove(id) {
                        if auto_git_sync_enabled() {
                            if let Some(dir) = current_wd.as_deref() {
                                api_git::invalidate_git_cache(dir);
                                publish_global(GlobalWireEvent::GitUpdated {
                                    cwd: dir.to_string_lossy().to_string(),
                                    fetch: intent.needs_fetch(),
                                });
                            }
                        }
                    }
                }
                ChatEvent::SessionAssigned { session_id }
                | ChatEvent::SessionRenamed { session_id, .. } => {
                    if current_sid.is_none() {
                        current_sid = Some(session_id.clone());
                    }
                    deferred_upsert_sid = Some(session_id.clone());
                }
                _ => {}
            }
            let effective_sid = match &event {
                ChatEvent::SessionAssigned { session_id } => Some(session_id.as_str()),
                ChatEvent::Done { session_id, .. } => Some(session_id.as_str()),
                ChatEvent::SessionRenamed { session_id, .. } => Some(session_id.as_str()),
                _ => current_sid.as_deref(),
            };
            if let Some(sid) = effective_sid {
                mirror_chat_event_to_registry(sid, &event);
            }
            let seq = if let Some(ref replay) = replay {
                let mut guard = replay
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                push_chat_replay(&mut guard, event.clone())
            } else {
                no_replay_seq = no_replay_seq.saturating_add(1);
                no_replay_seq
            };
            let _ = bus.send((seq, event.clone()));
            let _ = primary.send(event);
            // 终态必须先写入 replay 并投递到 /chat/watch 总线，随后才能在全局 /events 上广播
            // running: false 与执行磁盘扫描，避免前端收到 Activity 信号时 /chat/watch 尚未收到 Done。
            if let Some(activity) = deferred_activity {
                publish_global(activity);
            }
            if let (Some(wd), Some(sid)) = (current_wd.as_deref(), deferred_upsert_sid.as_deref()) {
                publish_session_upsert(wd, sid);
            }
        }
    });
    tx
}

fn mirror_chat_event_to_registry(session_id: &str, event: &ChatEvent) {
    use jeikcode_coding::session_runtime_registry::{SessionRuntimeRegistry, SessionViewEvent};
    use jeikcode_kernel::event::AgentEvent;
    let reg = SessionRuntimeRegistry::global();
    let working_dir = reg
        .lookup(&session_id.to_string())
        .map(|e| e.working_dir)
        .unwrap_or_else(|| PathBuf::from("."));
    let _ = reg.open_or_attach(session_id.to_string(), working_dir);
    match event {
        ChatEvent::TextDelta { content, .. } => {
            let _ = reg.push_runtime_event(
                &session_id.to_string(),
                0,
                CodingRuntimeEvent::Agent(AgentEvent::TextDelta(content.clone())),
            );
        }
        ChatEvent::ReasoningDelta { content, .. } => {
            let _ = reg.push_runtime_event(
                &session_id.to_string(),
                0,
                CodingRuntimeEvent::Agent(AgentEvent::Reasoning(content.clone())),
            );
        }
        ChatEvent::User { content, .. } => {
            let _ = reg.push_view_event(
                &session_id.to_string(),
                SessionViewEvent::InputAccepted {
                    input: jeikcode_coding::UserInput::from(content.as_str()),
                    client_input_id: None,
                },
            );
        }
        ChatEvent::PermissionRequest { .. } => {
            let _ = reg.set_activity(
                &session_id.to_string(),
                jeikcode_coding::session_runtime_registry::RuntimeActivity::WaitingApproval,
            );
        }
        ChatEvent::UserInputRequest { .. } => {
            let _ = reg.set_activity(
                &session_id.to_string(),
                jeikcode_coding::session_runtime_registry::RuntimeActivity::WaitingUserInput,
            );
        }
        ChatEvent::Done { stop_reason, .. } => {
            let _ = reg.note_terminal(
                &session_id.to_string(),
                chat_done_terminal_label(stop_reason.as_deref()),
            );
        }
        ChatEvent::Stopped => {
            let _ = reg.note_terminal(&session_id.to_string(), "stopped");
        }
        ChatEvent::Error { .. } => {
            let _ = reg.note_terminal(&session_id.to_string(), "failed");
        }
        _ => {}
    }
}
impl Drop for SseConnectionGuard {
    fn drop(&mut self) {
        self.0.fetch_sub(1, std::sync::atomic::Ordering::Relaxed);
    }
}

/// Combined app state for Axum
#[derive(Clone)]
pub struct AppState {
    pub project: ProjectStateStore,
    /// Admitted background chat operations and their session/request aliases.
    active_chats: ActiveChatRegistry,
    /// MCP server registry (global, used for /mcp/status backward compat)
    pub mcp_registry: Arc<RwLock<Arc<McpRegistry>>>,
    /// Per-project MCP connection pool (shared across chat runtimes in this process).
    pub mcp_pool: Arc<jeikcode_capabilities::mcp::ProjectMcpPool>,
    /// Process-unique generation for invalidating daemon-owned operation IDs.
    pub(crate) daemon_instance_id: Arc<str>,
    /// Shared telemetry handle (R1.4)
    pub telemetry: Arc<Telemetry>,
    /// Repo origin detected at daemon launch (R4.2)
    pub repo_origin: RepoOrigin,
    /// Sender to trigger graceful shutdown via POST /shutdown (R7.1, R7.2)
    pub shutdown_tx: watch::Sender<bool>,
    /// Timestamp (unix ms) of last non-health HTTP request — used for idle timeout
    pub last_activity: Arc<std::sync::atomic::AtomicI64>,
    /// Number of active SSE streaming connections (chat in progress)
    pub active_connections: Arc<std::sync::atomic::AtomicUsize>,
    /// 本地 webui 一次性 token 存储（Phase 1）
    pub webui_tokens: auth_token::WebuiTokenStore,
    /// 仅 webui 模式（启动时提供了 token store）强制 token 鉴权；
    /// 独立 daemon / VSCode 实例不强制，保持原行为。
    /// 临时远程访问启用带 token 的监听时可动态开启。
    pub enforce_token: Arc<std::sync::atomic::AtomicBool>,
    pub initial_enforce_token: bool,
    /// App 远程访问模式的期望 user_id（来自二维码 token 前缀）。
    /// 非空时强制校验每条请求的 `X-JeikCode-User-Id` 头，与桌面端登录账号一致才放行。
    /// 空串表示不校验（未登录 / 非 app 模式）。
    pub app_user_id: String,
    /// webui 交互式权限：session_id -> decider response 发送端
    pub pending_permissions: permission_bridge::PermissionResponders,
    /// `/chat` structured user-input answers, keyed by (session_id, native request_id).
    pub pending_user_inputs: permission_bridge::UserInputResponders,
    /// server 绑定的地址 / 端口（供 /tunnel/status 报告远程可达性）。
    pub bind_host: String,
    pub bind_port: u16,
    /// Workspace the OpenAI / Responses / Anthropic protocol surface is pinned
    /// to: the directory this process was started in (`jeikcode serve --host
    /// --port` cwd, or `working_dir_override`). WebUI multi-project switches
    /// update `project` for the session panel; they must not move protocol
    /// conversations into the first sidebar project.
    pub bind_working_dir: PathBuf,
    /// This instance's port-scoped webui cookie name (`jeikcode_webui_<port>`),
    /// resolved ONCE at construction from the actual bound port. Read it directly
    /// — never re-derive the name from the bare `WEBUI_COOKIE` const at a call
    /// site, or that site silently fails to authenticate (a sibling `/webui` on a
    /// different localhost port would shadow the shared-jar cookie). See
    /// [`auth_token::webui_cookie_name`].
    pub webui_cookie_name: String,
    /// Serve `--yolo`: auto-approve tools and unmount `request_user_input`.
    /// When true, no permission / user-input modal can stall an API or WebUI turn.
    pub yolo: bool,
    /// Temporary remote access turned token checks off for this process.
    pub token_optional: Arc<std::sync::atomic::AtomicBool>,
    /// Router cloned into an extra listener opened from the WebUI.
    pub http_router: Arc<std::sync::OnceLock<axum::Router>>,
    /// The extra listener, if the WebUI opened one.
    pub extra_remote: Arc<std::sync::Mutex<Option<ExtraRemoteBind>>>,
}

/// A second bind opened from the WebUI remote-access control.
pub struct ExtraRemoteBind {
    pub host: String,
    pub port: u16,
    pub aborts: Vec<tokio::task::AbortHandle>,
    pub token: Option<String>,
}

impl ExtraRemoteBind {
    pub fn abort_all(&self) {
        for handle in &self.aborts {
            handle.abort();
        }
    }
}

impl AppState {
    #[inline]
    pub fn is_token_enforced(&self) -> bool {
        self.enforce_token
            .load(std::sync::atomic::Ordering::Relaxed)
    }

    /// 检查指定会话当前是否处于活动运行中（如第一轮审查正在执行中）
    pub async fn is_session_active(&self, session_id: &str) -> bool {
        self.active_chats
            .active_session_ids()
            .await
            .iter()
            .any(|id| id == session_id)
    }

    /// 将新消息安全存入目标会话的代发卡片队列，并自动触发总线向前后端广播 QueueUpdated 事件
    pub async fn push_to_session_queue(&self, session_id: &str, text: &str) {
        let sid = session_id.trim().to_string();
        if sid.is_empty() {
            return;
        }
        let map = get_session_queues_map().await;
        let mut writer = map.write().await;
        let list = writer.entry(sid.clone()).or_default();
        let client_input_id = uuid::Uuid::new_v4().to_string();
        list.push(QueuedMessageItem {
            id: serde_json::Value::String(client_input_id.clone()),
            client_input_id: Some(client_input_id),
            text: text.to_string(),
            images: None,
            kind: "queue".to_string(),
            approval_mode: None,
            created_at: None,
            force_send: None,
        });
        let cloned_list = list.clone();
        if let Some(path) = session_queue_file_path(&sid) {
            if let Ok(json_str) = serde_json::to_string_pretty(&cloned_list) {
                let _ = tokio::fs::write(path, json_str).await;
            }
        }
        let value_items: Vec<serde_json::Value> = cloned_list
            .iter()
            .map(|item| serde_json::to_value(item).unwrap_or_default())
            .collect();
        self.active_chats
            .broadcast_to_session(
                &sid,
                ChatEvent::QueueUpdated {
                    session_id: sid.clone(),
                    items: value_items,
                },
            )
            .await;
        // 会话总线只覆盖“正Watch着这个会话”的客户端。正在看其它会话的实例
        // 也必须知道卡片变了，否则切过去时看到的是过期队列。
        publish_global(GlobalWireEvent::QueueUpdated { session_id: sid });
    }
}

/// Cached MCP registry for a specific project directory.
pub use jeikcode_capabilities::mcp::CachedMcpRegistry;

/// Maximum number of per-project MCP registries to cache.
pub use jeikcode_capabilities::mcp::MCP_CACHE_MAX;

/// Get default working directory
fn default_working_dir() -> PathBuf {
    std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

/// Initialize project state from config or default
/// Decide the initial working directory.
///
/// Precedence: an explicit launch-time override (if it exists) wins over the
/// configured `default_workdir` (if it exists), which wins over the process
/// cwd. The override exists so the in-process `jeikcode webui` launcher can
/// pin the daemon to the directory the user actually ran the command from,
/// rather than inheriting a stale `default_workdir` (e.g. a leftover `/tmp`).
fn resolve_initial_working_dir(
    override_dir: Option<PathBuf>,
    config_default: Option<PathBuf>,
    cwd: PathBuf,
) -> PathBuf {
    if let Some(o) = override_dir {
        if o.exists() {
            return o;
        }
    }
    if let Some(d) = config_default {
        if d.exists() {
            return d;
        }
    }
    cwd
}

/// Fold the working directory to its true on-disk case so the webui footer and
/// newly-created sessions don't drift (e.g. a launcher passing `C:\users\danan`
/// for a dir the history recorded as `C:\Users\danan`).
///
/// Windows-only, and guarded: it adopts the canonical form ONLY when that form
/// maps to the SAME session bucket as the input. On Windows `hash_path` already
/// lowercases, so a pure case-fold never changes the bucket — but a junction /
/// symlink whose resolution WOULD change the bucket (and thus hide existing
/// sessions) is left untouched. Other platforms keep the path verbatim to avoid
/// symlink-resolution surprises and bucket orphaning (`hash_path` does not fold
/// case off Windows).
#[cfg(windows)]
pub(crate) fn normalize_working_dir_case(p: PathBuf) -> PathBuf {
    match std::fs::canonicalize(&p) {
        Ok(c) => {
            let c = jeikcode_capabilities::pathnorm::strip_verbatim_path(&c);
            if hash_path(&c) == hash_path(&p) {
                c
            } else {
                p
            }
        }
        Err(_) => p,
    }
}

#[cfg(not(windows))]
pub(crate) fn normalize_working_dir_case(p: PathBuf) -> PathBuf {
    p
}

fn init_project_state(override_dir: Option<PathBuf>) -> ProjectState {
    let config_default = Config::load(&Config::default_path())
        .ok()
        .and_then(|c| c.default_workdir.map(PathBuf::from));
    // A TUI sharing its runtime via `/webui` / `/sync` registered its embedded binding in
    // THIS (in-process) daemon BEFORE the server started. Its working dir is the user's
    // ACTUAL directory, unlike the caller's `current_dir()` override (just where the
    // process launched). Prefer it so the webui footer + session list seed from the TUI's
    // project instead of the process cwd. `/cd` keeps `state.project` current afterward via
    // `live_set_working_dir`, so the read path (GET /project) stays authoritative.
    let embedded_dir = crate::native_live::embedded_binding().map(|binding| binding.working_dir);
    let path = normalize_working_dir_case(resolve_initial_working_dir(
        embedded_dir.or(override_dir),
        config_default,
        default_working_dir(),
    ));
    let name = path
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| "project".to_string());
    ProjectState {
        working_dir: path,
        previous_dir: None,
        recent_dirs: vec![],
        name,
    }
}
/// Artifact info for API response
#[derive(Debug, Serialize, Clone)]
pub struct ArtifactInfo {
    pub id: String,
    pub artifact_type: String, // "html", "svg", "mermaid", "code"
    pub title: Option<String>,
    pub language: Option<String>,
    pub content: String,
}

/// Tool call info for API response
#[derive(Debug, Clone, Serialize)]
pub struct ToolCallInfo {
    pub id: String,
    pub name: String,
    pub arguments: String,
    pub display: String,
}

/// Tool result info for API response
#[derive(Debug, Clone, Serialize)]
pub struct ToolResultInfo {
    pub call_id: String,
    pub success: bool,
    pub summary: String,
    pub line_count: usize,
}

/// Message info for API response
#[derive(Debug, Clone, Serialize, Default)]
pub struct MessageInfo {
    pub role: String,
    /// Stable per-message identity from the kernel `Message.id` (SIDECAR). Lets
    /// WebUI cache/disk/wire agree on the same handle. Absent for messages
    /// persisted before the field existed. ADDITIVE: `#[serde(default)]`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
    /// Durable client-input correlation id (`SessionInput.id`) for user rows.
    /// The kernel message id alone is not enough after a reconnect: a queued
    /// steer card carries the client id, so both halves must be on the row to
    /// dedupe without text heuristics. ADDITIVE: absent on old daemons/rows.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub client_input_id: Option<String>,
    /// Session-global v4 display order. Additive: absent for snapshot-only rows
    /// and old daemons. `after_seq` deltas use this cursor.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub seq: Option<u64>,
    /// Kernel turn id of the round that produced this row. Persisted so the WebUI
    /// can distinguish a steer folded into a RUNNING turn from a steer-delivered
    /// NEW turn after a terminal, even after a refresh. `None` for backfilled
    /// rows / legacy snapshots where the turn id is unknown.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub turn_id: Option<u64>,
    pub content: String,
    /// The model's reasoning/thinking for an ASSISTANT message — persisted
    /// losslessly in the kernel `Message.reasoning` but until now dropped at
    /// the API boundary, so a WebUI reload lost all earlier thinking and only
    /// showed whatever reasoning streamed in after the refresh. Now serialized
    /// so history (getSession / session detail) can re-render the full chain
    /// of thought.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub reasoning: Option<String>,
    /// True when a `Role::User` message was injected by the agent/runtime rather
    /// than authored by the human. UI clients use this to avoid rendering
    /// internal reminders as user input bubbles.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub synthetic: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub internal_origin: Option<String>,
    /// User-facing text. For user rows the display pipeline already unwraps the
    /// user envelope and strips injected reminders; clients must render THIS
    /// instead of re-parsing protocol strings out of `content`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub display_text: Option<String>,
    /// Server-authored visibility flag. A row is hidden from the transcript when
    /// this is true (synthetic reminders, verify-cadence narration).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub internal: Option<bool>,
    /// Whether the UI may edit / delete / rewind this row. Display-only archive
    /// and presentation rows are never editable.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub editable: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_calls: Option<Vec<ToolCallInfo>>,
    /// Tool result summary (for tool role messages)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_result: Option<ToolResultInfo>,
    /// Artifacts detected in this message (code blocks, HTML files, etc.)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub artifacts: Option<Vec<ArtifactInfo>>,
    /// Attached images (base64) for MultiPart user messages — lets the webui
    /// re-render thumbnails when loading history.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub images: Option<Vec<ImageData>>,
    /// Epoch MILLISECONDS this message was authored/received. lets the webui
    /// stamp each bubble with a send time (PR #562). The kernel's `Message`
    /// has no per-message clock, so for replayed history we approximate with
    /// the owning `Session::updated_at` (epoch SECONDS → ms); for live/snapshot
    /// turns the webui injects `Date.now()` client-side. `#[serde(default)]`
    /// keeps old daemons/clients interoperating when the field is absent.
    /// 注意单位: 毫秒 —— 与 `SessionDetail.created_at`/`updated_at` 一致
    /// (kernel 内部 `Session.created_at` 为秒, API 响应边界乘 1000 转换, bot review P2)。
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub created_at: Option<u64>,
    /// Wall-clock duration of the whole user turn (user send → final answer),
    /// not a single LLM round. Kernel `MessageMeta.elapsed_ms` is per-round;
    /// [`stamp_turn_elapsed_on_last_assistants`] rewrites the last assistant of
    /// each turn from `TurnStat.duration_ms` (or the user/assistant timestamp
    /// span) so refresh / session switch still shows the live "用时" total.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub elapsed_ms: Option<u64>,
}

/// Serializable image payload returned in session history.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ImageData {
    pub media_type: String,
    pub data: String,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub missing: bool,
}

impl ImageData {
    fn missing_placeholder() -> Self {
        Self {
            media_type: "image/png".to_string(),
            // 采用标准合法 1x1 透明 PNG Base64 占位，彻底杜绝浏览器 Data URI 为空时触发左上角小裂图坏图标
            data: "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==".to_string(),
            missing: true,
        }
    }
}

fn strip_vision_marker(raw: &str) -> (String, bool) {
    match raw
        .find("[图片内容（由")
        .or_else(|| raw.find("[图片识别失败]"))
    {
        Some(i) => (raw[..i].trim_end().to_string(), true),
        None => (raw.to_string(), false),
    }
}

/// Compact preview of a tool result for history UI. Prefer head+tail over first-line-only
/// so multi-row tables / JSON don't look empty after refresh. Already-compacted stubs
/// (single line starting with `[` and containing ` lines`) are returned as-is (capped).
fn tool_result_summary(text: &str) -> String {
    const CAP: usize = 240;
    let line_count = text.lines().count();
    let first = text.lines().next().unwrap_or("");
    // Compaction stubs / short single-line results: keep as one line.
    if line_count <= 1 {
        return if first.chars().count() > CAP {
            format!(
                "{}…",
                first
                    .chars()
                    .take(CAP.saturating_sub(1))
                    .collect::<String>()
            )
        } else {
            first.to_string()
        };
    }
    let head: String = first.chars().take(80).collect();
    let tail: String = text.lines().last().unwrap_or("").chars().take(80).collect();
    let summary = if tail.is_empty() || tail == head {
        format!("{line_count} lines | head: {head}")
    } else {
        format!("{line_count} lines | head: {head} | tail: {tail}")
    };
    if summary.chars().count() > CAP {
        format!(
            "{}…",
            summary
                .chars()
                .take(CAP.saturating_sub(1))
                .collect::<String>()
        )
    } else {
        summary
    }
}

impl MessageInfo {
    fn from_kernel(msg: &jeikcode_kernel::message::Message) -> Self {
        Self::from_kernel_in(msg, None)
    }

    fn from_kernel_in(
        msg: &jeikcode_kernel::message::Message,
        working_dir: Option<&std::path::Path>,
    ) -> Self {
        use jeikcode_kernel::message::Role;

        let role = match msg.role {
            Role::System => "system",
            Role::User => "user",
            Role::Assistant => "assistant",
            Role::Tool => "tool",
        };
        let tool_calls = (!msg.tool_calls.is_empty()).then(|| {
            msg.tool_calls
                .iter()
                .map(|call| ToolCallInfo {
                    id: call.id.clone(),
                    name: call.name.clone(),
                    arguments: call.arguments.clone(),
                    display: format_tool_args(&call.name, &call.arguments),
                })
                .collect()
        });
        let tool_result = (msg.role == Role::Tool).then(|| {
            ToolResultInfo {
                call_id: msg.tool_call_id.clone().unwrap_or_default(),
                success: !msg.is_error,
                // Head+tail summary (not first-line-only) so WebUI history doesn't look
                // empty after multi-line SQL/table outputs. Full text remains in `content`.
                summary: tool_result_summary(&msg.text),
                line_count: msg.text.lines().count(),
            }
        });
        let artifacts = extract_artifacts_from_call_fields(
            msg.tool_calls
                .iter()
                .map(|call| (call.name.as_str(), call.arguments.as_str())),
        );
        let mut content = msg.text.clone();
        let mut images = (!msg.images.is_empty()).then(|| {
            msg.images
                .iter()
                .map(|image| ImageData {
                    media_type: image.media_type.clone(),
                    data: image.data.clone(),
                    missing: false,
                })
                .collect()
        });
        if msg.role == Role::User {
            let cwd = working_dir.unwrap_or_else(|| std::path::Path::new("."));
            content = jeikcode_capabilities::session::user_text_for_display(cwd, &content);
            let (display, had_vision_marker) = strip_vision_marker(&content);
            if had_vision_marker {
                content = display;
                if images.is_none() {
                    images = Some(vec![ImageData::missing_placeholder()]);
                }
            }
        }
        let display_text = (msg.role == Role::User).then(|| content.clone());
        let internal = msg.synthetic || msg.internal_origin.as_deref() == Some("verify_cadence");
        let editable = (msg.role == Role::User).then(|| {
            !msg.synthetic
                && !matches!(
                    msg.internal_origin.as_deref(),
                    Some("transcript_archive") | Some("presentation") | Some("pending_input")
                )
        });
        Self {
            seq: None,
            turn_id: msg
                .meta
                .as_ref()
                .and_then(|meta| (meta.turn_id > 0).then_some(meta.turn_id)),
            role: role.into(),
            id: msg.id.clone(),
            client_input_id: None,
            content,
            reasoning: msg.reasoning.clone(),
            synthetic: msg.synthetic,
            internal_origin: msg.internal_origin.clone(),
            display_text,
            internal: Some(internal),
            editable,
            tool_calls,
            tool_result,
            artifacts,
            images,
            created_at: (msg.created_at_ms > 0).then_some(msg.created_at_ms),
            elapsed_ms: msg.meta.as_ref().map(|m| m.elapsed_ms).filter(|&ms| ms > 0),
        }
    }
}

fn extract_artifacts_from_call_fields<'a>(
    tool_calls: impl IntoIterator<Item = (&'a str, &'a str)>,
) -> Option<Vec<ArtifactInfo>> {
    let mut artifacts = Vec::new();

    for (name, arguments) in tool_calls {
        if matches!(
            name,
            "write" | "write_file" | "create_file" | "edit" | "edit_file"
        ) {
            // Parse arguments
            let args: serde_json::Value = match serde_json::from_str(arguments) {
                Ok(v) => v,
                Err(_) => continue,
            };

            let path = match args
                .get("path")
                .or_else(|| args.get("file_path"))
                .and_then(|v| v.as_str())
            {
                Some(p) => p,
                None => continue,
            };

            let (artifact_type, language) = if path.ends_with(".html") || path.ends_with(".htm") {
                ("html", "html")
            } else if path.ends_with(".svg") {
                ("svg", "xml")
            } else if path.ends_with(".md") || path.ends_with(".markdown") {
                ("markdown", "markdown")
            } else if path.ends_with(".pptx") {
                ("pptx", "pptx")
            } else if path.ends_with(".docx") {
                ("docx", "docx")
            } else if path.ends_with(".xlsx") {
                ("xlsx", "xlsx")
            } else if path.ends_with(".pdf") {
                ("pdf", "pdf")
            } else {
                continue; // Skip other file types
            };

            // Get content from arguments (optional for binary files)
            let content = args
                .get("content")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string();

            // Extract title from path
            let title = PathBuf::from(path)
                .file_name()
                .map(|n| n.to_string_lossy().to_string());

            artifacts.push(ArtifactInfo {
                id: format!("file-{}", artifacts.len() + 1),
                artifact_type: artifact_type.to_string(),
                title,
                language: Some(language.to_string()),
                content,
            });
        } else if jeikcode_capabilities::tools::is_shell_tool_name(name) {
            // Extract artifacts from bash commands that create files
            let args: serde_json::Value = match serde_json::from_str(arguments) {
                Ok(v) => v,
                Err(_) => continue,
            };

            let command = match args
                .get("command")
                .or_else(|| args.get("cmd"))
                .and_then(|v| v.as_str())
            {
                Some(c) => c,
                None => continue,
            };

            // Look for file redirection ( > or >> ) to artifact file types
            if let Some(path) = extract_output_file_from_bash(command) {
                let (artifact_type, language) = if path.ends_with(".html") || path.ends_with(".htm")
                {
                    ("html", "html")
                } else if path.ends_with(".svg") {
                    ("svg", "xml")
                } else if path.ends_with(".md") || path.ends_with(".markdown") {
                    ("markdown", "markdown")
                } else if path.ends_with(".pptx") {
                    ("pptx", "pptx")
                } else if path.ends_with(".docx") {
                    ("docx", "docx")
                } else if path.ends_with(".xlsx") {
                    ("xlsx", "xlsx")
                } else if path.ends_with(".pdf") {
                    ("pdf", "pdf")
                } else {
                    continue;
                };

                let title = PathBuf::from(&path)
                    .file_name()
                    .map(|n| n.to_string_lossy().to_string());

                artifacts.push(ArtifactInfo {
                    id: format!("file-{}", artifacts.len() + 1),
                    artifact_type: artifact_type.to_string(),
                    title,
                    language: Some(language.to_string()),
                    content: String::new(), // Content not available from bash
                });
            }
        }
    }

    if artifacts.is_empty() {
        None
    } else {
        Some(artifacts)
    }
}

/// Extract output file path from bash command (handles > and >> redirection, and quoted paths)
fn extract_output_file_from_bash(command: &str) -> Option<String> {
    // Artifact file extensions to look for
    let artifact_extensions = [
        ".html",
        ".htm",
        ".svg",
        ".md",
        ".markdown",
        ".pptx",
        ".docx",
        ".xlsx",
        ".pdf",
    ];

    // First, try to find > or >> redirection
    let chars: Vec<char> = command.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        if chars[i] == '>' {
            // Found redirection
            let append_mode = i + 1 < chars.len() && chars[i + 1] == '>';
            let start = if append_mode { i + 2 } else { i + 1 };

            // Skip whitespace
            let mut j = start;
            while j < chars.len() && chars[j].is_whitespace() {
                j += 1;
            }

            // Extract file path until whitespace or end
            let mut path_end = j;
            while path_end < chars.len()
                && !chars[path_end].is_whitespace()
                && chars[path_end] != ';'
                && chars[path_end] != '&'
            {
                path_end += 1;
            }

            if j < path_end {
                let path: String = chars[j..path_end].iter().collect();
                // Remove quotes if present
                let path = path.trim_matches(|c| c == '"' || c == '\'').to_string();
                if artifact_extensions.iter().any(|ext| path.ends_with(ext)) {
                    return Some(path);
                }
            }
        }
        i += 1;
    }

    // Look for quoted paths with artifact extensions
    // Pattern: 'path.pptx' or "path.docx"
    let mut in_single_quote = false;
    let mut in_double_quote = false;
    let mut quote_start = 0usize;
    let chars: Vec<char> = command.chars().collect();

    for (idx, &ch) in chars.iter().enumerate() {
        if ch == '\'' && !in_double_quote {
            if in_single_quote {
                // End of single-quoted string
                let path: String = chars[quote_start..idx].iter().collect();
                if artifact_extensions.iter().any(|ext| path.ends_with(ext)) {
                    return Some(path);
                }
                in_single_quote = false;
            } else {
                in_single_quote = true;
                quote_start = idx + 1;
            }
        } else if ch == '"' && !in_single_quote {
            if in_double_quote {
                // End of double-quoted string
                let path: String = chars[quote_start..idx].iter().collect();
                if artifact_extensions.iter().any(|ext| path.ends_with(ext)) {
                    return Some(path);
                }
                in_double_quote = false;
            } else {
                in_double_quote = true;
                quote_start = idx + 1;
            }
        }
    }

    None
}

/// Format tool arguments for display (CLI style)
fn format_tool_args(tool_name: &str, args_json: &str) -> String {
    let args: serde_json::Value = match serde_json::from_str(args_json) {
        Ok(v) => v,
        Err(_) => return String::new(),
    };

    match tool_name {
        "read" | "read_file" => {
            let path = args
                .get("path")
                .or_else(|| args.get("file_path"))
                .and_then(|v| v.as_str())
                .unwrap_or("");
            let short = short_path(path);
            let mut s = short;
            if let Some(offset) = args.get("offset").and_then(|v| v.as_u64()) {
                if let Some(limit) = args.get("limit").and_then(|v| v.as_u64()) {
                    s.push_str(&format!(" L{}-{}", offset, offset + limit));
                }
            }
            s
        }
        "write" | "write_file" | "create_file" => {
            let path = args
                .get("path")
                .or_else(|| args.get("file_path"))
                .and_then(|v| v.as_str())
                .unwrap_or("");
            let size = args
                .get("content")
                .and_then(|v| v.as_str())
                .map(|s| s.len())
                .unwrap_or(0);
            format!("{} ({} bytes)", short_path(path), size)
        }
        "edit" | "edit_file" => {
            let path = args
                .get("path")
                .or_else(|| args.get("file_path"))
                .and_then(|v| v.as_str())
                .unwrap_or("");
            short_path(path)
        }
        "bash" | "run_command" => {
            let cmd = args
                .get("command")
                .or_else(|| args.get("cmd"))
                .and_then(|v| v.as_str())
                .unwrap_or("");
            let shown = if cmd.chars().count() > 80 {
                format!("{}...", cmd.chars().take(77).collect::<String>())
            } else {
                cmd.to_string()
            };
            let summary = args
                .get("summary")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .trim();
            if summary.is_empty() {
                format!("`{shown}`")
            } else {
                format!("{summary} — `{shown}`")
            }
        }
        "code_explore" => {
            let query = args.get("query").and_then(|v| v.as_str()).unwrap_or("");
            let path = args.get("path").and_then(|v| v.as_str()).unwrap_or(".");
            format!("\"{}\" in {}", query, short_path(path))
        }
        "task" => {
            if let Some(tasks) = args.get("tasks").and_then(|t| t.as_array()) {
                format!("{} subtask(s)", tasks.len())
            } else {
                "subtask".to_string()
            }
        }
        "list_directory" => {
            // Schema primary key is `target_directory`; `path` is a serde alias for older calls.
            let path = args
                .get("target_directory")
                .or_else(|| args.get("path"))
                .and_then(|v| v.as_str())
                .unwrap_or(".");
            short_path(path)
        }
        "grep" => {
            let pattern = args.get("pattern").and_then(|v| v.as_str()).unwrap_or("");
            let path = args.get("path").and_then(|v| v.as_str()).unwrap_or(".");
            format!("\"{}\" in {}", pattern, short_path(path))
        }
        "glob" => {
            let pattern = args.get("pattern").and_then(|v| v.as_str()).unwrap_or("");
            format!("\"{}\"", pattern)
        }
        "web_search" => {
            let query = args.get("query").and_then(|v| v.as_str()).unwrap_or("");
            format!("\"{}\"", query)
        }
        "web_fetch" => {
            let url = args.get("url").and_then(|v| v.as_str()).unwrap_or("");
            url.to_string()
        }
        _ => {
            if let Some(obj) = args.as_object() {
                obj.iter()
                    .map(|(k, v)| {
                        let val = match v {
                            serde_json::Value::String(s) if s.chars().count() > 30 => {
                                format!("{}...", s.chars().take(27).collect::<String>())
                            }
                            serde_json::Value::String(s) => s.clone(),
                            other => other.to_string(),
                        };
                        format!("{}={}", k, val)
                    })
                    .collect::<Vec<_>>()
                    .join(" ")
            } else {
                String::new()
            }
        }
    }
}

fn short_path(path: &str) -> String {
    let parts: Vec<&str> = path.rsplitn(3, '/').collect();
    match parts.len() {
        0 | 1 => path.to_string(),
        2 => format!("{}/{}", parts[1], parts[0]),
        _ => format!(".../{}/{}", parts[1], parts[0]),
    }
}
fn dangerous_tools_enabled() -> bool {
    std::env::var(DANGEROUS_TOOLS_ENV).ok().as_deref() == Some("1")
}

fn compression_layer() -> CompressionLayer<impl Predicate + Clone> {
    CompressionLayer::new().gzip(true).br(true).compress_when(
        DefaultPredicate::new()
            .and(NotForContentType::new("text/event-stream"))
            .and(CompressibleContentType),
    )
}

/// Binary payloads are already compressed (or incompressible): gzip/brotli only
/// burns CPU and can enlarge them. SSE is excluded separately above.
#[derive(Clone, Copy, Default)]
struct CompressibleContentType;

fn is_binary_content_type(content_type: &str) -> bool {
    let value = content_type.trim().to_ascii_lowercase();
    value.starts_with("image/")
        || value.starts_with("video/")
        || value.starts_with("audio/")
        || value.starts_with("font/")
        || value.starts_with("application/zip")
        || value.starts_with("application/gzip")
        || value.starts_with("application/x-gzip")
        || value.starts_with("application/octet-stream")
        || value.starts_with("application/pdf")
        || value.starts_with("application/wasm")
}

impl Predicate for CompressibleContentType {
    fn should_compress<B>(&self, response: &axum::http::Response<B>) -> bool
    where
        B: axum::body::HttpBody,
    {
        let content_type = response
            .headers()
            .get(axum::http::header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .unwrap_or("");
        !is_binary_content_type(content_type)
    }
}

#[cfg(test)]
mod compression_predicate_tests {
    use super::is_binary_content_type;

    #[test]
    fn binary_content_types_are_excluded_from_compression() {
        for content_type in [
            "image/png",
            "video/mp4",
            "audio/mpeg",
            "font/woff2",
            "application/zip",
            "application/gzip",
            "application/octet-stream",
            "application/pdf",
            "application/wasm",
        ] {
            assert!(is_binary_content_type(content_type), "{content_type}");
        }
        for content_type in [
            "application/json",
            "text/html; charset=utf-8",
            "text/event-stream",
            "application/javascript",
        ] {
            assert!(!is_binary_content_type(content_type), "{content_type}");
        }
    }
}

fn cors_layer() -> CorsLayer {
    // Loopback-only was correct when the daemon only ever bound 127.0.0.1.
    // `jeikcode serve --host 0.0.0.0` (and LAN binds) serve the SPA from a
    // private IP; some browsers/WebViews treat custom-header POSTs as CORS
    // even on that host. Allow loopback + private-network origins so remote
    // LAN clients can call the API. Public internet origins stay denied —
    // token auth is the real gate for serve mode, not CORS.
    CorsLayer::new()
        .allow_origin(AllowOrigin::predicate(is_allowed_cors_origin))
        .allow_methods([Method::GET, Method::POST, Method::PATCH, Method::DELETE])
        .allow_headers([
            header::CONTENT_TYPE,
            header::AUTHORIZATION,
            header::IF_NONE_MATCH,
            HeaderName::from_static("x-jeikcode-client"),
        ])
        .expose_headers([header::ETAG])
        .allow_credentials(true)
}

fn is_legacy_live_transport(path: &str) -> bool {
    matches!(
        path,
        "/live" | "/live/message" | "/live/stop" | "/live/compact" | "/live/switch_session"
    )
}

/// Mark the retired `/live` transport without breaking older clients. The
/// current WebUI uses `/chat` + `/chat/watch`; these endpoints remain for an
/// external compatibility window.
async fn legacy_live_deprecation_middleware(
    req: axum::extract::Request,
    next: axum::middleware::Next,
) -> axum::response::Response {
    let path = req.uri().path().to_string();
    let mut response = next.run(req).await;
    if is_legacy_live_transport(&path) {
        response.headers_mut().insert(
            axum::http::header::HeaderName::from_static("deprecation"),
            axum::http::HeaderValue::from_static("true"),
        );
        response.headers_mut().insert(
            axum::http::header::HeaderName::from_static("link"),
            axum::http::HeaderValue::from_static("</chat>; rel=\"successor-version\""),
        );
        tracing::warn!(path = %path, "deprecated /live transport used");
    }
    response
}

/// Middleware that updates `last_activity` timestamp on every request except
/// GET /health and POST /shutdown (these should not prevent idle timeout).
async fn activity_tracker_middleware(
    req: axum::extract::Request,
    next: axum::middleware::Next,
) -> axum::response::Response {
    let skip = (req.method() == Method::GET && req.uri().path() == "/health")
        || (req.method() == Method::POST && req.uri().path() == "/shutdown");

    if !skip {
        if let Some(activity) = req.extensions().get::<Arc<std::sync::atomic::AtomicI64>>() {
            activity.store(now_unix_ms(), std::sync::atomic::Ordering::Relaxed);
        }
    }

    // Resolve client mode from X-JeikCode-Client header
    let client_mode = req
        .headers()
        .get("x-jeikcode-client")
        .and_then(|v| v.to_str().ok())
        .map(resolve_client_mode)
        .unwrap_or(SessionMode::Ide);
    let mut req = req;
    req.extensions_mut().insert(client_mode);

    next.run(req).await
}

/// Map X-JeikCode-Client header value to SessionMode.
/// Unknown values fall back to Ide.
fn resolve_client_mode(header: &str) -> SessionMode {
    match header {
        "channel" => SessionMode::Channel,
        "vscode" => SessionMode::Vscode,
        "jetbrains" => SessionMode::Jetbrains,
        "webui" => SessionMode::Webui,
        "jeikcode-air" => SessionMode::JeikcodeAir,
        _ => SessionMode::Ide,
    }
}

/// CORS allowlist for webui: loopback **or** RFC1918 / link-local private hosts.
/// Used so LAN clients of `jeikcode serve` are not blocked when a browser emits
/// an Origin header for same-host API calls with custom headers.
fn is_allowed_cors_origin(origin: &HeaderValue, _request_parts: &RequestParts) -> bool {
    let Some(authority) = origin_authority(origin) else {
        return false;
    };
    if is_loopback_authority(&authority) || is_private_network_authority(&authority) {
        return true;
    }
    let host = if let Some(rest) = authority.strip_prefix('[') {
        rest.split(']').next().unwrap_or(rest)
    } else {
        authority.split(':').next().unwrap_or(&authority)
    };
    // 允许局域网/Tailscale/常见内部域名
    if host.ends_with(".local") || host.ends_with(".lan") || host.ends_with(".ts.net") {
        return true;
    }
    // 若 Origin authority 与请求的 Host 头一致（同主机直连自托管请求，包括公网 IPv4 / 双栈公网 IPv6 / 域名直连），直接放行
    if let Some(host_hdr) = _request_parts
        .headers
        .get(header::HOST)
        .and_then(|h| h.to_str().ok())
    {
        if authority.eq_ignore_ascii_case(host_hdr.trim()) {
            return true;
        }
    }
    false
}

fn origin_authority(origin: &HeaderValue) -> Option<String> {
    let origin = origin.to_str().ok()?;
    let authority = origin
        .strip_prefix("http://")
        .or_else(|| origin.strip_prefix("https://"))?;
    Some(authority.to_string())
}

fn is_loopback_authority(authority: &str) -> bool {
    if let Some(rest) = authority.strip_prefix("[::1]") {
        return rest.is_empty() || rest.starts_with(':');
    }

    let host = authority.split(':').next().unwrap_or(authority);
    matches!(host, "localhost" | "127.0.0.1" | "::1")
}

/// Host part of an Origin/authority is a private/LAN address (not public internet).
fn is_private_network_authority(authority: &str) -> bool {
    let host = if let Some(rest) = authority.strip_prefix('[') {
        // IPv6 literal: [::ffff:192.168.0.1]:port or [fe80::1]:port
        rest.split(']').next().unwrap_or(rest)
    } else {
        authority.split(':').next().unwrap_or(authority)
    };
    if let Ok(ip) = host.parse::<std::net::IpAddr>() {
        return match ip {
            std::net::IpAddr::V4(v4) => {
                v4.is_private() || v4.is_link_local() || v4.is_loopback() || v4.is_unspecified()
            }
            std::net::IpAddr::V6(v6) => {
                let seg0 = v6.segments()[0];
                v6.is_loopback()
                    || (seg0 & 0xfe00) == 0xfc00 // unique local fc00::/7
                    || (seg0 & 0xffc0) == 0xfe80 // link-local fe80::/10
            }
        };
    }
    false
}

/// Whether this client can receive interactive approval prompts.
///
/// - **WebUI** always can: the SPA has `PermissionCard` + `POST /chat/permission`
///   and shows Build / Accept Edits / Auto / Plan. Honoring that UI must not
///   depend on bind host or token — otherwise LAN `serve --host 0.0.0.0`
///   (with or without `--no-token`) silently sets `dangerously_skip_permissions`
///   for Build and contradicts the mode pill.
/// - **Other known clients** (channel / VSCode / JetBrains): interactive when
///   token-protected, or on loopback (UI can answer `/chat/permission`).
/// - **API** never uses this path (`ChatTurnOrigin::Api` → automation policy).
fn client_interactive_permission(
    client_mode: SessionMode,
    enforce_token: bool,
    bind_host: &str,
) -> bool {
    if matches!(client_mode, SessionMode::Webui) {
        return true;
    }
    enforce_token
        || (matches!(
            client_mode,
            SessionMode::Channel | SessionMode::Vscode | SessionMode::Jetbrains
        ) && is_loopback_authority(bind_host))
}

/// Who owns a `/chat` turn and which interaction policy applies.
///
/// Product rules (serve):
/// - **API** (OpenAI/Anthropic `/v1/*`): low-confirm — Auto tools; no permission /
///   user-input modals; residual `request_user_input` → final-answer handoff so the
///   client replies in the **next** message. WebUI `/chat/watch` is an **observer**
///   of this policy (must not open extra modals). Unchanged by WebUI mode pill.
/// - **Native WebUI** (`POST /chat` from the SPA input): full mode pill —
///   Build / Accept Edits / Auto / Plan — always interactive for permission +
///   user-input (LAN / no-token included). Request body `approval_mode` (or
///   global `/approval_mode`) is honored; never force Auto here.
/// - **Other native** (channel / IDE on loopback or token): interactive when the
///   client can answer `/chat/permission`.
/// - **Yolo** (`serve --yolo`): every path follows automation — Auto, no modals,
///   `request_user_input` unmounted process-wide.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ChatTurnOrigin {
    /// OpenAI / Anthropic compatible HTTP API.
    Api,
    /// WebUI, TUI-attached clients, channel, VSCode, etc. sending their own turn.
    Native,
}

/// Resolved interaction flags for one chat turn.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct ChatTurnPolicy {
    pub origin: ChatTurnOrigin,
    /// Wait on `/chat/permission` (every mode except Auto, when the client can answer).
    pub interactive_permission: bool,
    /// Wait on WebUI `/chat/user-input` for `request_user_input`.
    pub interactive_user_input: bool,
    /// When set, force this approval mode for the turn (API / YOLO → Auto).
    pub force_approval_mode: Option<crate::approval_mode::ApprovalMode>,
}

impl ChatTurnPolicy {
    /// `serve --yolo`: all surfaces share automation policy.
    pub fn yolo() -> Self {
        Self {
            origin: ChatTurnOrigin::Api,
            interactive_permission: false,
            interactive_user_input: false,
            force_approval_mode: Some(crate::approval_mode::ApprovalMode::Auto),
        }
    }

    /// OpenAI/Anthropic `/v1/*` (and any pure automation chat entry).
    pub fn api_automation() -> Self {
        Self {
            origin: ChatTurnOrigin::Api,
            interactive_permission: false,
            interactive_user_input: false,
            force_approval_mode: Some(crate::approval_mode::ApprovalMode::Auto),
        }
    }

    /// WebUI / channel / IDE own message — honor the client's mode pill when the
    /// client can answer approval / user-input. Does **not** force Auto (that is
    /// reserved for API + YOLO).
    pub fn native(client_mode: SessionMode, enforce_token: bool, bind_host: &str) -> Self {
        Self {
            origin: ChatTurnOrigin::Native,
            interactive_permission: client_interactive_permission(
                client_mode,
                enforce_token,
                bind_host,
            ),
            // Only WebUI implements the typed user-input response endpoint today.
            interactive_user_input: matches!(client_mode, SessionMode::Webui),
            // Native turns use the request/global mode (Build/AcceptEdits/Auto/Plan).
            force_approval_mode: None,
        }
    }

    /// Resolve policy for a daemon chat entry.
    /// YOLO wins over origin; otherwise API vs native as requested.
    pub fn resolve(
        yolo: bool,
        origin: ChatTurnOrigin,
        client_mode: SessionMode,
        enforce_token: bool,
        bind_host: &str,
    ) -> Self {
        if yolo {
            return Self::yolo();
        }
        match origin {
            ChatTurnOrigin::Api => Self::api_automation(),
            ChatTurnOrigin::Native => Self::native(client_mode, enforce_token, bind_host),
        }
    }
}

fn effective_chat_approval_mode(
    request_mode: Option<crate::approval_mode::ApprovalMode>,
) -> crate::approval_mode::ApprovalMode {
    effective_chat_approval_mode_scoped(request_mode, None)
}

/// Final approval mode for one `/chat` turn.
///
/// 优先级：策略强制（API / YOLO）> 全局开关 > 会话级 > 请求体 > 进程级默认。
/// `forced` 必须压过全局开关：否则 WebUI 切到全局 Plan 会连累 `/v1/*` 自动化。
fn resolve_turn_approval_mode(
    forced: Option<crate::approval_mode::ApprovalMode>,
    request_mode: Option<crate::approval_mode::ApprovalMode>,
    session_id: Option<&str>,
) -> crate::approval_mode::ApprovalMode {
    match forced {
        Some(forced) => forced,
        None => effective_chat_approval_mode_scoped(request_mode, session_id),
    }
}

fn effective_chat_approval_mode_scoped(
    request_mode: Option<crate::approval_mode::ApprovalMode>,
    session_id: Option<&str>,
) -> crate::approval_mode::ApprovalMode {
    // 全局开关开启：所有会话统一，请求体里的旧副本也不再影响。
    if live_api::live_global_mode_enabled() {
        return live_api::live_current_approval_mode();
    }
    // 会话级模式优先：它来自用户显式切换（含异地广播）。请求体里的
    // `approval_mode` 可能是另一实例上的陈旧副本，绝不能反向覆盖。
    if let Some(mode) = live_api::live_session_approval_mode_cached(session_id) {
        return mode;
    }
    request_mode.unwrap_or_else(|| live_api::live_session_approval_mode(session_id))
}

/// Modes that park the turn until the WebUI/TUI answers `/chat/permission`.
/// Only **Auto** (`bypass`) auto-approves and must not register a responder.
/// Build / AcceptEdits / Plan all need a human when a tool is gated.
fn approval_mode_requires_responder(mode: crate::approval_mode::ApprovalMode) -> bool {
    !matches!(mode, crate::approval_mode::ApprovalMode::Auto)
}

/// Map a working directory to its physical session-bucket name.
///
/// Delegates to the native store so API project ids and physical buckets stay
/// byte-for-byte identical.
pub(crate) fn hash_path(path: &std::path::Path) -> String {
    NativeSessionManager::project_hash(path)
}

fn response_project_hash(path: &std::path::Path) -> String {
    hash_path(path)
}

/// System temp directory prefixes to exclude from the project list.
/// These are directories that are not meaningful as user projects.
fn is_system_temp_dir(path: &std::path::Path) -> bool {
    let path_str = path.to_string_lossy();
    // Unix/Linux/macOS temp dirs
    if path_str.starts_with("/tmp/") || path_str == "/tmp" {
        return true;
    }
    if path_str.starts_with("/var/tmp/") || path_str == "/var/tmp" {
        return true;
    }
    // Windows temp dirs
    if path_str.contains("\\Temp\\")
        || path_str.contains("\\TEMP\\")
        || path_str.ends_with("\\Temp")
        || path_str.ends_with("\\TEMP")
    {
        return true;
    }
    // /private/tmp (macOS symlink target for /tmp)
    if path_str.starts_with("/private/tmp/") || path_str == "/private/tmp" {
        return true;
    }
    false
}

/// List all projects (scans sessions directory)
fn list_projects() -> std::io::Result<Vec<ProjectInfo>> {
    let sessions_root = NativeSessionManager::sessions_root();
    let scan = catalog_scan_in_root(&sessions_root)?;
    let active = active_catalog_location(&scan.entries);
    list_projects_in_root(&sessions_root, active.as_ref())
}

fn list_projects_in_root(
    sessions_root: &std::path::Path,
    active: Option<&jeikcode_capabilities::session::CatalogLocation>,
) -> std::io::Result<Vec<ProjectInfo>> {
    let scan = catalog_scan_in_root(sessions_root)?;
    let mut by_project_entries = std::collections::BTreeMap::<
        String,
        Vec<jeikcode_capabilities::session::CatalogEntry>,
    >::new();
    for entry in scan.entries {
        if is_system_temp_dir(&entry.working_dir) {
            continue;
        }
        if !catalog_entry_is_visible(sessions_root, &entry, active) {
            continue;
        }
        by_project_entries
            .entry(entry.project_bucket.clone())
            .or_default()
            .push(entry);
    }
    let mut projects = Vec::new();
    for (bucket, mut entries) in by_project_entries {
        NativeSessionManager::collapse_fork_lineages(&mut entries);
        if entries.is_empty() {
            continue;
        }
        let session_count = entries.len();
        let mut created_at = u64::MAX;
        let mut last_updated = 0;
        let mut name = String::new();
        let mut working_dir = PathBuf::new();

        for entry in &entries {
            let c = u64::try_from(entry.created_at_ms.max(0)).unwrap_or(0) / 1_000;
            let u = u64::try_from(entry.updated_at_ms.max(0)).unwrap_or(0) / 1_000;
            created_at = created_at.min(c);
            if u >= last_updated {
                last_updated = u;
                working_dir = entry.working_dir.clone();
                name = entry
                    .working_dir
                    .file_name()
                    .map(|n| n.to_string_lossy().into_owned())
                    .unwrap_or_else(|| "unknown".into());
            }
        }
        if created_at == u64::MAX {
            created_at = last_updated;
        }

        projects.push(ProjectInfo {
            hash: bucket,
            name,
            working_dir,
            description: None,
            session_count,
            created_at,
            last_updated,
        });
    }
    projects.sort_by(|a, b| b.last_updated.cmp(&a.last_updated));
    Ok(projects)
}

/// 根据项目哈希查找关联的项目工作目录
pub fn find_working_dir_for_project_hash(project_hash: &str) -> Option<PathBuf> {
    let hash = project_hash.trim();
    if hash.is_empty() {
        return None;
    }
    if let Ok(projects) = list_projects() {
        for p in projects {
            if p.hash == hash {
                return Some(p.working_dir);
            }
        }
    }
    None
}

/// Session metadata with project hash for cross-project listing
#[derive(Debug, Serialize)]
pub struct SessionMetaWithProject {
    pub project_hash: String,
    #[serde(flatten)]
    pub meta: SessionSummary,
}

/// Daemon/API listing DTO. Its wire shape intentionally matches the retired
/// core `SessionMeta`, but it is sourced directly from the native catalog.
#[derive(Debug, Clone, Serialize)]
pub struct SessionSummary {
    pub id: String,
    pub name: String,
    pub working_dir: PathBuf,
    pub created_at: u64,
    pub updated_at: u64,
    pub message_count: usize,
    #[serde(default)]
    pub file_size: u64,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub approval_mode: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub preferred_model: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reasoning_effort: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub thinking_budget: Option<u32>,
}

fn catalog_scan_in_root(
    root: &std::path::Path,
) -> std::io::Result<jeikcode_capabilities::session::CatalogScan> {
    let scan = jeikcode_capabilities::session::SessionManager::scan_catalog(root);
    for diagnostic in &scan.diagnostics {
        tracing::warn!(
            path = %diagnostic.path.display(),
            kind = ?diagnostic.kind,
            message = %diagnostic.message,
            "session catalog entry was skipped"
        );
    }
    Ok(scan)
}

fn catalog_entry_to_session_summary(
    entry: &jeikcode_capabilities::session::CatalogEntry,
) -> SessionSummary {
    // Catalog entries already carry the four session-scoped config fields, so
    // the list path does not re-open `<id>.meta` for every row.
    let preferred_model = entry.preferred_model.clone();
    // 全局开关优先，其余情况磁盘元数据 > 内存热态（不再回扫会话目录）。
    let approval_mode =
        live_api::live_display_approval_mode_wire(&entry.id, entry.approval_mode.as_deref());
    SessionSummary {
        id: entry.id.clone(),
        name: entry.name.clone(),
        working_dir: entry.working_dir.clone(),
        created_at: u64::try_from(entry.created_at_ms.max(0)).unwrap_or(0) / 1_000,
        updated_at: u64::try_from(entry.updated_at_ms.max(0)).unwrap_or(0) / 1_000,
        message_count: entry.message_count,
        file_size: 0,
        approval_mode: Some(approval_mode),
        preferred_model,
        reasoning_effort: entry.reasoning_effort.clone(),
        thinking_budget: entry.thinking_budget,
    }
}

fn catalog_entry_with_project(
    entry: &jeikcode_capabilities::session::CatalogEntry,
) -> SessionMetaWithProject {
    SessionMetaWithProject {
        project_hash: entry.project_bucket.clone(),
        meta: catalog_entry_to_session_summary(entry),
    }
}

fn active_catalog_location(
    entries: &[jeikcode_capabilities::session::CatalogEntry],
) -> Option<jeikcode_capabilities::session::CatalogLocation> {
    let binding = crate::native_live::binding().ok()?;
    resolve_active_catalog_location(entries, &binding.session_id, &binding.working_dir)
}

fn resolve_active_catalog_location(
    entries: &[jeikcode_capabilities::session::CatalogEntry],
    session_id: &str,
    working_dir: &std::path::Path,
) -> Option<jeikcode_capabilities::session::CatalogLocation> {
    let working_dir_key = jeikcode_capabilities::pathnorm::path_case_key(working_dir);
    let mut matches = entries.iter().filter(|entry| {
        entry.id == session_id
            && jeikcode_capabilities::pathnorm::path_case_key(&entry.working_dir) == working_dir_key
    });
    let entry = matches.next()?;
    // A logical working directory is not a physical catalog identity: resumed
    // and imported sessions may live in a historical bucket. Fail closed on an
    // ambiguous duplicate instead of manufacturing a bucket from the cwd.
    if matches.next().is_some() {
        return None;
    }
    Some(jeikcode_capabilities::session::CatalogLocation {
        id: entry.id.clone(),
        project_bucket: entry.project_bucket.clone(),
    })
}

fn binding_targets_catalog_location(
    entries: &[jeikcode_capabilities::session::CatalogEntry],
    binding: &crate::live_hub::LiveBinding,
    project_bucket: &str,
    session_id: &str,
) -> bool {
    binding.session_id == session_id
        && resolve_active_catalog_location(entries, session_id, &binding.working_dir)
            .is_some_and(|location| location.project_bucket == project_bucket)
}

fn catalog_entry_is_visible(
    sessions_root: &std::path::Path,
    entry: &jeikcode_capabilities::session::CatalogEntry,
    active: Option<&jeikcode_capabilities::session::CatalogLocation>,
) -> bool {
    if entry.message_count > 0 {
        return true;
    }
    if active.is_some_and(|location| {
        location.id == entry.id && location.project_bucket == entry.project_bucket
    }) {
        return true;
    }
    if entry.presence == jeikcode_capabilities::session::CatalogPresence::LegacyOnly {
        return false;
    }
    NativeSessionManager::with_root(sessions_root.join(&entry.project_bucket))
        .has_valid_inflight_snapshot(&entry.id)
}

static SESSION_CATALOG_IO: tokio::sync::Semaphore = tokio::sync::Semaphore::const_new(1);

/// Run bulk catalog scans off the async runtime and serialize them so queued
/// refreshes rescan after any durable placeholder-name repairs.
async fn run_session_catalog_io<T>(
    operation: impl FnOnce() -> std::io::Result<T> + Send + 'static,
) -> std::io::Result<T>
where
    T: Send + 'static,
{
    let permit = SESSION_CATALOG_IO.acquire().await.map_err(|error| {
        std::io::Error::other(format!("session catalog coordinator closed: {error}"))
    })?;
    tokio::task::spawn_blocking(move || {
        let _permit = permit;
        operation()
    })
    .await
    .map_err(|error| std::io::Error::other(format!("session catalog task failed: {error}")))?
}

/// List sessions for a project
fn list_sessions(project_hash: &str) -> std::io::Result<Vec<SessionSummary>> {
    let scan = catalog_scan_in_root(&NativeSessionManager::sessions_root())?;
    let active = active_catalog_location(&scan.entries);
    list_sessions_in_root(
        &NativeSessionManager::sessions_root(),
        project_hash,
        active.as_ref(),
    )
}

fn list_sessions_in_root(
    sessions_root: &std::path::Path,
    project_hash: &str,
    active: Option<&jeikcode_capabilities::session::CatalogLocation>,
) -> std::io::Result<Vec<SessionSummary>> {
    let mut entries: Vec<_> = catalog_scan_in_root(sessions_root)?
        .entries
        .into_iter()
        .filter(|entry| {
            entry.project_bucket == project_hash
                && catalog_entry_is_visible(sessions_root, entry, active)
        })
        .collect();
    NativeSessionManager::collapse_fork_lineages(&mut entries);
    crate::legacy_convert::repair_catalog_names_for_display_in_root(sessions_root, &mut entries);
    Ok(entries
        .iter()
        .map(catalog_entry_to_session_summary)
        .collect())
}

/// List all sessions across all projects
fn list_all_sessions() -> std::io::Result<Vec<SessionMetaWithProject>> {
    let scan = catalog_scan_in_root(&NativeSessionManager::sessions_root())?;
    let active = active_catalog_location(&scan.entries);
    list_all_sessions_in_root(&NativeSessionManager::sessions_root(), active.as_ref())
}

fn list_all_sessions_in_root(
    sessions_root: &std::path::Path,
    active: Option<&jeikcode_capabilities::session::CatalogLocation>,
) -> std::io::Result<Vec<SessionMetaWithProject>> {
    let mut entries: Vec<_> = catalog_scan_in_root(sessions_root)?
        .entries
        .into_iter()
        .filter(|entry| catalog_entry_is_visible(sessions_root, entry, active))
        .collect();
    NativeSessionManager::collapse_fork_lineages(&mut entries);
    // Bound snapshot hydration to the same newest-50 surface the API returns.
    entries.truncate(50);
    crate::legacy_convert::repair_catalog_names_for_display_in_root(sessions_root, &mut entries);
    Ok(entries.iter().map(catalog_entry_with_project).collect())
}

/// Resolve a (possibly short) session id to its full record by scanning bucket
/// directory ENTRIES. The filename is `<id>.json`, so we match on the name and
/// parse only the ONE file that matches — cheap, and UNCAPPED (unlike
/// `/sessions`, which truncates to 50 across all projects and so can't locate an
/// older session). Prefers an exact id match; otherwise the most-recent prefix
/// match. `project_hash` is the physical bucket the file lives in.
///
/// Split from `resolve_session_by_id` so the scan can be unit-tested against a
/// temp root without touching the real sessions directory.
fn resolve_session_in_root(
    sessions_root: &std::path::Path,
    id_prefix: &str,
) -> std::io::Result<Option<SessionMetaWithProject>> {
    if id_prefix.is_empty() {
        return Ok(None);
    }
    catalog_scan_in_root(sessions_root)?
        .find(id_prefix)
        .map(|entry| entry.as_ref().map(catalog_entry_with_project))
        .map_err(std::io::Error::from)
}

pub(crate) fn resolve_session_by_id(
    id_prefix: &str,
) -> std::io::Result<Option<SessionMetaWithProject>> {
    resolve_session_in_root(&NativeSessionManager::sessions_root(), id_prefix)
}

// ============== HTTP Handlers ==============

/// Health check response
#[derive(Debug, Serialize)]
pub struct HealthResponse {
    pub status: &'static str,
    pub version: &'static str,
    pub service: &'static str,
    pub binary_hash: &'static str,
    pub instance_id: String,
}

fn executable_sha256() -> &'static str {
    static HASH: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    HASH.get_or_init(|| {
        use sha2::{Digest, Sha256};

        std::env::current_exe()
            .and_then(std::fs::read)
            .map(|bytes| format!("{:x}", Sha256::digest(bytes)))
            .unwrap_or_else(|_| "unknown".to_string())
    })
}

/// GET /health - Health check endpoint
async fn health(State(state): State<AppState>) -> impl IntoResponse {
    Json(HealthResponse {
        status: "ok",
        version: env!("CARGO_PKG_VERSION"),
        service: "jeikcode-daemon",
        binary_hash: executable_sha256(),
        instance_id: state.daemon_instance_id.to_string(),
    })
}

/// Webui index route with token → cookie handoff (and SPA-visible bootstrap).
///
/// `/webui` / `jeikcode serve` open `http://host:port/?token=<uuid>`.
///
/// Previously we 302'd immediately after setting an HttpOnly cookie, so the
/// SPA never saw the token and relied on cookie-only auth. That works on
/// local loopback browsers, but remote LAN clients (phones, other PCs,
/// in-app WebViews) often fail to attach the cookie on subsequent API/SSE
/// calls — the UI loads (static assets are public) while `/chat` and `/live`
/// 401, leaving a blinking cursor with no response.
///
/// Current handoff:
/// 1. Set HttpOnly cookie (`SameSite=Lax` — more reliable than Strict for
///    top-level opens from chat apps / QR scanners on LAN).
/// 2. Serve `index.html` **with** `?token=` still present so the SPA can
///    copy it into `sessionStorage` + `Authorization: Bearer` (and then
///    `history.replaceState` to strip the address bar — CWE-598 mitigation
///    still applies client-side).
///
/// Auth accepts cookie **or** Bearer (see `require_webui_token`).
///
/// `Secure` is intentionally omitted: the webui is plain HTTP on
/// localhost/LAN, where a `Secure` cookie would never be sent.
async fn serve_webui_index(
    State(state): State<AppState>,
    uri: axum::http::Uri,
) -> axum::response::Response {
    if state.is_token_enforced() {
        if let Some(query) = uri.query() {
            if let Some(token) = first_query_value(query, "token") {
                if !token.is_empty() && state.webui_tokens.is_valid(&token) {
                    // SameSite=Lax: set on top-level navigations (QR / shared
                    // link / chat app open) and sent on same-site fetches.
                    // Strict blocked some in-app WebView → LAN flows.
                    let cookie = format!(
                        "{}={}; Path=/; HttpOnly; SameSite=Lax",
                        state.webui_cookie_name, token
                    );
                    let mut response = webui::serve_webui(uri).await;
                    if let Ok(value) = HeaderValue::from_str(&cookie) {
                        response.headers_mut().insert(header::SET_COOKIE, value);
                    }
                    return response;
                }
            }
        }
    }
    webui::serve_webui(uri).await
}

/// First value for `key` in a raw `a=b&c=d` query string. Returns the raw
/// (still percent-encoded) value; the webui token is a hex UUID so no
/// decoding is needed.
fn first_query_value(query: &str, key: &str) -> Option<String> {
    query.split('&').find_map(|pair| {
        let mut it = pair.splitn(2, '=');
        match (it.next(), it.next()) {
            (Some(k), Some(v)) if k == key => Some(v.to_string()),
            _ => None,
        }
    })
}

/// Drop every `key=…` pair from a raw query string, preserving the rest
/// verbatim. Only used in unit tests (SPA strips `token` client-side after
/// capture; see webui `captureWebuiToken`).
#[cfg(test)]
fn strip_query_key(query: &str, key: &str) -> String {
    query
        .split('&')
        .filter(|pair| pair.split('=').next().unwrap_or("") != key)
        .collect::<Vec<_>>()
        .join("&")
}

/// POST /shutdown - Trigger graceful shutdown via HTTP (R7.1, R7.2)
async fn shutdown_handler(State(state): State<AppState>) -> impl IntoResponse {
    state.shutdown_tx.send(true).ok();
    Json(serde_json::json!({"success": true}))
}

/// Current project state plus the physical session-bucket hash for the
/// working directory. The webui uses `project_hash` — NOT the mutable
/// `working_dir` string — to decide which sessions belong to this project,
/// so it must be the same hash the session store files them under.
#[derive(Debug, Serialize)]
struct ProjectStateResponse {
    working_dir: PathBuf,
    #[serde(skip_serializing_if = "Option::is_none")]
    previous_dir: Option<PathBuf>,
    recent_dirs: Vec<PathBuf>,
    name: String,
    project_hash: String,
}

/// GET /project - Get current project state
async fn get_project_state(State(state): State<AppState>) -> impl IntoResponse {
    let state = state.project.read().await;
    Json(ProjectStateResponse {
        working_dir: state.working_dir.clone(),
        previous_dir: state.previous_dir.clone(),
        recent_dirs: state.recent_dirs.clone(),
        name: state.name.clone(),
        project_hash: hash_path(&state.working_dir),
    })
}

pub(crate) fn update_project_state(project: &mut ProjectState, new_path: &std::path::Path) {
    let new_path = jeikcode_capabilities::pathnorm::strip_verbatim_path(new_path);
    let new_path = normalize_working_dir_case(new_path);
    let old_dir = project.working_dir.clone();
    if old_dir != new_path {
        project.previous_dir = Some(old_dir);
        project.working_dir = new_path.clone();
        project.name = new_path
            .file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_else(|| "project".to_string());

        let new_key = jeikcode_capabilities::pathnorm::path_case_key(&new_path);
        project
            .recent_dirs
            .retain(|d| jeikcode_capabilities::pathnorm::path_case_key(d) != new_key);
        project.recent_dirs.insert(0, new_path);
        project.recent_dirs.truncate(5);
    }
}

/// POST /cd - Change working directory (like /cd command)
async fn change_dir(
    State(state): State<AppState>,
    axum::Extension(client_mode): axum::Extension<SessionMode>,
    Json(req): Json<ChangeDirRequest>,
) -> impl IntoResponse {
    let state_clone = state.clone();
    daemon_scope(&state, None, client_mode, || async move {
        let state = state_clone;
        let mut project = state.project.write().await;

        // Handle "-" to go back to previous directory
        let new_path = if req.path == "-" {
            match &project.previous_dir {
                Some(prev) => prev.clone(),
                None => {
                    return Json(ChangeDirResponse {
                        success: false,
                        message: "No previous directory to go back to".to_string(),
                        current_dir: project.working_dir.clone(),
                        project_hash: hash_path(&project.working_dir),
                    });
                }
            }
        } else {
            // Expand ~ and make absolute
            let expanded = if req.path.starts_with('~') {
                jeikcode_config::util::real_home_dir()
                    .map(|h| {
                        h.join(
                            req.path
                                .strip_prefix('~')
                                .unwrap_or("")
                                .trim_start_matches('/'),
                        )
                    })
                    .unwrap_or_else(|| PathBuf::from(&req.path))
            } else {
                PathBuf::from(&req.path)
            };

            let resolved = if expanded.is_absolute() {
                expanded
            } else {
                project.working_dir.join(&expanded)
            };

            // Check if directory exists
            if !resolved.exists() {
                return Json(ChangeDirResponse {
                    success: false,
                    message: format!("Directory does not exist: {}", resolved.display()),
                    current_dir: project.working_dir.clone(),
                    project_hash: hash_path(&project.working_dir),
                });
            }

            if !resolved.is_dir() {
                return Json(ChangeDirResponse {
                    success: false,
                    message: format!("Not a directory: {}", resolved.display()),
                    current_dir: project.working_dir.clone(),
                    project_hash: hash_path(&project.working_dir),
                });
            }

            resolved
        };

        // Strip any `\\?\` verbatim prefix before it reaches working_dir /
        // session cwd / hash, so a path that round-tripped through a
        // `canonicalize()`-based client still groups with the plain TUI form.
        let new_path = jeikcode_capabilities::pathnorm::strip_verbatim_path(&new_path);
        // Fold case to the on-disk truth (Windows, bucket-safe) so a `/cd` with a
        // differently-cased path doesn't leave the footer/new sessions drifting.
        let new_path = normalize_working_dir_case(new_path);

        // When a native live runtime is attached, it is the working-directory
        // owner. Reject the HTTP mutation if the runtime cannot accept the same
        // transition; otherwise the UI state and the executing runtime diverge.
        if let Ok(previous_binding) = crate::native_live::binding() {
            if let Err(error) = crate::native_live::change_directory(new_path.clone()).await {
                return Json(ChangeDirResponse {
                    success: false,
                    message: format!("Runtime rejected directory change: {error:?}"),
                    current_dir: project.working_dir.clone(),
                    project_hash: hash_path(&project.working_dir),
                });
            }
            if let Some(session_id) = req
                .session_id
                .as_deref()
                .map(str::trim)
                .filter(|session_id| !session_id.is_empty())
            {
                if let Err(error) =
                    crate::live_api::live_switch_session(session_id.to_string()).await
                {
                    let rollback_error = match crate::native_live::change_directory(
                        previous_binding.working_dir.clone(),
                    )
                    .await
                    {
                        Ok(_) => crate::live_api::live_switch_session(
                            previous_binding.session_id.clone(),
                        )
                        .await
                        .err()
                        .map(|error| format!("session restore failed: {error:?}")),
                        Err(error) => Some(format!("directory restore failed: {error:?}")),
                    };
                    return Json(ChangeDirResponse {
                        success: false,
                        message: match rollback_error {
                            Some(rollback) => format!(
                                "Runtime rejected session switch: {error:?}; rollback failed: {rollback}"
                            ),
                            None => format!("Runtime rejected session switch: {error:?}"),
                        },
                        current_dir: project.working_dir.clone(),
                        project_hash: hash_path(&project.working_dir),
                    });
                }
            }
        }

        // Update state
        update_project_state(&mut project, &new_path);

        // Persist to config only when explicitly requested. The live in-memory
        // state above is always updated (so a webui switch survives refresh);
        // rewriting the configured default is gated behind `set_default`.
        if req.set_default {
            let _ = jeikcode_config::ConfigStore::default_store().update(|config| {
                config.default_workdir = Some(new_path.to_string_lossy().to_string());
                Ok(())
            });
        }

        let hash = hash_path(&new_path);
        state.telemetry.track(Event::UseCommand {
            type_: "cd".into(),
            success: Some(true),
            error_kind: None,
            error_data: None,
        });

        // 同步 daemon 项目视图；已绑定 runtime 已在上方接受原生目录切换。
        crate::live_api::live_set_working_dir(new_path.clone());
        // MCP registry is loaded per-request based on working_dir, no need to reload here.

        Json(ChangeDirResponse {
            success: true,
            message: format!("Changed to {}", new_path.display()),
            current_dir: new_path,
            project_hash: hash,
        })
    })
    .await
}

/// GET /projects - List all projects (historical, from sessions directory)
async fn get_projects() -> impl IntoResponse {
    match run_session_catalog_io(list_projects).await {
        Ok(projects) => Json(projects).into_response(),
        Err(e) => {
            let msg = format!("Failed to list projects: {}", e);
            (StatusCode::INTERNAL_SERVER_ERROR, Json(msg)).into_response()
        }
    }
}

/// GET /projects/:hash/sessions - List sessions for a project
async fn get_project_sessions(Path(hash): Path<String>) -> impl IntoResponse {
    match run_session_catalog_io(move || list_sessions(&hash)).await {
        Ok(sessions) => Json(sessions).into_response(),
        Err(e) => {
            let msg = format!("Failed to list sessions: {}", e);
            (StatusCode::INTERNAL_SERVER_ERROR, Json(msg)).into_response()
        }
    }
}

/// GET /sessions/resolve/:id - Resolve a (short or full) session id to its full
/// record across all projects. Backs the webui's URL-restore, which carries
/// only a short id and must find which project bucket owns it without the
/// 50-session cap of `/sessions`.
async fn resolve_session(Path(id): Path<String>) -> impl IntoResponse {
    match resolve_session_by_id(&id) {
        Ok(Some(s)) => Json(s).into_response(),
        Ok(None) => (StatusCode::NOT_FOUND, Json("Session not found")).into_response(),
        Err(e) => {
            let msg = format!("Failed to resolve session: {}", e);
            (StatusCode::INTERNAL_SERVER_ERROR, Json(msg)).into_response()
        }
    }
}

/// POST /sessions/:id/seen — 广播「该会话已被用户查看」。
///
/// 侧栏的绿色「刚完成」徽标由全局 `activity` 广播点亮；熄灭也必须走同一条
/// 全局总线，否则只清当前标签页会在其它标签页 / 浏览器上留下幽灵勾。
/// 本接口不读写会话数据，只发一条跨实例失效信号。
async fn mark_session_seen(Path(id): Path<String>) -> impl IntoResponse {
    let session_id = id.trim();
    if session_id.is_empty() {
        return (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({ "success": false, "error": "session_id is required" })),
        )
            .into_response();
    }
    publish_global(GlobalWireEvent::SessionSeen {
        session_id: session_id.to_string(),
    });
    Json(serde_json::json!({ "success": true })).into_response()
}

/// GET /sessions/by-working-dir?working_dir=/path - List sessions for an explicit working directory
async fn get_sessions_by_working_dir(
    Query(query): Query<SessionsByWorkingDirQuery>,
) -> impl IntoResponse {
    let hash = hash_path(&query.working_dir);
    let list_hash = hash.clone();
    match run_session_catalog_io(move || list_sessions(&list_hash)).await {
        Ok(sessions) => {
            let sessions: Vec<SessionMetaWithProject> = sessions
                .into_iter()
                .map(|meta| SessionMetaWithProject {
                    project_hash: hash.clone(),
                    meta,
                })
                .collect();
            Json(sessions).into_response()
        }
        Err(e) => {
            let msg = format!("Failed to list sessions: {}", e);
            (StatusCode::INTERNAL_SERVER_ERROR, Json(msg)).into_response()
        }
    }
}

#[derive(Debug, Serialize)]
struct SessionFreshness {
    /// Sum of snapshot, jsonl, and UI presentation file sizes.
    bytes: u64,
    /// Newest mtime among those files, in unix milliseconds.
    mtime_ms: u64,
    /// True while this session has a live or `/chat` turn.
    running: bool,
}

fn stat_session_file(path: &std::path::Path, bytes: &mut u64, mtime_ms: &mut u64) {
    let Ok(meta) = std::fs::metadata(path) else {
        return;
    };
    *bytes = bytes.saturating_add(meta.len());
    let Ok(modified) = meta.modified() else {
        return;
    };
    let Ok(elapsed) = modified.duration_since(std::time::UNIX_EPOCH) else {
        return;
    };
    let ms = u64::try_from(elapsed.as_millis()).unwrap_or(u64::MAX);
    *mtime_ms = (*mtime_ms).max(ms);
}

/// Stat the transcript files only. Does not read or parse message bodies.
fn session_disk_freshness(project_hash: &str, session_id: &str) -> SessionFreshness {
    let manager =
        NativeSessionManager::with_root(NativeSessionManager::sessions_root().join(project_hash));
    let mut bytes = 0u64;
    let mut mtime_ms = 0u64;
    for path in [
        manager.snapshot_path(session_id),
        manager.jsonl_path(session_id),
        manager.presentation_path(session_id),
    ]
    .into_iter()
    .flatten()
    {
        stat_session_file(&path, &mut bytes, &mut mtime_ms);
    }
    SessionFreshness {
        bytes,
        mtime_ms,
        running: false,
    }
}

/// GET /projects/:hash/sessions/:id/freshness
///
/// Cheap catch-up probe: file size and mtime only. The WebUI reads the
/// transcript body only when this signature changes.
async fn get_session_freshness(
    State(state): State<AppState>,
    Path((hash, id)): Path<(String, String)>,
) -> impl IntoResponse {
    let mut freshness = session_disk_freshness(&hash, &id);
    freshness.running = state
        .active_chats
        .active_session_ids()
        .await
        .iter()
        .any(|sid| sid == &id)
        || crate::native_live::live_running_session_id().as_deref() == Some(id.as_str())
        || jeikcode_coding::session_runtime_registry::SessionRuntimeRegistry::global()
            .live_turn_session_ids()
            .iter()
            .any(|sid| sid == &id);
    Json(freshness)
}

const SESSION_DETAIL_WARN_BYTES: usize = 8 * 1024 * 1024;

/// Stable, dependency-free ETag for a JSON response body.
fn response_etag(bytes: &[u8]) -> String {
    let mut hash = 0xcbf29ce484222325u64;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("\"{hash:016x}\"")
}

fn log_response_size(route: &str, bytes: usize) {
    tracing::debug!(target: "jeikcode::http", route, bytes, "response_size");
    if bytes > SESSION_DETAIL_WARN_BYTES {
        tracing::warn!(target: "jeikcode::http", route, bytes, "large_response_body");
    }
}

fn session_detail_response(headers: &HeaderMap, detail: SessionDetail) -> axum::response::Response {
    let body = match serde_json::to_vec(&detail) {
        Ok(body) => body,
        Err(error) => {
            return (StatusCode::INTERNAL_SERVER_ERROR, error.to_string()).into_response()
        }
    };
    let etag = response_etag(&body);
    let not_modified = headers
        .get(header::IF_NONE_MATCH)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| {
            value.split(',').any(|candidate| {
                let candidate = candidate.trim();
                candidate == "*"
                    || candidate == etag
                    || candidate
                        .strip_prefix("W/")
                        .is_some_and(|weak| weak == etag)
            })
        });
    if not_modified {
        let mut response = StatusCode::NOT_MODIFIED.into_response();
        if let Ok(value) = HeaderValue::from_str(&etag) {
            response.headers_mut().insert(header::ETAG, value);
        }
        return response;
    }

    log_response_size("session_detail", body.len());
    let mut response = axum::response::Response::new(axum::body::Body::from(body));
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("application/json"),
    );
    if let Ok(value) = HeaderValue::from_str(&etag) {
        response.headers_mut().insert(header::ETAG, value);
    }
    response
}

/// GET /projects/:hash/sessions/:id - Get session detail
async fn get_session_detail(
    State(state): State<AppState>,
    Path((hash, id)): Path<(String, String)>,
    Query(query): Query<SessionDetailQuery>,
    headers: HeaderMap,
) -> impl IntoResponse {
    match crate::legacy_convert::load_catalog_session_view_in_project(&hash, &id) {
        Ok(Some(session)) => {
            let _ = crate::native_live::take_session_draft(&id);
            let turn_running = state
                .active_chats
                .active_session_ids()
                .await
                .iter()
                .any(|sid| sid == &id)
                || crate::native_live::live_running_session_id().as_deref() == Some(id.as_str())
                || jeikcode_coding::session_runtime_registry::SessionRuntimeRegistry::global()
                    .live_turn_session_ids()
                    .iter()
                    .any(|sid| sid == &id);
            let display_manager =
                NativeSessionManager::with_root(NativeSessionManager::sessions_root().join(&hash));
            let snapshot_last_turn = session
                .meta
                .turn_stats
                .iter()
                .filter(|stat| stat.position_valid)
                .map(|stat| stat.turn_id)
                .max()
                .unwrap_or(0);
            let current_operation = if turn_running {
                state
                    .active_chats
                    .admitted_user_for_session(&id)
                    .await
                    .and_then(|user| user.client_input_id)
            } else {
                None
            };
            // First-paint `tail=N`: use the v4 offset index to seek directly into
            // the tail. Only for an idle, settled v4 session; running sessions need
            // the snapshot-tail overlay and keep the full read path.
            let tail_view = if query.offset.is_none() && query.after_seq.is_none() {
                query.tail.and_then(|tail| {
                    read_display_tail_view(
                        &display_manager,
                        &session,
                        tail,
                        current_operation.as_deref(),
                        turn_running,
                        snapshot_last_turn,
                    )
                })
            } else {
                None
            };
            // Prefer the append-only display transcript: it is never compacted,
            // so it keeps every turn, image, reasoning block and tool card. A log
            // that is behind the snapshot (failed write / old session) falls back
            // to the snapshot projection and is backfilled below.
            let display = if tail_view.is_some() {
                None
            } else {
                read_display_cached(&display_manager, &session.meta.id).filter(|(meta, records)| {
                    if meta.v == jeikcode_capabilities::session::DISPLAY_VERSION {
                        // v4 normal path: exact prompt-identity coverage; no text
                        // reconciliation. A gap (including a dropped tail whose
                        // turn id was reused after a rewind) falls through to the
                        // one-time canonical rebuild below.
                        meta.complete
                            && v4_display_covers_completed_user_turns(
                                meta,
                                &display_record_ids(records),
                                &session.snapshot.messages,
                                &session.meta.turn_stats,
                                snapshot_last_turn,
                            )
                    } else {
                        // v3 is migration input only.
                        meta.last_turn_id >= snapshot_last_turn
                            && display_covers_completed_user_rows(
                                records,
                                &session.snapshot.messages,
                                &session.meta.turn_stats,
                                snapshot_last_turn,
                            )
                    }
                })
            };
            let display_is_v4 = display
                .as_ref()
                .is_some_and(|(meta, _)| meta.v == jeikcode_capabilities::session::DISPLAY_VERSION);
            let (turns, message_count, offset, messages, pinned_user_index) = if let Some(view) =
                tail_view
            {
                (
                    view.turns,
                    view.message_count,
                    view.offset,
                    view.messages,
                    view.pinned_user_index,
                )
            } else if let Some((meta, records)) = display {
                let elapsed = display_turn_elapsed_overrides(&records, &session.meta.turn_stats);
                // A hook-created log begins at the first user turn; a backfill
                // already contains the session-start prefix. Prepend the prefix
                // only in the former case so indices stay stable across upgrades.
                let already_prefixed = meta.backfilled
                    || records.first().is_some_and(|record| {
                        record.role.eq_ignore_ascii_case("system")
                            || (record.role.eq_ignore_ascii_case("user") && record.synthetic)
                    });
                let prefix = if already_prefixed {
                    Vec::new()
                } else {
                    display_prefix_messages(&session)
                };
                let prefix_len = prefix.len();

                // 1. 全会话大纲零开销提取：直接从 DisplayRecord 提炼，确保右栏大纲与 "(13 questions left)" 100% 精确，
                // 并且无需将整仓几千行无用工具行堆分配转化为 MessageInfo。
                let mut turns = session_user_outline(&prefix);
                let record_turns = session_records_user_outline(&records, prefix_len);
                let turns_offset = turns.len();
                turns.extend(record_turns.into_iter().map(|mut t| {
                    t.ordinal += turns_offset;
                    t
                }));

                let mut full_messages = prefix;
                full_messages.extend(records.iter().enumerate().map(|(index, record)| {
                    let mut message = display_record_to_message_info(record);
                    if let Some(duration) = elapsed.get(&index) {
                        message.elapsed_ms = Some(*duration);
                    }
                    message
                }));
                let snapshot_ids: std::collections::HashSet<&str> = session
                    .snapshot
                    .messages
                    .iter()
                    .filter_map(|message| message.id.as_deref())
                    .collect();
                mark_display_only_archive_rows(
                    records.as_slice(),
                    &mut full_messages[prefix_len..],
                    &snapshot_ids,
                    snapshot_last_turn,
                    !turn_running && meta.last_turn_id <= snapshot_last_turn,
                );
                // 展示日志在 turn_complete 才落盘。运行中/刚停止/硬杀死的尾巴只存在于
                // inflight 快照：按最后一条共享 id 之后整段投影，画布与大纲共用
                // 同一套绝对下标，刷新后与直播看到的完全一致。
                // The append is idempotent (only rows after the last shared id), so
                // a fully settled v4 log is untouched; an idle crashed turn (no
                // completed `turn_stat`, so `v4_display_covers...` cannot see it)
                // still gets its checkpointed tail back.
                append_snapshot_tail(
                    &mut full_messages,
                    &mut turns,
                    &session.snapshot.messages,
                    std::path::Path::new(&session.meta.working_dir),
                );
                if !display_is_v4 && !turn_running && !full_messages.is_empty() {
                    // Lazy v3 -> v4 migration: the current merged projection is
                    // complete enough to become the v4 source of truth. The next
                    // read never re-enters this branch.
                    let records: Vec<_> = full_messages
                        .iter()
                        .enumerate()
                        .map(|(index, message)| {
                            display_record_from_message_info(&session.meta.id, index, message)
                        })
                        .collect();
                    let _ = display_manager.write_display_backfill(
                        &session.meta.id,
                        &records,
                        snapshot_last_turn,
                    );
                }
                // Durable admitted inputs (prompt/steer) that the kernel has
                // not folded/persisted yet: show them now, scoped to this turn.
                append_pending_inputs(
                    &mut full_messages,
                    &mut turns,
                    &session.meta.id,
                    current_operation.as_deref(),
                    std::path::Path::new(&session.meta.working_dir),
                    0,
                );
                annotate_client_input_ids(&mut full_messages, &session.meta.id);
                append_interrupted_partial(&mut full_messages, &session.meta.id, turn_running);
                attach_display_images(
                    &mut full_messages,
                    std::path::Path::new(&session.meta.working_dir),
                    &session.meta.id,
                );
                repair_display_clock(&mut full_messages);
                let (message_count, offset, window, pinned) =
                    if let Some(after_seq) = query.after_seq {
                        take_session_after(full_messages, after_seq)
                    } else {
                        take_session_page(full_messages, &query)
                    };
                (turns, message_count, offset, window, pinned)
            } else {
                // v4 missing/incomplete: one-time migration or explicit-mutation
                // rebuild. This branch writes v4 before returning; a normal
                // settled session never re-enters it.
                let mut messages = match merge_catalog_session_messages_for_display(&session) {
                    Ok(messages) => messages,
                    Err(error) => {
                        let msg = format!("Failed to load session: {error}");
                        return (StatusCode::NOT_FOUND, Json(msg)).into_response();
                    }
                };
                // 旧快照可能没有 message id（功能引入前写入）：补确定性 id，
                // 保证新契约下的右栏锚点 / 编辑 / 删除不退化。
                mint_legacy_message_ids(&mut messages);
                // Compaction drains model context from the snapshot, but the raw
                // transcript is append-only. Rebuild the pre-compaction display
                // prefix from it so the question rail and canvas never lose turns
                // after a refresh. Presentation entries already merged into the
                // list are display-only rows: the splice keeps any that are not
                // covered by the rebuilt transcript.
                if let Some(anchor) = messages.iter().position(|message| {
                    message.role.eq_ignore_ascii_case("user")
                        && message.synthetic
                        && jeikcode_capabilities::compaction::is_compaction_anchor_text(
                            &message.content,
                        )
                }) {
                    if let Some(turns) = load_display_transcript(&hash, &session.meta.id) {
                        let boundary = messages[anchor + 1..].iter().find(|message| {
                            message.role.eq_ignore_ascii_case("user") && !message.synthetic
                        });
                        let prefix = display_prefix_from_transcript(
                            &turns,
                            boundary.and_then(|message| message.created_at),
                            boundary.map(|message| message.content.as_str()),
                        );
                        messages = splice_compacted_display(messages, prefix);
                    }
                }
                // One-time upgrade path for sessions created before the display
                // log existed. Only settled sessions are materialized so a live
                // turn is never frozen into the log half-way. If an existing log
                // is already beyond the readable ceiling, do not rewrite it on
                // every read (the next read would fail the same way).
                let display_too_large = display_manager
                    .display_path(&session.meta.id)
                    .ok()
                    .and_then(|path| std::fs::metadata(path).ok())
                    .is_some_and(|metadata| {
                        metadata.len()
                            > jeikcode_capabilities::session::display::MAX_DISPLAY_READ_BYTES as u64
                    });
                if !turn_running && !messages.is_empty() && !display_too_large {
                    let records: Vec<_> = messages
                        .iter()
                        .enumerate()
                        .map(|(index, message)| {
                            display_record_from_message_info(&session.meta.id, index, message)
                        })
                        .collect();
                    let _ = display_manager.write_display_backfill(
                        &session.meta.id,
                        &records,
                        snapshot_last_turn,
                    );
                }
                let mut turns = session_user_outline(&messages);
                append_pending_inputs(
                    &mut messages,
                    &mut turns,
                    &id,
                    current_operation.as_deref(),
                    std::path::Path::new(&session.meta.working_dir),
                    0,
                );
                annotate_client_input_ids(&mut messages, &id);
                append_interrupted_partial(&mut messages, &id, turn_running);
                repair_display_clock(&mut messages);
                let (message_count, offset, messages, pinned_user_index) =
                    if let Some(after_seq) = query.after_seq {
                        take_session_after(messages, after_seq)
                    } else {
                        take_session_page(messages, &query)
                    };
                (turns, message_count, offset, messages, pinned_user_index)
            };
            let token_usage = session_token_usage_from_session(&session.meta, &session.snapshot);
            let (todos, todos_revision) =
                if let Some(board) = jeikcode_capabilities::tools::read_todo_board(&id) {
                    if jeikcode_capabilities::tools::list_fully_completed(&board.items)
                        && !turn_running
                    {
                        let closed =
                            jeikcode_capabilities::tools::close_todo_board_if_complete(&id);
                        (
                            Vec::new(),
                            closed.map(|board| board.revision).unwrap_or(board.revision),
                        )
                    } else {
                        let revision = board.revision;
                        (board.items, revision)
                    }
                } else {
                    (Vec::new(), 0)
                };
            let cursor = SessionCursor {
                oldest_seq: messages.iter().find_map(|message| message.seq),
                total: message_count,
            };
            // 大纲单取：右栏唤醒时只需要 turns（每轮提问的标签/序号/seq），
            // 正文、工具输出、图片一律不传。弱网下把一次大纲刷新从几十 KB
            // 降到几百字节；`message_count` / `cursor` 仍然保留，客户端可以
            // 用它做“是否需要拉正文”的对账。
            let messages = if query.turns_only.unwrap_or(false) {
                Vec::new()
            } else {
                messages
            };
            let detail = SessionDetail {
                id: session.meta.id,
                name: session.meta.name,
                working_dir: PathBuf::from(session.meta.working_dir),
                created_at: u64::try_from(session.meta.created_at.max(0)).unwrap_or(0),
                updated_at: u64::try_from(session.meta.updated_at.max(0)).unwrap_or(0),
                message_count,
                revision: session.snapshot.cache_epoch,
                caps: session_capabilities(),
                cursor,
                offset,
                pinned_user_index,
                turns,
                input_cursor: jeikcode_capabilities::session::inputs::cursor_global(&id),
                messages,
                preferred_model: session.meta.preferred_model.clone().or_else(|| {
                    session
                        .meta
                        .turn_stats
                        .iter()
                        .rev()
                        .find_map(|s| s.model_usage.first().map(|m| m.provider_id.clone()))
                }),
                approval_mode: Some(live_api::live_display_approval_mode_wire(
                    &id,
                    session.meta.approval_mode.as_deref(),
                )),
                reasoning_effort: session.meta.reasoning_effort.clone(),
                thinking_budget: session.meta.thinking_budget,
                token_usage,
                origin: session.meta.origin,
                todos,
                todos_revision,
            };
            session_detail_response(&headers, detail)
        }
        Ok(None) if crate::native_live::is_session_draft(&id) => {
            // OpenCode draft: allocated via POST /sessions but not catalog-persisted yet.
            let working_dir = crate::native_live::session_draft_working_dir(&id)
                .unwrap_or_else(|| PathBuf::from("."));
            let detail = SessionDetail {
                cursor: SessionCursor {
                    oldest_seq: None,
                    total: 0,
                },
                id: id.clone(),
                name: format!("session-{id}"),
                working_dir,
                created_at: 0,
                updated_at: 0,
                message_count: 0,
                revision: 0,
                caps: session_capabilities(),
                offset: 0,
                pinned_user_index: None,
                turns: Vec::new(),
                input_cursor: jeikcode_capabilities::session::inputs::cursor_global(&id),
                messages: Vec::new(),
                preferred_model: None,
                approval_mode: Some(
                    live_api::live_session_approval_mode(Some(&id))
                        .wire()
                        .to_string(),
                ),
                reasoning_effort: None,
                thinking_budget: None,
                token_usage: None,
                origin: jeikcode_capabilities::session::SessionOrigin::Manual,
                todos: Vec::new(),
                todos_revision: 0,
            };
            session_detail_response(&headers, detail)
        }
        Ok(None) => (StatusCode::NOT_FOUND, Json("Session not found")).into_response(),
        Err(e) => {
            let msg = format!("Failed to load session: {}", e);
            (StatusCode::NOT_FOUND, Json(msg)).into_response()
        }
    }
}

/// GET /projects/:hash/sessions/:id/lineage - Get conversation fork lineage and child branches
async fn get_session_lineage(Path((hash, id)): Path<(String, String)>) -> impl IntoResponse {
    if !valid_project_bucket(&hash) {
        return (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({
                "error": "INVALID_PROJECT",
                "message": format!("Invalid project identifier: {hash}")
            })),
        )
            .into_response();
    }
    let sessions_root = NativeSessionManager::sessions_root();
    let manager = NativeSessionManager::with_root(sessions_root.join(&hash));
    match manager.session_lineage(&id) {
        Ok(Some(lineage)) => (StatusCode::OK, Json(lineage)).into_response(),
        Ok(None) => (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({
                "error": "SESSION_NOT_FOUND",
                "message": format!("Session '{id}' was not found in project '{hash}'")
            })),
        )
            .into_response(),
        Err(error) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({
                "error": "STORAGE_ERROR",
                "message": format!("{error}")
            })),
        )
            .into_response(),
    }
}

/// Display-only image sidecar: the ORIGINAL images of VL-preprocessed user messages.
///
/// When the active model lacks vision, the runtime's VL seam strips the image from the
/// conversation (only the text caption reaches the model + the persisted snapshot). The
/// image must NOT go back into the conversation — the kernel counts every stored image as
/// ~1600 tokens (`Message::estimate_tokens`) and the adapter would re-send it — so we
/// stash the originals HERE, out of band, and re-attach them for DISPLAY only on load.
/// Ordered: one entry per VL-preprocessed submission, matched to the VL-marker user
/// messages in order (each such submission produces exactly one).
#[derive(Debug, Default, serde::Serialize, serde::Deserialize)]
pub(crate) struct ImageSidecar {
    #[serde(default)]
    pub sets: Vec<Vec<ImageData>>,
}

fn image_sidecar_path(working_dir: &std::path::Path, session_id: &str) -> PathBuf {
    jeikcode_capabilities::session::SessionManager::for_project(working_dir)
        .root()
        .join(format!("{session_id}.images.json"))
}

/// Append a VL-preprocessed message's ORIGINAL images to the session's display-only
/// sidecar. Best-effort: a failure just means the image later shows as the "missing"
/// placeholder — it never blocks the turn and never touches the model context.
pub(crate) fn append_display_images(
    working_dir: &std::path::Path,
    session_id: &str,
    images: Vec<ImageData>,
) {
    if images.is_empty() {
        return;
    }
    let path = image_sidecar_path(working_dir, session_id);
    let mut sidecar: ImageSidecar = std::fs::read(&path)
        .ok()
        .and_then(|bytes| serde_json::from_slice(&bytes).ok())
        .unwrap_or_default();
    sidecar.sets.push(images);
    if let Ok(bytes) = serde_json::to_vec(&sidecar) {
        let _ = std::fs::write(&path, bytes);
    }
}

/// Re-attach display-only sidecar images to the VL-preprocessed user messages that
/// currently render the "missing image" placeholder, IN ORDER. Real (vision-model)
/// images and non-user messages are left untouched.
pub(crate) fn attach_display_images(
    messages: &mut [MessageInfo],
    working_dir: &std::path::Path,
    session_id: &str,
) {
    let sets = std::fs::read(image_sidecar_path(working_dir, session_id))
        .ok()
        .and_then(|bytes| serde_json::from_slice::<ImageSidecar>(&bytes).ok())
        .map(|sidecar| sidecar.sets)
        .unwrap_or_default();
    attach_image_sets(messages, sets);
}

fn is_steer_user_message(msg: &MessageInfo) -> bool {
    msg.role == "user"
        && (msg.content.contains("[jeikcode-steer]")
            || (msg.content.contains("<user-query>") && msg.content.contains("</user-query>")))
}

fn is_visible_user_turn_start(msg: &MessageInfo) -> bool {
    msg.role == "user" && !msg.synthetic && !is_steer_user_message(msg)
}

fn is_visible_assistant_reply(msg: &MessageInfo) -> bool {
    msg.role == "assistant" && msg.internal_origin.as_deref() != Some("turn_diagnostic")
}

/// Stamp each user-turn's last assistant with the full agent-loop wall clock.
///
/// Live WebUI measures user-bubble → final answer. Kernel `MessageMeta.elapsed_ms`
/// is only the last LLM round, so a reload would otherwise shrink "用时 20min"
/// down to the last reply. Prefer persisted [`TurnStat::duration_ms`], then the
/// user/assistant `created_at` span.
pub(crate) fn stamp_turn_elapsed_on_last_assistants(
    messages: &mut [MessageInfo],
    turn_stats: &[jeikcode_capabilities::session::TurnStat],
) {
    let total_root_turns = messages
        .iter()
        .filter(|m| is_visible_user_turn_start(m))
        .count();
    let mut extra_stats = turn_stats.len().saturating_sub(total_root_turns);
    let mut i = 0usize;
    let mut turn_i = 0usize;
    while i < messages.len() {
        if !is_visible_user_turn_start(&messages[i]) {
            i += 1;
            continue;
        }
        let user_ts = messages[i].created_at;
        let mut last_asst = None;
        let mut steer_count = 0usize;
        let mut j = i + 1;
        while j < messages.len() && !is_visible_user_turn_start(&messages[j]) {
            if is_steer_user_message(&messages[j]) {
                steer_count += 1;
            }
            if is_visible_assistant_reply(&messages[j]) {
                last_asst = Some(j);
            }
            j += 1;
        }
        let consumed_extra = steer_count.min(extra_stats);
        extra_stats -= consumed_extra;
        let stats_for_turn = 1 + consumed_extra;
        if let Some(ai) = last_asst {
            let from_ts = match (user_ts, messages[ai].created_at) {
                (Some(user), Some(asst)) if asst > user => Some(asst - user),
                _ => None,
            };
            let slice_end = (turn_i + stats_for_turn).min(turn_stats.len());
            let from_stat = if turn_i < slice_end {
                let sum: u64 = turn_stats[turn_i..slice_end]
                    .iter()
                    .map(|stat| stat.duration_ms)
                    .sum();
                (sum > 0).then_some(sum)
            } else {
                None
            };
            let total = match (from_stat, from_ts) {
                (Some(stat_ms), Some(ts_ms)) if steer_count > 0 => Some(stat_ms.max(ts_ms)),
                (stat_ms, ts_ms) => stat_ms.or(ts_ms),
            };
            if let Some(total) = total {
                messages[ai].elapsed_ms = Some(total);
            }
        }
        turn_i += stats_for_turn;
        i = j;
    }
}

/// Pure matcher (see [`attach_display_images`]): replace each VL-marker user message's
/// "missing image" placeholder with the next sidecar image set, IN ORDER. Real images and
/// non-user messages are left untouched.
fn attach_image_sets(messages: &mut [MessageInfo], sets: Vec<Vec<ImageData>>) {
    if sets.is_empty() {
        return;
    }
    // The sidecar is append-only and holds ALL VL submissions, while the
    // message list may have lost the oldest placeholder rows to compaction.
    // Match the TAIL of the sidecar (newest submissions) to the surviving
    // placeholders; matching from the head would attach an old image to a
    // newer question.
    let placeholders = messages
        .iter()
        .filter(|message| {
            message.role == "user"
                && message
                    .images
                    .as_ref()
                    .is_some_and(|images| images.iter().any(|image| image.missing))
        })
        .count();
    let skip = sets.len().saturating_sub(placeholders);
    let mut next = sets.into_iter().skip(skip);
    for message in messages.iter_mut() {
        let is_missing_placeholder = message.role == "user"
            && message
                .images
                .as_ref()
                .is_some_and(|imgs| imgs.iter().any(|img| img.missing));
        if is_missing_placeholder {
            if let Some(images) = next.next() {
                if !images.is_empty() {
                    message.images = Some(images);
                }
            }
        }
    }
}

/// The display log is also read on every history page. Keep a small LRU across
/// sessions so warm-switching does not re-read + re-parse a multi-megabyte JSONL
/// per page. Both the per-entry and total budgets are bounded.
const MAX_CACHED_DISPLAY_BYTES: u64 = 64 * 1024 * 1024;
const MAX_CACHED_DISPLAY_ENTRIES: usize = 8;
const MAX_CACHED_DISPLAY_TOTAL_BYTES: u64 = 128 * 1024 * 1024;

struct DisplayLogCacheEntry {
    key: String,
    log_mtime: Option<std::time::SystemTime>,
    log_len: u64,
    meta_mtime: Option<std::time::SystemTime>,
    meta_len: u64,
    meta: jeikcode_capabilities::session::DisplayMeta,
    records: Arc<Vec<jeikcode_capabilities::session::DisplayRecord>>,
}

#[derive(Default)]
struct DisplayLogCache {
    entries: HashMap<String, DisplayLogCacheEntry>,
    order: std::collections::VecDeque<String>,
    total_bytes: u64,
}

impl DisplayLogCache {
    fn get(
        &mut self,
        key: &str,
        log_mtime: Option<std::time::SystemTime>,
        log_len: u64,
        meta_mtime: Option<std::time::SystemTime>,
        meta_len: u64,
    ) -> Option<(
        jeikcode_capabilities::session::DisplayMeta,
        Arc<Vec<jeikcode_capabilities::session::DisplayRecord>>,
    )> {
        let entry = self.entries.get(key)?;
        if entry.log_mtime != log_mtime
            || entry.log_len != log_len
            || entry.meta_mtime != meta_mtime
            || entry.meta_len != meta_len
        {
            return None;
        }
        let meta = entry.meta.clone();
        let records = entry.records.clone();
        self.order.retain(|item| item != key);
        self.order.push_back(key.to_string());
        Some((meta, records))
    }

    fn insert(&mut self, entry: DisplayLogCacheEntry) {
        let key = entry.key.clone();
        let bytes = entry.log_len.saturating_add(entry.meta_len);
        if let Some(previous) = self.entries.remove(&key) {
            self.total_bytes = self
                .total_bytes
                .saturating_sub(previous.log_len.saturating_add(previous.meta_len));
        }
        self.order.retain(|item| item != &key);
        self.order.push_back(key.clone());
        self.total_bytes = self.total_bytes.saturating_add(bytes);
        self.entries.insert(key, entry);
        while self.entries.len() > MAX_CACHED_DISPLAY_ENTRIES
            || self.total_bytes > MAX_CACHED_DISPLAY_TOTAL_BYTES
        {
            let Some(oldest) = self.order.pop_front() else {
                break;
            };
            if let Some(evicted) = self.entries.remove(&oldest) {
                self.total_bytes = self
                    .total_bytes
                    .saturating_sub(evicted.log_len.saturating_add(evicted.meta_len));
            }
        }
    }
}

fn display_log_cache() -> &'static std::sync::Mutex<DisplayLogCache> {
    static CACHE: std::sync::OnceLock<std::sync::Mutex<DisplayLogCache>> =
        std::sync::OnceLock::new();
    CACHE.get_or_init(|| std::sync::Mutex::new(DisplayLogCache::default()))
}

/// Read a complete display log with an mtime+length guarded cache. The log is
/// append-only; both the log and its meta sidecar are part of the fingerprint,
/// so a new turn (or a backfill/invalidation) misses the cache immediately.
fn read_display_cached(
    manager: &NativeSessionManager,
    id: &str,
) -> Option<(
    jeikcode_capabilities::session::DisplayMeta,
    Arc<Vec<jeikcode_capabilities::session::DisplayRecord>>,
)> {
    read_display_with_cache(manager, id, display_log_cache())
}

fn read_display_with_cache(
    manager: &NativeSessionManager,
    id: &str,
    cache: &std::sync::Mutex<DisplayLogCache>,
) -> Option<(
    jeikcode_capabilities::session::DisplayMeta,
    Arc<Vec<jeikcode_capabilities::session::DisplayRecord>>,
)> {
    let log_path = manager.display_path(id).ok()?;
    let meta_path = manager.display_meta_path(id).ok()?;
    let log_metadata = std::fs::metadata(&log_path).ok()?;
    let meta_metadata = std::fs::metadata(&meta_path).ok()?;
    let log_mtime = log_metadata.modified().ok();
    let meta_mtime = meta_metadata.modified().ok();
    let log_len = log_metadata.len();
    let meta_len = meta_metadata.len();
    let key = log_path.to_string_lossy().into_owned();

    // Do not cache an oversized log: the read itself is the memory risk.
    if log_len > MAX_CACHED_DISPLAY_BYTES {
        return manager
            .read_display(id)
            .ok()
            .flatten()
            .map(|(meta, records)| (meta, Arc::new(records)));
    }

    if let Ok(mut guard) = cache.lock() {
        if let Some(hit) = guard.get(&key, log_mtime, log_len, meta_mtime, meta_len) {
            return Some(hit);
        }
    }

    let (meta, records) = manager.read_display(id).ok().flatten()?;
    let records = Arc::new(records);
    if let Ok(mut guard) = cache.lock() {
        guard.insert(DisplayLogCacheEntry {
            key,
            log_mtime,
            log_len,
            meta_mtime,
            meta_len,
            meta: meta.clone(),
            records: records.clone(),
        });
    }
    Some((meta, records))
}

/// Single-entry cache for the parsed raw transcript. `getSession` is called on
/// every history page (48 rows) and by background reconciliation, so re-reading
/// a multi-megabyte JSONL each time would stall the timeline. The fingerprint
/// (mtime + length) invalidates the entry as soon as a turn is flushed.
struct DisplayTranscriptCache {
    key: String,
    mtime: Option<std::time::SystemTime>,
    len: u64,
    turns: Arc<Vec<jeikcode_capabilities::session::TurnRecord>>,
}

fn display_transcript_cache() -> &'static std::sync::Mutex<Option<DisplayTranscriptCache>> {
    static CACHE: std::sync::OnceLock<std::sync::Mutex<Option<DisplayTranscriptCache>>> =
        std::sync::OnceLock::new();
    CACHE.get_or_init(|| std::sync::Mutex::new(None))
}

/// Read the append-only transcript for display reconstruction, with a
/// fingerprint-guarded single-entry cache. `None` means the transcript cannot
/// be read (no file / corrupt); callers then keep the snapshot-only projection.
fn load_display_transcript(
    project_hash: &str,
    id: &str,
) -> Option<Arc<Vec<jeikcode_capabilities::session::TurnRecord>>> {
    let manager =
        NativeSessionManager::with_root(NativeSessionManager::sessions_root().join(project_hash));
    let path = manager.jsonl_path(id).ok()?;
    let metadata = std::fs::metadata(&path).ok();
    let mtime = metadata.as_ref().and_then(|m| m.modified().ok());
    let len = metadata.as_ref().map(|m| m.len()).unwrap_or(0);
    let key = format!("{project_hash}/{id}");

    let mut guard = display_transcript_cache().lock().ok()?;
    if let Some(cache) = guard.as_ref() {
        if cache.key == key && cache.mtime == mtime && cache.len == len {
            return Some(cache.turns.clone());
        }
    }
    let turns = Arc::new(manager.read_transcript_turns(id).ok()?);
    *guard = Some(DisplayTranscriptCache {
        key,
        mtime,
        len,
        turns: turns.clone(),
    });
    Some(turns)
}

fn normalized_display_text(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// Rebuild display rows for every transcript turn before `boundary`. The raw
/// transcript is never compacted; this is the authoritative pre-compaction
/// display history. Timestamps are intentionally omitted for user rows because
/// `TurnRecord.ts` is the turn's FLUSH time, not the prompt time.
fn display_prefix_from_transcript(
    turns: &[jeikcode_capabilities::session::TurnRecord],
    boundary_ts: Option<u64>,
    boundary_user: Option<&str>,
) -> Vec<MessageInfo> {
    let boundary_text = boundary_user.map(normalized_display_text);
    let split = turns
        .iter()
        .position(|turn| match boundary_ts {
            Some(ts) if ts > 0 => u64::try_from(turn.ts).map(|t| t >= ts).unwrap_or(false),
            _ => boundary_text
                .as_deref()
                .filter(|text| !text.is_empty())
                .is_some_and(|text| {
                    let user = normalized_display_text(&turn.user);
                    !user.is_empty() && (text.starts_with(&user) || user.starts_with(text))
                }),
        })
        .unwrap_or(turns.len());

    const ID_PREFIX: &str = "transcript";
    // Display-only reconstruction: these rows have no kernel counterpart, so
    // mutation APIs (edit/delete/regenerate by array index) must stay disabled.
    const DISPLAY_ORIGIN: &str = "transcript_archive";
    let mut rows = Vec::new();
    for turn in &turns[..split] {
        if !turn.user.trim().is_empty() {
            rows.push(message_info! {
                seq: None,
                turn_id: (turn.turn_id > 0).then_some(turn.turn_id),
                role: "user".into(),
                id: Some(format!("{ID_PREFIX}-{}-user", turn.turn_id)),
                content: turn.user.clone(),
                reasoning: None,
                synthetic: false,
                internal_origin: Some(DISPLAY_ORIGIN.into()),
                tool_calls: None,
                tool_result: None,
                artifacts: None,
                images: None,
                created_at: None,
                elapsed_ms: None,
            });
        }
        let calls: Vec<ToolCallInfo> = turn
            .tools
            .iter()
            .enumerate()
            .map(|(index, tool)| ToolCallInfo {
                id: format!("{ID_PREFIX}-{}-tool-{index}", turn.turn_id),
                name: tool.name.clone(),
                arguments: tool.args.clone(),
                display: format_tool_args(&tool.name, &tool.args),
            })
            .collect();
        let has_tools = !calls.is_empty();
        let has_text = !turn.assistant.trim().is_empty();
        let has_reasoning = !turn.reasoning.trim().is_empty();
        if !has_tools && !has_text && !has_reasoning {
            continue;
        }
        if has_tools {
            // Phase 1: Tool execution message (thinking + tool calls)
            rows.push(message_info! {
                seq: None,
                turn_id: (turn.turn_id > 0).then_some(turn.turn_id),
                role: "assistant".into(),
                id: Some(format!("{ID_PREFIX}-{}-assistant-tools", turn.turn_id)),
                content: String::new(),
                reasoning: has_reasoning.then(|| turn.reasoning.clone()),
                synthetic: false,
                internal_origin: Some(DISPLAY_ORIGIN.into()),
                tool_calls: Some(calls),
                tool_result: None,
                artifacts: None,
                images: None,
                created_at: u64::try_from(turn.ts).ok(),
                elapsed_ms: None,
            });
            for (index, tool) in turn.tools.iter().enumerate() {
                rows.push(message_info! {
                    seq: None,
                    turn_id: (turn.turn_id > 0).then_some(turn.turn_id),
                    role: "tool".into(),
                    id: Some(format!("{ID_PREFIX}-{}-tool-{index}", turn.turn_id)),
                    content: tool.result.clone(),
                    reasoning: None,
                    synthetic: false,
                    internal_origin: Some(DISPLAY_ORIGIN.into()),
                    tool_calls: None,
                    tool_result: Some(ToolResultInfo {
                        call_id: format!("{ID_PREFIX}-{}-tool-{index}", turn.turn_id),
                        success: !tool.is_error,
                        summary: tool_result_summary(&tool.result),
                        line_count: tool.result.lines().count(),
                    }),
                    artifacts: None,
                    images: None,
                    created_at: u64::try_from(turn.ts).ok(),
                    elapsed_ms: None,
                });
            }
            // Phase 2: Final reply message (concluding answer text)
            if has_text {
                rows.push(message_info! {
                    seq: None,
                    turn_id: (turn.turn_id > 0).then_some(turn.turn_id),
                    role: "assistant".into(),
                    id: Some(format!("{ID_PREFIX}-{}-assistant", turn.turn_id)),
                    content: turn.assistant.clone(),
                    reasoning: None,
                    synthetic: false,
                    internal_origin: Some(DISPLAY_ORIGIN.into()),
                    tool_calls: None,
                    tool_result: None,
                    artifacts: None,
                    images: None,
                    created_at: u64::try_from(turn.ts).ok(),
                    elapsed_ms: None,
                });
            }
        } else {
            rows.push(message_info! {
                seq: None,
                turn_id: (turn.turn_id > 0).then_some(turn.turn_id),
                role: "assistant".into(),
                id: Some(format!("{ID_PREFIX}-{}-assistant", turn.turn_id)),
                content: turn.assistant.clone(),
                reasoning: has_reasoning.then(|| turn.reasoning.clone()),
                synthetic: false,
                internal_origin: Some(DISPLAY_ORIGIN.into()),
                tool_calls: None,
                tool_result: None,
                artifacts: None,
                images: None,
                created_at: u64::try_from(turn.ts).ok(),
                elapsed_ms: None,
            });
        }
    }
    rows
}

/// Splice the transcript-rebuilt prefix ahead of the snapshot's retained tail.
/// The compaction anchor itself is model context, not a display row; the real
/// rows before it are covered by the transcript and are dropped to avoid a
/// duplicate "你好啊". Invisible scaffolding and display-only presentation rows
/// are preserved. Tool rows before the anchor are always covered by the prefix.
fn splice_compacted_display(
    mut messages: Vec<MessageInfo>,
    prefix: Vec<MessageInfo>,
) -> Vec<MessageInfo> {
    if prefix.is_empty() {
        return messages;
    }
    let Some(anchor) = messages.iter().position(|m| {
        m.role.eq_ignore_ascii_case("user")
            && m.synthetic
            && jeikcode_capabilities::compaction::is_compaction_anchor_text(&m.content)
    }) else {
        return messages;
    };

    let prefix_users: Vec<String> = prefix
        .iter()
        .filter(|m| m.role.eq_ignore_ascii_case("user"))
        .map(|m| m.content.trim().to_string())
        .filter(|text| !text.is_empty())
        .collect();
    let prefix_assistants: Vec<String> = prefix
        .iter()
        .filter(|m| m.role.eq_ignore_ascii_case("assistant"))
        .map(|m| m.content.trim().to_string())
        .filter(|text| !text.is_empty())
        .collect();

    let (head, rest) = messages.split_at(anchor);
    let tail = rest.get(1..).unwrap_or(&[]);
    let mut out = Vec::with_capacity(prefix.len() + head.len() + tail.len());
    out.extend(prefix);
    for message in head {
        if message.role.eq_ignore_ascii_case("system") || message.synthetic {
            out.push(message.clone());
            continue;
        }
        let text = message.content.trim();
        if message.role.eq_ignore_ascii_case("user")
            && prefix_users.iter().any(|prefix_text| {
                !prefix_text.is_empty()
                    && (text.starts_with(prefix_text.as_str()) || prefix_text.starts_with(text))
            })
        {
            continue;
        }
        if message.role.eq_ignore_ascii_case("assistant")
            && prefix_assistants
                .iter()
                .any(|prefix_text| prefix_text == text)
        {
            continue;
        }
        if message.role.eq_ignore_ascii_case("tool") {
            continue;
        }
        out.push(message.clone());
    }
    out.extend(tail.iter().cloned());
    out
}

/// Full agent-loop duration for each turn's last assistant display record.
/// Compaction preserves full turn durations only for the recent turn stats;
/// older turns keep their per-round `MessageMeta.elapsed_ms`. Returns an index
/// map instead of mutating the cached display records.
fn display_turn_elapsed_overrides(
    records: &[jeikcode_capabilities::session::DisplayRecord],
    stats: &[jeikcode_capabilities::session::TurnStat],
) -> std::collections::HashMap<usize, u64> {
    use std::collections::HashMap;
    let durations: HashMap<u64, u64> = stats
        .iter()
        .filter(|stat| stat.position_valid && stat.turn_id != 0 && stat.duration_ms > 0)
        .map(|stat| (stat.turn_id, stat.duration_ms))
        .collect();
    let mut last_assistant: HashMap<u64, usize> = HashMap::new();
    for (index, record) in records.iter().enumerate() {
        if record.role.eq_ignore_ascii_case("assistant") && record.turn_id != 0 {
            last_assistant.insert(record.turn_id, index);
        }
    }
    last_assistant
        .into_iter()
        .filter_map(|(turn_id, index)| durations.get(&turn_id).map(|duration| (index, *duration)))
        .collect()
}

/// The invisible session-start prefix (system prompts + synthetic instructions)
/// that precedes the first real user turn. A hook-created display log starts at
/// that user, so the read path prepends this prefix to keep `sourceIndex` aligned
/// with the snapshot fallback (old caches, right-rail indices, jump anchors).
fn display_prefix_messages(
    session: &crate::legacy_convert::CatalogSessionView,
) -> Vec<MessageInfo> {
    let working_dir = std::path::Path::new(&session.meta.working_dir);
    let mut out = Vec::new();
    for message in &session.snapshot.messages {
        if message.role == jeikcode_kernel::message::Role::User && !message.synthetic {
            break;
        }
        out.push(MessageInfo::from_kernel_in(message, Some(working_dir)));
    }
    mint_legacy_message_ids(&mut out);
    out
}

/// 跨版本兼容：旧日志（id 字段引入前写入）可能没有 `id`。读取时铸造一个
/// **确定性** id：`m-<turn_id>-<index>`。它稳定、可重复，且永远不会与内核
/// `m-<uuid>` 撞车；于是历史会话无需重写日志就能被新架构按 id 寻址。
fn display_record_identity(record: &jeikcode_capabilities::session::DisplayRecord) -> String {
    record
        .id
        .clone()
        .unwrap_or_else(|| format!("m-{}-{}", record.turn_id, record.index))
}

/// 给没有 id 的旧快照行补确定性 id，保证右栏/编辑/删除在新契约下仍可用。
fn mint_legacy_message_ids(messages: &mut [MessageInfo]) {
    for (index, message) in messages.iter_mut().enumerate() {
        if message.id.is_none() {
            message.id = Some(format!("m-legacy-{index}"));
        }
    }
}

/// Convert one display-log record to the API shape the WebUI/TUI already render.
fn display_record_to_message_info(
    record: &jeikcode_capabilities::session::DisplayRecord,
) -> MessageInfo {
    let mut content = record.content.clone();
    let mut images = (!record.images.is_empty()).then(|| {
        record
            .images
            .iter()
            .map(|image| ImageData {
                media_type: image.media_type.clone(),
                data: image.data.clone(),
                missing: image.missing,
            })
            .collect::<Vec<_>>()
    });
    if record.role.eq_ignore_ascii_case("user") {
        let (display, had_vision_marker) = strip_vision_marker(&content);
        if had_vision_marker {
            content = display;
            if images.is_none() {
                images = Some(vec![ImageData::missing_placeholder()]);
            }
        }
    }
    let tool_calls = (!record.tool_calls.is_empty()).then(|| {
        record
            .tool_calls
            .iter()
            .map(|call| ToolCallInfo {
                id: call.id.clone(),
                name: call.name.clone(),
                arguments: call.arguments.clone(),
                display: format_tool_args(&call.name, &call.arguments),
            })
            .collect::<Vec<_>>()
    });
    let tool_result = record
        .role
        .eq_ignore_ascii_case("tool")
        .then(|| ToolResultInfo {
            call_id: record.tool_call_id.clone().unwrap_or_default(),
            success: !record.is_error,
            summary: tool_result_summary(&record.content),
            line_count: record.content.lines().count(),
        });
    let artifacts = extract_artifacts_from_call_fields(
        record
            .tool_calls
            .iter()
            .map(|call| (call.name.as_str(), call.arguments.as_str())),
    );
    let display_text = record
        .role
        .eq_ignore_ascii_case("user")
        .then(|| content.clone());
    let internal = record.synthetic || record.internal_origin.as_deref() == Some("verify_cadence");
    let editable = record.role.eq_ignore_ascii_case("user").then(|| {
        !record.synthetic
            && !matches!(
                record.internal_origin.as_deref(),
                Some("transcript_archive") | Some("presentation") | Some("pending_input")
            )
    });
    message_info! {
        turn_id: (record.turn_id > 0).then_some(record.turn_id),
        seq: (record.seq > 0).then_some(record.seq),
        role: record.role.clone(),
        id: Some(display_record_identity(record)),
        content,
        reasoning: record.reasoning.clone(),
        synthetic: record.synthetic,
        internal_origin: record.internal_origin.clone(),
        display_text,
        internal: Some(internal),
        editable,
        tool_calls,
        tool_result,
        artifacts,
        images,
        created_at: record.created_at,
        elapsed_ms: record.elapsed_ms,
    }
}

/// Attach the durable client-input id to user rows. A steer has two identities:
/// the client-minted `SessionInput.id` and the kernel `message_id`; the display
/// log only persists the latter, so after a reload a queue card carrying the
/// former could not be recognized as already folded. The durable input ledger
/// is the single source for this mapping; no text matching is needed.
fn client_input_identity_map(
    inputs: impl IntoIterator<Item = jeikcode_capabilities::session::SessionInput>,
) -> std::collections::HashMap<String, String> {
    let mut by_message: std::collections::HashMap<String, String> =
        std::collections::HashMap::new();
    for input in inputs {
        let input_id = input.id;
        // A promoted input has both ids; an admitted one may already be keyed
        // by its client id when it is rendered as a pending row.
        by_message.insert(input_id.clone(), input_id.clone());
        if let Some(message_id) = input.message_id.filter(|id| !id.trim().is_empty()) {
            by_message.insert(message_id, input_id);
        }
    }
    by_message
}

fn annotate_client_input_ids_with(
    messages: &mut [MessageInfo],
    by_message: &std::collections::HashMap<String, String>,
) {
    if by_message.is_empty() {
        return;
    }
    for message in messages {
        if !message.role.eq_ignore_ascii_case("user") {
            continue;
        }
        let Some(id) = message.id.as_deref() else {
            continue;
        };
        if let Some(client_input_id) = by_message.get(id) {
            message.client_input_id = Some(client_input_id.clone());
        }
    }
}

fn annotate_client_input_ids(messages: &mut [MessageInfo], session_id: &str) {
    let inputs = jeikcode_capabilities::session::inputs::list_global(session_id);
    let by_message = client_input_identity_map(inputs);
    annotate_client_input_ids_with(messages, &by_message);
}

/// Mark display-log rows that no longer exist in the kernel snapshot as
/// display-only/read-only. Compaction drains model context while the display
/// log stays append-only; editing such a row by id would return "message not
/// found". The WebUI already renders `transcript_archive` rows as read-only.
fn mark_display_only_archive_rows(
    records: &[jeikcode_capabilities::session::DisplayRecord],
    messages: &mut [MessageInfo],
    snapshot_ids: &std::collections::HashSet<&str>,
    persisted_last_turn: u64,
    mark_latest: bool,
) {
    for (record, message) in records.iter().zip(messages.iter_mut()) {
        // A turn beyond the persisted boundary is ahead of the snapshot; the
        // latest turn may also race a snapshot save. Only mark it when the
        // caller has proved the session is idle and the log is not ahead.
        if record.turn_id > persisted_last_turn {
            continue;
        }
        if record.turn_id == persisted_last_turn && !mark_latest {
            continue;
        }
        if message.internal_origin.is_some() {
            continue;
        }
        let Some(id) = message.id.as_deref() else {
            continue;
        };
        if !snapshot_ids.contains(id) {
            message.internal_origin = Some("transcript_archive".to_string());
        }
    }
}

/// Project an already-computed fallback display list into the append-only log.
/// Used once for old sessions; future turns are written by `DisplayHook`.
fn display_record_from_message_info(
    session_id: &str,
    index: usize,
    message: &MessageInfo,
) -> jeikcode_capabilities::session::DisplayRecord {
    jeikcode_capabilities::session::DisplayRecord {
        v: jeikcode_capabilities::session::DISPLAY_VERSION,
        session_id: session_id.to_string(),
        // Carry the kernel turn identity when the source row knows it (snapshot
        // meta / live display rows). Legacy rows without it stay 0; the WebUI
        // then falls back to steer-root penetration for the timer boundary.
        turn_id: message.turn_id.unwrap_or(0),
        index: u32::try_from(index).unwrap_or(u32::MAX),
        seq: message.seq.unwrap_or(0),
        role: message.role.clone(),
        id: message.id.clone().or_else(|| {
            if message.internal_origin.as_deref() == Some("turn_diagnostic") {
                Some(format!("diag-{}", uuid::Uuid::new_v4()))
            } else if message.role == "system" {
                Some(format!("sys-{}", uuid::Uuid::new_v4()))
            } else {
                Some(format!("msg-{}", uuid::Uuid::new_v4()))
            }
        }),
        content: message.content.clone(),
        reasoning: message.reasoning.clone(),
        synthetic: message.synthetic,
        internal_origin: message.internal_origin.clone(),
        tool_calls: message
            .tool_calls
            .as_ref()
            .map(|calls| {
                calls
                    .iter()
                    .map(|call| jeikcode_capabilities::session::DisplayToolCall {
                        id: call.id.clone(),
                        name: call.name.clone(),
                        arguments: call.arguments.clone(),
                    })
                    .collect()
            })
            .unwrap_or_default(),
        tool_call_id: message
            .tool_result
            .as_ref()
            .map(|result| result.call_id.clone()),
        is_error: message
            .tool_result
            .as_ref()
            .is_some_and(|result| !result.success),
        images: message
            .images
            .as_ref()
            .map(|images| {
                images
                    .iter()
                    .map(|image| jeikcode_capabilities::session::DisplayImage {
                        media_type: image.media_type.clone(),
                        data: image.data.clone(),
                        missing: image.missing,
                    })
                    .collect()
            })
            .unwrap_or_default(),
        created_at: message.created_at,
        elapsed_ms: message.elapsed_ms,
    }
}

pub(crate) enum DisplayMutation<'a> {
    Patch {
        target_id: Option<&'a str>,
        text: &'a str,
        images: &'a [ImageData],
        truncate_after: bool,
    },
    Truncate {
        target_id: Option<&'a str>,
        inclusive: bool,
    },
    Delete {
        target_id: Option<&'a str>,
        delete_turn: bool,
    },
}

/// Rewrite the v4 log in place for an explicit mutation, preserving every row
/// before the target (including display-only/presentation rows that are absent
/// from the model snapshot). Falls back to invalidation + canonical rebuild only
/// when the v4 log or the target identity is unavailable.
pub(crate) fn rewrite_display_for_mutation(
    manager: &NativeSessionManager,
    id: &str,
    mutation: DisplayMutation<'_>,
    last_turn_id: u64,
    completed_turns: &[u64],
) -> bool {
    let Some((_meta, mut records)) = manager.read_display(id).ok().flatten() else {
        return false;
    };
    let target_id = match &mutation {
        DisplayMutation::Patch { target_id, .. }
        | DisplayMutation::Truncate { target_id, .. }
        | DisplayMutation::Delete { target_id, .. } => *target_id,
    };
    let Some(target_id) = target_id else {
        return false;
    };
    let Some(idx) = records
        .iter()
        .position(|record| record.id.as_deref() == Some(target_id))
    else {
        return false;
    };
    match mutation {
        DisplayMutation::Patch {
            text,
            images,
            truncate_after,
            ..
        } => {
            if truncate_after {
                let target_turn = records[idx].turn_id;
                let presentation_tail: Vec<_> = records[idx + 1..]
                    .iter()
                    .filter(|record| {
                        record.turn_id == target_turn
                            && record.internal_origin.as_deref() == Some("presentation")
                    })
                    .cloned()
                    .collect();
                records.truncate(idx + 1);
                records.extend(presentation_tail);
            }
            if let Some(record) = records.get_mut(idx) {
                record.content = text.to_string();
                record.images = images
                    .iter()
                    .map(|image| jeikcode_capabilities::session::DisplayImage {
                        media_type: image.media_type.clone(),
                        data: image.data.clone(),
                        missing: image.missing,
                    })
                    .collect();
            }
        }
        DisplayMutation::Truncate { inclusive, .. } => {
            // `inclusive=false` means “remove the target and everything after it”;
            // keep ends at the target. `inclusive=true` keeps the target itself.
            let keep = if inclusive { idx + 1 } else { idx };
            let target_turn = records[idx].turn_id;
            // Presentation-only rows belong to the turn; keep them only when the
            // target row itself survives (inclusive truncate). An exclusive
            // rewind removes the whole target turn, including its display rows.
            let presentation_tail: Vec<_> = if inclusive {
                records[keep..]
                    .iter()
                    .filter(|record| {
                        record.turn_id == target_turn
                            && record.internal_origin.as_deref() == Some("presentation")
                    })
                    .cloned()
                    .collect()
            } else {
                Vec::new()
            };
            records.truncate(keep);
            records.extend(presentation_tail);
        }
        DisplayMutation::Delete { delete_turn, .. } => {
            let is_user = records[idx].role.eq_ignore_ascii_case("user");
            if delete_turn {
                let end = records
                    .iter()
                    .enumerate()
                    .skip(idx + 1)
                    .find(|(_, record)| {
                        record.role.eq_ignore_ascii_case("user") && !record.synthetic
                    })
                    .map(|(index, _)| index)
                    .unwrap_or(records.len());
                records.drain(idx..end);
            } else if !is_user {
                // Assistant/tool delete keeps the preceding user row and removes
                // the whole agent run up to the next user turn.
                let start = records[..idx]
                    .iter()
                    .rposition(|record| record.role.eq_ignore_ascii_case("user"))
                    .map(|position| position + 1)
                    .unwrap_or(0);
                let end = records
                    .iter()
                    .enumerate()
                    .skip(idx + 1)
                    .find(|(_, record)| {
                        record.role.eq_ignore_ascii_case("user") && !record.synthetic
                    })
                    .map(|(index, _)| index)
                    .unwrap_or(records.len());
                records.drain(start..end);
            } else {
                records.remove(idx);
            }
        }
    }
    manager
        .rewrite_display_rows(id, &records, last_turn_id, completed_turns, false)
        .is_ok()
}

fn merge_catalog_session_messages_for_display(
    session: &crate::legacy_convert::CatalogSessionView,
) -> anyhow::Result<Vec<MessageInfo>> {
    use jeikcode_capabilities::session::{DisplayAnchor, PresentationRole};

    let runtime_messages: Vec<_> = session
        .snapshot
        .messages
        .iter()
        .filter(|message| {
            message.internal_origin.as_deref()
                != Some(jeikcode_kernel::message::LEGACY_COLD_SUMMARY_ORIGIN)
                && !jeikcode_capabilities::reminder::is_system_reminder(&message.text)
        })
        .collect();
    let mut presentation = std::collections::BTreeMap::<usize, Vec<_>>::new();
    for entry in &session.presentation.entries {
        let after_message = match entry.anchor {
            DisplayAnchor::AtStart => 0,
            DisplayAnchor::AfterTurn { turn_id } => session
                .meta
                .turn_stats
                .iter()
                .find(|stat| stat.position_valid && stat.turn_id == turn_id)
                .map(|stat| stat.after_message)
                .ok_or_else(|| {
                    anyhow::anyhow!("presentation references missing turn id {turn_id}")
                })?,
        };
        presentation.entry(after_message).or_default().push(entry);
    }
    let working_dir = std::path::Path::new(&session.meta.working_dir);
    let mut messages =
        Vec::with_capacity(runtime_messages.len() + session.presentation.entries.len());
    let unwrap_presentation_text = |role: PresentationRole, text: &str| -> String {
        if role == PresentationRole::User {
            jeikcode_capabilities::session::user_text_for_display(working_dir, text)
        } else {
            text.to_string()
        }
    };
    let mut append_presentation = |position: usize, messages: &mut Vec<MessageInfo>| {
        for entry in presentation.remove(&position).unwrap_or_default() {
            if jeikcode_capabilities::reminder::is_system_reminder(&entry.text) {
                continue;
            }
            messages.push(message_info! {
                turn_id: None,
                seq: None,
                role: match entry.role {
                    PresentationRole::User => "user",
                    PresentationRole::Assistant => "assistant",
                }
                .into(),
                id: None,
                content: unwrap_presentation_text(entry.role, &entry.text),
                reasoning: None,
                synthetic: false,
                internal_origin: Some("presentation".into()),
                tool_calls: None,
                tool_result: None,
                artifacts: None,
                images: None,
                created_at: None,
                elapsed_ms: None,
            });
        }
    };
    append_presentation(0, &mut messages);
    for (index, message) in runtime_messages.into_iter().enumerate() {
        let info = MessageInfo::from_kernel_in(message, Some(working_dir));
        messages.push(info);
        append_presentation(index + 1, &mut messages);
    }
    for (_, entries) in presentation {
        for entry in entries {
            if jeikcode_capabilities::reminder::is_system_reminder(&entry.text) {
                continue;
            }
            messages.push(message_info! {
                turn_id: None,
                seq: None,
                role: match entry.role {
                    PresentationRole::User => "user",
                    PresentationRole::Assistant => "assistant",
                }
                .into(),
                id: None,
                content: unwrap_presentation_text(entry.role, &entry.text),
                reasoning: None,
                synthetic: false,
                internal_origin: Some("presentation".into()),
                tool_calls: None,
                tool_result: None,
                artifacts: None,
                images: None,
                created_at: None,
                elapsed_ms: None,
            });
        }
    }
    // 缺时间的行（tool 结果 / system / 展示条目）继承**上一条**已知时间，
    // 绝不能拿会话 `updated_at`（≈ 现在）当戳：那会让这些行声称比它后面的
    // 助手正文更晚发布，界面就会出现“最后一次回复的时间比上一次还早”的倒流。
    fill_missing_display_clock(
        &mut messages,
        u64::try_from(session.meta.created_at.max(0)).unwrap_or(0),
    );
    // Re-attach display-only images (VL-preprocessed originals) stashed out of band, so a
    // reloaded session shows the thumbnail instead of the "missing image" placeholder.
    attach_display_images(
        &mut messages,
        std::path::Path::new(&session.meta.working_dir),
        &session.meta.id,
    );
    stamp_turn_elapsed_on_last_assistants(&mut messages, &session.meta.turn_stats);
    Ok(messages)
}

/// 按行序补齐缺失的展示时间戳：缺时间的行继承**上一条**已知时间。
///
/// 行序就是时间序，所以继承前一条是安全的；用会话 `updated_at`（≈ 写入时刻）
/// 补洞则会让旧行的时刻晚于它后面的正文，界面上表现为时间倒流。
fn fill_missing_display_clock(messages: &mut [MessageInfo], seed: u64) {
    let mut clock = seed;
    for message in messages.iter_mut() {
        match message.created_at {
            Some(ts) => clock = ts,
            None => message.created_at = Some(clock),
        }
    }
}

/// 展示时间戳校准：把旧版本已落盘、比下一行还晚的伪造时间拉回行序。
///
/// 转录行序本身就是时间序，所以只做「向下拉平」：一个比下一行更晚的时刻只可能
/// 来自旧版本用会话 `updated_at` 补洞的伪造值（注入提示的 user 行也会命中）。
fn repair_display_clock(messages: &mut [MessageInfo]) {
    let mut next_known: Option<u64> = None;
    for message in messages.iter_mut().rev() {
        match message.created_at {
            Some(ts) => {
                let repaired = match next_known {
                    Some(next) if ts > next => next,
                    _ => ts,
                };
                message.created_at = Some(repaired);
                next_known = Some(repaired);
            }
            None => {
                if let Some(next) = next_known {
                    message.created_at = Some(next);
                }
            }
        }
    }
}

/// GET /sessions - List all sessions across all projects
async fn get_all_sessions() -> impl IntoResponse {
    match run_session_catalog_io(list_all_sessions).await {
        Ok(sessions) => Json(sessions).into_response(),
        Err(e) => {
            let msg = format!("Failed to list sessions: {}", e);
            (StatusCode::INTERNAL_SERVER_ERROR, Json(msg)).into_response()
        }
    }
}

/// POST /sessions - Create a new session
async fn create_session(
    State(state): State<AppState>,
    Json(req): Json<CreateSessionRequest>,
) -> impl IntoResponse {
    // Determine working directory
    let mut working_dir = match req.working_dir {
        Some(dir) => {
            let mut proj = state.project.write().await;
            update_project_state(&mut proj, &dir);
            dir
        }
        None => {
            // Use current project's working directory
            let project = state.project.read().await;
            project.working_dir.clone()
        }
    };

    // Ensure working directory exists
    if !working_dir.exists() {
        // Create jeikchat directory in user's home if default
        let home = jeikcode_config::util::real_home_dir().unwrap_or_else(|| PathBuf::from("."));
        let jeikchat_dir = home.join("jeikchat");
        if jeikchat_dir.exists() || std::fs::create_dir_all(&jeikchat_dir).is_ok() {
            working_dir = jeikchat_dir;
        } else {
            let msg = format!("Working directory does not exist: {:?}", working_dir);
            return (StatusCode::BAD_REQUEST, Json(msg)).into_response();
        }
    }

    let id = uuid::Uuid::new_v4().to_string();
    let now = jeikcode_capabilities::session::now_ms();
    let mut meta =
        jeikcode_capabilities::session::SessionMeta::new(&id, working_dir.to_string_lossy(), now);
    meta.owner = jeikcode_capabilities::session::StorageOwner::Native;
    if let Some(title) = req.title {
        meta.name = title;
        meta.user_renamed = true;
    }
    // OpenCode-style draft: allocate identity without writing an empty catalog row.
    // The first real user Submit (via CodingRuntime staged publish) persists it.
    crate::native_live::register_session_draft(id.clone(), working_dir.clone());

    let project_hash = response_project_hash(&working_dir);

    let response = CreateSessionResponse {
        id: id.clone(),
        name: meta.name.clone(),
        working_dir: working_dir.clone(),
        project_hash,
        created_at: u64::try_from(meta.created_at.max(0)).unwrap_or(0) / 1_000,
    };

    (StatusCode::CREATED, Json(response)).into_response()
}

/// POST /sessions/:id/messages - Append externally handled, UI-only messages.
async fn append_session_messages(
    State(state): State<AppState>,
    Path(session_id): Path<String>,
    Json(req): Json<AppendSessionMessagesRequest>,
) -> impl IntoResponse {
    let working_dir = match req.working_dir {
        Some(dir) => dir,
        None => {
            let project = state.project.read().await;
            project.working_dir.clone()
        }
    };

    let mut messages = Vec::with_capacity(req.messages.len());
    for msg in req.messages {
        let role = match msg.role.to_ascii_lowercase().as_str() {
            "user" => jeikcode_capabilities::session::PresentationRole::User,
            "assistant" => jeikcode_capabilities::session::PresentationRole::Assistant,
            _ => {
                let err = format!("Unsupported message role: {}", msg.role);
                return (StatusCode::BAD_REQUEST, Json(err)).into_response();
            }
        };
        messages.push((role, msg.content));
    }

    let project_hash = response_project_hash(&working_dir);
    let client_request_id = req
        .client_request_id
        .as_deref()
        .map(str::trim)
        .filter(|key| {
            !key.is_empty()
                && key.len() <= 128
                && key
                    .chars()
                    .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.'))
        });
    let message_count = match crate::legacy_convert::append_catalog_presentation_in_project(
        &project_hash,
        &session_id,
        &messages,
        client_request_id,
    ) {
        Ok(count) => count,
        Err(error) => {
            let msg = format!("Failed to save session: {error}");
            return (StatusCode::INTERNAL_SERVER_ERROR, Json(msg)).into_response();
        }
    };

    // The manager writes UI-only presentation rows into the v4 display log at
    // the anchor turn (or invalidates it itself when the anchor is legacy).

    let response = AppendSessionMessagesResponse {
        success: true,
        session_id,
        message_count,
        project_hash,
    };

    (StatusCode::OK, Json(response)).into_response()
}

/// Search sessions by name across all projects
fn search_sessions_by_name(keyword: &str) -> std::io::Result<Vec<SessionMetaWithProject>> {
    search_sessions_by_name_in_root(&NativeSessionManager::sessions_root(), keyword)
}

fn search_sessions_by_name_in_root(
    sessions_root: &std::path::Path,
    keyword: &str,
) -> std::io::Result<Vec<SessionMetaWithProject>> {
    let keyword_lower = keyword.to_lowercase();
    let mut entries: Vec<_> = catalog_scan_in_root(sessions_root)?
        .entries
        .into_iter()
        .filter(|entry| entry.message_count > 0)
        .collect();
    crate::legacy_convert::repair_catalog_names_for_display_in_root(sessions_root, &mut entries);
    Ok(entries
        .iter()
        .filter(|entry| {
            entry.name.to_lowercase().contains(&keyword_lower)
                || entry
                    .working_dir
                    .to_string_lossy()
                    .to_lowercase()
                    .contains(&keyword_lower)
                || entry.id.to_lowercase().starts_with(&keyword_lower)
        })
        .map(catalog_entry_with_project)
        .collect())
}

/// GET /sessions/search?q=keyword - Search sessions by name
async fn search_sessions(Query(query): Query<SearchQuery>) -> impl IntoResponse {
    if query.q.trim().is_empty() {
        return (
            StatusCode::BAD_REQUEST,
            Json("Search keyword cannot be empty"),
        )
            .into_response();
    }

    let keyword = query.q;
    match run_session_catalog_io(move || search_sessions_by_name(&keyword)).await {
        Ok(sessions) => Json(sessions).into_response(),
        Err(e) => {
            let msg = format!("Failed to search sessions: {}", e);
            (StatusCode::INTERNAL_SERVER_ERROR, Json(msg)).into_response()
        }
    }
}

/// Delete one inactive session aggregate.
///
/// Keep the typed storage error in the anyhow chain: the HTTP boundary must
/// distinguish an active lease (`409`) from missing data (`404`) and an
/// unexpected storage failure (`500`). Flattening everything into
/// `io::Error::other` made that distinction impossible.
fn delete_session_file(project_hash: &str, session_id: &str) -> anyhow::Result<()> {
    crate::legacy_convert::delete_catalog_session_in_project(project_hash, session_id)?;
    // 跨实例增量：删行 + 让客户端丢弃该 id 的本地缓存。
    publish_global(GlobalWireEvent::SessionDeleted {
        session_id: session_id.to_string(),
        project_hash: project_hash.to_string(),
    });
    Ok(())
}

fn valid_project_bucket(project_bucket: &str) -> bool {
    project_bucket.len() == 16 && project_bucket.bytes().all(|byte| byte.is_ascii_hexdigit())
}

fn delete_session_api_error(
    status: StatusCode,
    code: &'static str,
    message: &'static str,
) -> (StatusCode, Json<ApiError>) {
    (
        status,
        Json(ApiError {
            success: false,
            error: message.to_string(),
            code: Some(code.to_string()),
            retryable: Some(false),
        }),
    )
}

fn classify_delete_session_error(error: &anyhow::Error) -> (StatusCode, Json<ApiError>) {
    match error.downcast_ref::<SessionStoreError>() {
        Some(SessionStoreError::SessionInUse { .. }) => delete_session_api_error(
            StatusCode::CONFLICT,
            "SESSION_IN_USE",
            "This session is active. Switch to or create another session, then try again.",
        ),
        Some(SessionStoreError::NotFound { .. }) => delete_session_api_error(
            StatusCode::NOT_FOUND,
            "SESSION_NOT_FOUND",
            "The session was not found.",
        ),
        Some(SessionStoreError::InvalidId { .. } | SessionStoreError::AmbiguousId { .. }) => {
            delete_session_api_error(
                StatusCode::BAD_REQUEST,
                "INVALID_SESSION",
                "The session identifier is invalid.",
            )
        }
        _ => delete_session_api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "DELETE_FAILED",
            "Failed to delete the session. Check the JeikCode logs for details.",
        ),
    }
}

#[derive(Debug, Default, Deserialize)]
pub struct RepairSessionRequest {
    #[serde(default)]
    pub apply: bool,
}

#[derive(Debug, Serialize)]
pub struct RepairSessionResponse {
    pub success: bool,
    pub status: &'static str,
    pub applied: bool,
    pub metadata: &'static str,
    pub snapshot: &'static str,
    pub presentation: &'static str,
    pub transcript: &'static str,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub message_count: Option<usize>,
}

fn transcript_state(manager: &NativeSessionManager, id: &str) -> &'static str {
    let Ok(path) = manager.jsonl_path(id) else {
        return "invalid";
    };
    match std::fs::symlink_metadata(path) {
        Ok(metadata) if !metadata.file_type().is_file() => "unsafe",
        Ok(metadata) if metadata.len() == 0 => "empty",
        Ok(_) => "present",
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => "missing",
        Err(_) => "unreadable",
    }
}

fn repair_session_file(
    project_hash: &str,
    session_id: &str,
    apply: bool,
) -> Result<RepairSessionResponse, RepairSessionFailure> {
    let manager =
        NativeSessionManager::with_root(NativeSessionManager::sessions_root().join(project_hash));
    repair_session_with_manager(&manager, session_id, apply).map_err(|error| RepairSessionFailure {
        transcript: transcript_state(&manager, session_id),
        error,
    })
}

#[derive(Debug)]
struct RepairSessionFailure {
    error: SessionStoreError,
    transcript: &'static str,
}

fn repair_session_with_manager(
    manager: &NativeSessionManager,
    session_id: &str,
    apply: bool,
) -> Result<RepairSessionResponse, SessionStoreError> {
    let lease = manager.acquire_lease(session_id)?;
    let outcome = manager.repair_missing_presentation(&lease, apply)?;
    let transcript = transcript_state(manager, session_id);
    use jeikcode_capabilities::session::NativeSessionRepairOutcome as Outcome;
    let (status, applied, presentation, message_count) = match outcome {
        Outcome::Healthy(session) => ("healthy", false, "valid", session.snapshot.messages.len()),
        Outcome::RepairableMissingPresentation { snapshot, .. } => (
            "repairable_missing_presentation",
            false,
            "missing",
            snapshot.messages.len(),
        ),
        Outcome::Repaired(session) => ("repaired", true, "valid", session.snapshot.messages.len()),
    };
    Ok(RepairSessionResponse {
        success: true,
        status,
        applied,
        metadata: "valid",
        snapshot: "valid",
        presentation,
        transcript,
        message_count: Some(message_count),
    })
}

fn repair_artifact_kind(error: &SessionStoreError) -> Option<(&'static str, &'static str)> {
    fn normalize(kind: &str) -> Option<&'static str> {
        if matches!(kind, "session meta" | "meta turn stats" | "metadata") {
            Some("metadata")
        } else if kind.starts_with("snapshot") {
            Some("snapshot")
        } else if kind.starts_with("presentation") {
            Some("presentation")
        } else {
            None
        }
    }

    match error {
        SessionStoreError::NotFound { path } => match path.extension().and_then(|ext| ext.to_str())
        {
            Some("snapshot") => Some(("snapshot", "missing")),
            Some("presentation") => Some(("presentation", "missing")),
            _ => None,
        },
        SessionStoreError::Corrupt { kind, .. } => normalize(kind).map(|kind| (kind, "corrupt")),
        SessionStoreError::FutureSchema { kind, .. } => {
            normalize(kind).map(|kind| (kind, "future_schema"))
        }
        SessionStoreError::TooLarge { kind, .. } => normalize(kind).map(|kind| (kind, "too_large")),
        SessionStoreError::UnsafeFile { path, .. } => {
            match path.extension().and_then(|ext| ext.to_str()) {
                Some("meta") => Some(("metadata", "unsafe")),
                Some("snapshot") => Some(("snapshot", "unsafe")),
                Some("presentation") => Some(("presentation", "unsafe")),
                _ => None,
            }
        }
        SessionStoreError::OwnershipConflict { .. } => Some(("metadata", "non_native_owner")),
        _ => None,
    }
}

fn not_repairable_response(
    artifact: &'static str,
    state: &'static str,
    transcript: &'static str,
) -> RepairSessionResponse {
    let mut response = RepairSessionResponse {
        success: false,
        status: "not_repairable",
        applied: false,
        metadata: "valid",
        snapshot: "valid",
        presentation: "valid",
        transcript,
        message_count: None,
    };
    match artifact {
        "metadata" | "meta" => {
            response.metadata = state;
            response.snapshot = "unchecked";
            response.presentation = "unchecked";
        }
        "snapshot" => {
            response.snapshot = state;
            response.presentation = "unchecked";
        }
        "presentation" => response.presentation = state,
        _ => {
            response.metadata = "unchecked";
            response.snapshot = "unchecked";
            response.presentation = "unchecked";
        }
    }
    response
}

fn classify_repair_session_error(
    error: &SessionStoreError,
    transcript: &'static str,
) -> axum::response::Response {
    match error {
        SessionStoreError::SessionInUse { .. } => delete_session_api_error(
            StatusCode::CONFLICT,
            "SESSION_IN_USE",
            "This session is active. Switch to or create another session, then try again.",
        )
        .into_response(),
        SessionStoreError::NotFound { path }
            if path.extension().and_then(|ext| ext.to_str()) == Some("meta") =>
        {
            delete_session_api_error(
                StatusCode::NOT_FOUND,
                "SESSION_NOT_FOUND",
                "The session metadata was not found.",
            )
            .into_response()
        }
        SessionStoreError::InvalidId { .. } | SessionStoreError::AmbiguousId { .. } => {
            delete_session_api_error(
                StatusCode::BAD_REQUEST,
                "INVALID_SESSION",
                "The project or session identifier is invalid.",
            )
            .into_response()
        }
        _ if repair_artifact_kind(error).is_some() => {
            let (artifact, state) = repair_artifact_kind(error).expect("guarded above");
            (
                StatusCode::UNPROCESSABLE_ENTITY,
                Json(not_repairable_response(artifact, state, transcript)),
            )
                .into_response()
        }
        _ => delete_session_api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "REPAIR_FAILED",
            "Failed to inspect or repair the session. Check the JeikCode logs for details.",
        )
        .into_response(),
    }
}

/// POST /projects/:hash/sessions/:id/repair - Inspect or explicitly repair a session.
async fn repair_session(
    Path((hash, id)): Path<(String, String)>,
    Json(request): Json<RepairSessionRequest>,
) -> impl IntoResponse {
    if !valid_project_bucket(&hash) {
        return delete_session_api_error(
            StatusCode::BAD_REQUEST,
            "INVALID_SESSION",
            "The project or session identifier is invalid.",
        )
        .into_response();
    }
    let task = tokio::task::spawn_blocking(move || repair_session_file(&hash, &id, request.apply));
    match task.await {
        Ok(Ok(response)) => (StatusCode::OK, Json(response)).into_response(),
        Ok(Err(failure)) => {
            tracing::warn!(error = %failure.error, "session repair was rejected");
            classify_repair_session_error(&failure.error, failure.transcript)
        }
        Err(error) => {
            tracing::error!(error = %error, "session repair task failed");
            delete_session_api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "REPAIR_FAILED",
                "Failed to inspect or repair the session. Check the JeikCode logs for details.",
            )
            .into_response()
        }
    }
}

/// DELETE /projects/:hash/sessions/:id - Delete a session
async fn delete_session(
    State(state): State<AppState>,
    axum::Extension(client_mode): axum::Extension<SessionMode>,
    Path((hash, id)): Path<(String, String)>,
) -> impl IntoResponse {
    let session_uuid = uuid::Uuid::parse_str(&id).ok();
    let state_clone = state.clone();
    daemon_scope(&state, session_uuid, client_mode, || async move {
        if !valid_project_bucket(&hash) {
            tracing::warn!(project_bucket = %hash, "rejected invalid session delete request");
            return delete_session_api_error(
                StatusCode::BAD_REQUEST,
                "INVALID_SESSION",
                "The project or session identifier is invalid.",
            )
            .into_response();
        }
        // ViewBinding (WebUI/TUI 正在看哪个会话) is not ownership. Release the
        // idle execution runtime or registry runner that actually holds the
        // lease. Active turns stay fail-closed as SESSION_IN_USE.
        match crate::native_live::release_idle_session_for_delete(&id).await {
            Ok(()) => {}
            Err(crate::live_hub::HubError::ActiveTurn) => {
                return delete_session_api_error(
                    StatusCode::CONFLICT,
                    "SESSION_IN_USE",
                    "This session has an active turn. Stop it, then try again.",
                )
                .into_response();
            }
            Err(crate::live_hub::HubError::StaleBinding)
            | Err(crate::live_hub::HubError::RuntimeGenerationChanged { .. })
            | Err(crate::live_hub::HubError::Unbound) => {}
            Err(error) => {
                tracing::warn!(
                    project_bucket = %hash,
                    session_id = %id,
                    error = ?error,
                    "failed to release current session before delete"
                );
                return delete_session_api_error(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "DELETE_FAILED",
                    "Failed to release the current session before deleting it.",
                )
                .into_response();
            }
        }

        let delete_hash = hash.clone();
        let delete_id = id.clone();
        let deleted =
            tokio::task::spawn_blocking(move || delete_session_file(&delete_hash, &delete_id))
                .await;
        match deleted {
            Ok(Ok(())) => {
                // Global sidecars are session-id keyed and are not under the
                // project bucket; delete them with the session.
                jeikcode_capabilities::session::inputs::clear_global(&id);
                jeikcode_capabilities::session::partial::clear_global(&id);
                let working_dir = state_clone.project.read().await.working_dir.clone();
                let id_for_cleanup = id.clone();
                let active_chats_cleanup = state_clone.active_chats.clone();
                // Session files are already gone. Reap MCP, kill session background tasks,
                // and clean up session background log files asynchronously.
                tokio::spawn(async move {
                    let pool = jeikcode_capabilities::mcp::SessionMcpPool::global();
                    pool.retire_session(&working_dir, &id_for_cleanup).await;
                    pool.retire_session_id(&id_for_cleanup).await;

                    // Cascade terminate all background services owned by this session
                    jeikcode_capabilities::tools::bash_runtime::kill_by_session_id(&id_for_cleanup);

                    // Delete all ephemeral log files matching jeikcode-back-{session_id}-*.log
                    jeikcode_capabilities::tools::cleanup_session_logs(&id_for_cleanup).await;

                    // Release session-scoped approval mode override
                    crate::live_api::live_clear_session_approval_mode(&id_for_cleanup);

                    // Clean up active chat registry state (session seq, terminal frames, standby watchers)
                    active_chats_cleanup.clear_session(&id_for_cleanup).await;
                });
                state_clone.telemetry.track(Event::UseCommand {
                    type_: "delete_session".into(),
                    success: Some(true),
                    error_kind: None,
                    error_data: None,
                });
                let msg = format!("Session {} deleted successfully", id);
                (StatusCode::OK, Json(msg)).into_response()
            }
            Ok(Err(e)) => {
                let response = classify_delete_session_error(&e);
                if response.0 == StatusCode::INTERNAL_SERVER_ERROR {
                    tracing::error!(
                        project_bucket = %hash,
                        session_id = %id,
                        error = ?e,
                        "failed to delete session"
                    );
                }
                response.into_response()
            }
            Err(error) => {
                tracing::error!(
                    project_bucket = %hash,
                    session_id = %id,
                    error = %error,
                    "session delete task failed"
                );
                delete_session_api_error(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "DELETE_FAILED",
                    "Failed to delete the session. Check the JeikCode logs for details.",
                )
                .into_response()
            }
        }
    })
    .await
}

/// Rename request body
#[derive(Debug, Deserialize)]
pub struct RenameRequest {
    pub name: String,
}

/// Rename a session
fn rename_session_file(
    project_hash: &str,
    session_id: &str,
    new_name: &str,
) -> std::io::Result<()> {
    crate::legacy_convert::rename_catalog_session_in_project(project_hash, session_id, new_name)
        .map(|_| ())
        .map_err(std::io::Error::other)?;
    // 跨实例增量：就地 upsert 该行（改名 + updated_at），不重拉列表。
    if let Some(session) = session_row_wire_in_bucket(project_hash, session_id) {
        publish_global(GlobalWireEvent::SessionUpsert { session });
    }
    Ok(())
}

/// PATCH /projects/:hash/sessions/:id/rename - Rename a session
async fn rename_session(
    State(state): State<AppState>,
    axum::Extension(client_mode): axum::Extension<SessionMode>,
    Path((hash, id)): Path<(String, String)>,
    Json(req): Json<RenameRequest>,
) -> impl IntoResponse {
    let session_uuid = uuid::Uuid::parse_str(&id).ok();
    let state_clone = state.clone();
    daemon_scope(&state, session_uuid, client_mode, || async move {
        match rename_session_file(&hash, &id, &req.name) {
            Ok(()) => {
                state_clone.telemetry.track(Event::UseCommand {
                    type_: "rename".into(),
                    success: Some(true),
                    error_kind: None,
                    error_data: None,
                });
                let msg = format!("Session {} renamed to '{}'", id, req.name);
                (StatusCode::OK, Json(msg)).into_response()
            }
            Err(e) => {
                let msg = format!("Failed to rename session: {}", e);
                (StatusCode::NOT_FOUND, Json(msg)).into_response()
            }
        }
    })
    .await
}

